function companyInsightTeaser(report, lang) {
  if (!report) return "";
  const rows = Object.values(report.replacement_blocks || {}).flatMap((items) => Array.isArray(items) ? items : []);
  const candidates = ["revenue", "operating_income", "net_income"];
  const labels = {
    revenue: ["выручка", "tushum", "revenue"],
    operating_income: ["операционная прибыль", "operatsion foyda", "operating profit"],
    net_income: ["чистая прибыль", "sof foyda", "net profit"],
  };
  const languageIndex = lang === "uz" ? 1 : lang === "en" ? 2 : 0;
  const comparable = candidates.map((code) => rows.find((row) => row.metric_code === code))
    .filter((row) => Number.isFinite(Number(row?.change_pct)))
    .slice(0, 2);
  if (comparable.length) {
    const movement = Object.fromEntries(comparable.map((row) => [row.metric_code, Number(row.change_pct)]));
    let thesis;
    if (movement.revenue > 0 && (movement.operating_income < 0 || movement.net_income < 0)) {
      if (movement.operating_income < 0) {
        thesis = [
          "рост выручки при падении операционной прибыли указывает на сжатие маржи и ухудшение эффективности",
          "tushum o‘sib, operatsion foyda pasayishi marja qisqarishi va samaradorlik yomonlashganini ko‘rsatadi",
          "revenue growth alongside falling operating profit indicates margin compression and weaker efficiency",
        ][languageIndex];
      } else {
        thesis = [
          "рост выручки при падении чистой прибыли указывает на снижение чистой маржи и качества результата",
          "tushum o‘sib, sof foyda pasayishi sof marja va natija sifati yomonlashganini ko‘rsatadi",
          "revenue growth alongside falling net profit indicates lower net margins and weaker earnings quality",
        ][languageIndex];
      }
    } else if (comparable.length >= 2 && comparable.every((row) => Number(row.change_pct) >= 0)) {
      thesis = [
        "доходы и прибыль растут — финансовая динамика положительная",
        "daromad va foyda o‘smoqda — moliyaviy dinamika ijobiy",
        "income and profit are growing — financial momentum is positive",
      ][languageIndex];
    } else if (comparable.length >= 2 && comparable.every((row) => Number(row.change_pct) < 0)) {
      thesis = [
        "доходы и прибыль снижаются — финансовые результаты ослабевают",
        "daromad va foyda pasaymoqda — moliyaviy natijalar zaiflashmoqda",
        "income and profit are declining — financial performance is weakening",
      ][languageIndex];
    } else if (comparable.length >= 2) {
      thesis = [
        "ключевые показатели разнонаправленные — устойчивого улучшения пока нет",
        "asosiy ko‘rsatkichlar turli yo‘nalishda — barqaror yaxshilanish hali yo‘q",
        "key metrics are mixed — there is no sustained improvement yet",
      ][languageIndex];
    } else {
      const row = comparable[0];
      const labelText = labels[row.metric_code][languageIndex];
      const rising = Number(row.change_pct) >= 0;
      thesis = [
        `${labelText} ${rising ? "растёт" : "снижается"} — это главный подтверждённый сигнал периода`,
        `${labelText} ${rising ? "o‘smoqda" : "pasaymoqda"} — bu davrning asosiy tasdiqlangan signali`,
        `${labelText} is ${rising ? "growing" : "declining"} — the period’s main verified signal`,
      ][languageIndex];
    }
    const detailedTeaser = `${report.issuer?.ticker || ""}: ${thesis}.`.trim();
    const detailedWords = detailedTeaser.split(/\s+/).filter(Boolean);
    return detailedWords.length > 18
      ? `${detailedWords.slice(0, 18).join(" ").replace(/[\s,;:]+$/, "")}…`
      : detailedTeaser;
  }
  const teaser = report.card_text || report.short_summary || report.headline || "";
  const words = String(teaser).trim().split(/\s+/).filter(Boolean);
  return words.length > 22 ? `${words.slice(0, 22).join(" ").replace(/[\s,;:]+$/, "")}…` : teaser;
}

function CompanyInsightCard({ report, loading, error, onOpen, onRetry, buttonRef, lang }) {
  const tx = COMPANY_INSIGHT_TX[lang] || COMPANY_INSIGHT_TX.ru;
  const teaser = companyInsightTeaser(report, lang);
  return (
    <section className={`company-insight-card tone-${report?.headline_tone || "neutral"}`} data-testid="company-insight-card" aria-live="polite" aria-busy={loading ? "true" : "false"}>
      <CompanyInsightIcon />
      <div className="company-insight-card-copy">
        {loading ? (
          <div className="company-insight-loading" aria-label={tx.loading}><span /><span /></div>
        ) : report?.status && report.status !== "available" && !error ? (
          <Suspense fallback={null}><ReportAvailability report={report} lang={lang} /></Suspense>
        ) : (
          <p>{error ? tx.unavailable : teaser}</p>
        )}
      </div>
      {!loading && error && (
        <button className="company-insight-action" type="button" onClick={onRetry}>{tx.retry}</button>
      )}
      {!loading && !error && report && (!report.status || report.status === "available") && report.paragraphs?.length > 0 && (
        <button ref={buttonRef} className="company-insight-action" type="button" onClick={onOpen}>{tx.details}</button>
      )}
    </section>
  );
}

function CompanyInsightDialog({ report, ticker, companyName, lang, onClose }) {
  const tx = COMPANY_INSIGHT_TX[lang] || COMPANY_INSIGHT_TX.ru;
  const dialogRef = React.useRef(null);
  const closeRef = React.useRef(null);
  const titleId = `company-insight-title-${String(ticker || "company").replace(/[^a-zA-Z0-9_-]/g, "-")}`;
  const bodyId = `${titleId}-body`;
  const sources = React.useMemo(() => {
    const seen = new Set();
    return (report?.number_references || []).reduce((items, ref) => {
      const source = ref?.source || {};
      const key = source.document_id || source.url;
      if (!key || seen.has(key)) return items;
      seen.add(key);
      items.push({ ...source, period: ref.period });
      return items;
    }, []);
  }, [report]);

  React.useEffect(() => {
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    closeRef.current?.focus();
    const handleKey = (event) => {
      if (event.key === "Escape") {
        event.preventDefault();
        onClose();
        return;
      }
      if (event.key !== "Tab" || !dialogRef.current) return;
      const focusable = [...dialogRef.current.querySelectorAll('button:not([disabled]), a[href], summary, [tabindex]:not([tabindex="-1"])')].filter((element) => element.getClientRects().length > 0);
      if (!focusable.length) return;
      const first = focusable[0];
      const last = focusable[focusable.length - 1];
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    };
    document.addEventListener("keydown", handleKey);
    return () => {
      document.body.style.overflow = previousOverflow;
      document.removeEventListener("keydown", handleKey);
    };
  }, [onClose]);

  return createPortal((
    <div className="company-insight-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}>
      <article ref={dialogRef} className="company-insight-dialog" role="dialog" aria-modal="true" aria-labelledby={titleId} aria-describedby={bodyId}>
        <header className="company-insight-dialog-head">
          <button ref={closeRef} className="company-insight-close" type="button" onClick={onClose} aria-label={tx.close}>×</button>
          <CompanyInsightIcon />
          <div>
            <div className="company-insight-eyebrow">{report.standard?.toUpperCase()} · {report.period_label || report.period || "—"}</div>
            <h2 id={titleId}>{tx.title} {ticker}</h2>
            <p>{companyName}</p>
          </div>
        </header>
        {report.content_status === "shortened" && <div className="company-insight-status">{tx.shortened}</div>}
        {sources.length > 0 && (
          <section className="company-insight-sources" aria-label={tx.sources}>
            <h3>{tx.sources}</h3>
            <div>
              {sources.map((source, index) => {
                const label = `${tx.source} ${report.standard?.toUpperCase() || ""} · ${source.period || report.period || "—"}`;
                return source.url ? (
                  <a key={source.document_id || source.url || index} href={source.url} target="_blank" rel="noreferrer">{label} ↗</a>
                ) : <span key={source.document_id || index}>{label}</span>;
              })}
            </div>
          </section>
        )}
        <div id={bodyId} className="company-insight-report-copy">
          {report.abstract && <aside className="company-insight-abstract"><span>{lang === "ru" ? "Аннотация" : lang === "uz" ? "Annotatsiya" : "Abstract"}</span><p>{companyInsightTeaser(report, lang)}</p></aside>}
          {(report.sections?.length ? report.sections : (report.paragraphs || []).map((text, index) => ({ id: `section-${index}`, text }))).map((section, index) => (
            <section className="company-insight-report-section" key={section.id || index}>
              {section.title && <header><span>{section.number || String(index + 1).padStart(2, "0")}</span><h3>{section.title}</h3></header>}
              <p>{section.text}</p>
            </section>
          ))}
        </div>
        <Suspense fallback={null}><VerifiedReport report={report} lang={lang} /></Suspense>
        <footer className="company-insight-dialog-foot">
          <span><CompanyInsightIcon small />{tx.generated}</span>
          <p>{tx.disclaimer}</p>
        </footer>
      </article>
    </div>
  ), document.body);
}

function CompanyOverviewTab({ sec, ticker, priceHistory, priceLoading, priceAdjustments, intraday, priceRange, onRangeChange, companyData, financials, lang, infoLoading, securityType, isPreferred, industry, marketRow, priceMetrics, metrics12, mult, dividends, lastPrice, watchRail, compare, onExpandChart }) {
  const nominalVal = safeNumber(marketRow?.nominal) || null;

  return (
    <div className="company-overview-layout">
      {/* Three columns at full width, MSN's shape: the watchlist on the left,
          the security in the middle, its numbers on the right. Valuation,
          profitability and the session all come from /api/market/multiples and
          the board row, so nothing here is recomputed and nothing can disagree
          with the market table. */}
      <div className="company-hero-grid">
        <div className="company-hero-watch">{watchRail}</div>
        <div className="company-hero-main">
          <div className="company-chart-panel panel">
            {/* The metrics response still decides whether candles mean anything
                here (`quality`) and how long a moving average is (`ma_windows`);
                only its numbers stopped being printed. */}
            <CompanyPriceChart history={priceHistory} loading={priceLoading} range={priceRange} onRangeChange={onRangeChange} adjustments={priceAdjustments} lang={lang}
              intraday={intraday} quality={priceMetrics?.quality} metricsWindows={priceMetrics?.ma_windows}
              ticker={ticker} compare={compare?.series} compareLoading={compare?.loading} compareTools={compare}
              onExpand={onExpandChart} />
            {/* Inside the chart panel, as on the reference page: the strip is a
                control for the chart above it, not a section of its own. */}
            {compare && (
              <QuickCompareStrip peers={compare.peers} securitiesMap={compare.securitiesMap}
                selected={compare.selected} colors={QC_COLORS} onToggle={compare.onToggle}
                lang={lang} loading={compare.loading} />
            )}
          </div>
          <div className="company-overview-main">
            <h3 className="co-heading">{lang === "ru" ? "О компании" : lang === "uz" ? "Kompaniya haqida" : "About the company"}</h3>
            {sec.company_description ? (
              <>
                <p className="company-description-text">{sec.company_description}</p>
                {sec.source_url && (
                  <a href={sec.source_url} target="_blank" rel="noreferrer" className="wiki-link">
                    {sec.info_source === "wikipedia"
                      ? (lang === "ru" ? "Читать на Википедии →" : lang === "uz" ? "Vikipediyada o'qish →" : "Read on Wikipedia →")
                      : (lang === "ru" ? "Официальный сайт →" : lang === "uz" ? "Rasmiy sayt →" : "Official website →")}
                  </a>
                )}
              </>
            ) : infoLoading ? (
              <div className="company-desc-skeleton" aria-hidden="true">
                <span /><span /><span /><span style={{ width: "62%" }} />
              </div>
            ) : (
              <p className="muted" style={{ fontSize: 14 }}>{lang === "ru" ? "Информация о компании недоступна." : lang === "uz" ? "Kompaniya haqida ma'lumot mavjud emas." : "Company information is currently unavailable."}</p>
            )}
          </div>
        </div>

        {/* Everything the page states ABOUT THIS SECURITY, in one column: the
            session, the year's range, the multiples, the returns — and under
            them the two reference blocks. They belong here by subject. The left
            rail is other people's securities, and an issuer's own dividend
            history read oddly in a column of peers.
            The 2026-08-08 note under this comment recorded the cost of a long
            rail: six blocks ran to 1521px against a 1029px main column. It is
            back, smaller — measured after this change at 1920px, the rail ends
            below the main column rather than level with it. That is the trade
            the customer chose: subject over balance. */}
        <div className="company-overview-sidebar">
          <CompanyKeyStats row={marketRow} sec={sec} metrics12={metrics12} mult={mult}
            metricsWindow={priceMetrics} range={priceRange}
            dividends={dividends} lastPrice={lastPrice} securityType={securityType} lang={lang}
            placement="rail" />
          <CompanyKeyStats row={marketRow} sec={sec} metrics12={metrics12} mult={mult}
            dividends={dividends} lastPrice={lastPrice} securityType={securityType} lang={lang}
            placement="lower" />
          <div className="co-sidebar-block">
            <h3 className="co-heading">{lang === "ru" ? "Детали" : lang === "uz" ? "Tafsilotlar" : "Details"}</h3>
            <div className="company-metrics-list">
              {sec.isin && <div className="company-metric-row"><span className="panel-label">ISIN</span><span className="isin-mono">{sec.isin}</span></div>}
              {nominalVal && <div className="company-metric-row"><span className="panel-label">{lang === "ru" ? "Номинал" : lang === "uz" ? "Nominal" : "Nominal"}</span><span>{formatMarketNumber(nominalVal, lang)} UZS</span></div>}
              {industry && <div className="company-metric-row"><span className="panel-label">{lang === "ru" ? "Отрасль" : lang === "uz" ? "Soha" : "Sector"}</span><span>{sectorLabel(lang, industry)}</span></div>}
              {securityType && <div className="company-metric-row"><span className="panel-label">{lang === "ru" ? "Тип" : lang === "uz" ? "Turi" : "Type"}</span><span>{securityType === "bond" ? (lang === "ru" ? "Облигация" : lang === "uz" ? "Obligatsiya" : "Bond") : (lang === "ru" ? "Акция" : lang === "uz" ? "Aksiya" : "Stock")}</span></div>}
              {securityType !== "bond" && (
                <div className="company-metric-row">
                  <span className="panel-label">{lang === "ru" ? "Класс" : lang === "uz" ? "Sinf" : "Class"}</span>
                  <span>{isPreferred ? (lang === "ru" ? "Привилегированная" : lang === "uz" ? "Imtiyozli" : "Preferred") : (lang === "ru" ? "Обыкновенная" : lang === "uz" ? "Oddiy" : "Common")}</span>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

    </div>
  );
}

function CompanyReportsTab({ reports, lang }) {
  const forms = [...new Set((reports || []).map((r) => r.report_form))];
  const [form, setForm] = React.useState(forms[0] || null);
  // Keyed on the actual form set, not reports.length: two companies with the
  // same report count but different form types used to keep a stale filter
  // and show "no reports" even though reports existed.
  const formsKey = forms.join("|");
  React.useEffect(() => {
    if (forms.length > 0 && !forms.includes(form)) setForm(forms[0]);
  }, [formsKey]);
  const visible = form ? reports.filter((r) => r.report_form === form) : reports;
  const FORM_LABELS = { NSBU: "НСБУ", MSFO: "МСФО", Audition: lang === "ru" ? "Аудит" : "Audit" };
  return (
    <div>
      {forms.length > 1 && (
        <div className="company-chart-ranges" style={{ marginBottom: 12 }}>
          {forms.map((f) => (
            <button key={f} type="button" className={`range-btn ${form === f ? "active" : ""}`} onClick={() => setForm(f)}>{FORM_LABELS[f] || f}</button>
          ))}
        </div>
      )}
      {visible.length === 0 ? (
        <div className="panel" style={{ padding: 32, textAlign: "center" }}>
          <p className="muted">{lang === "ru" ? "Отчётов не найдено" : "No reports found"}</p>
        </div>
      ) : (
        <div className="company-reports-list">
          {visible.map((r, i) => (
            <div key={i} className="company-report-row panel">
              <div>
                <div style={{ fontWeight: 600, fontSize: 14 }}>{r.title || `${r.report_form} ${r.year || ""} ${r.quarter ? `Q${r.quarter}` : ""}`}</div>
                <div className="muted" style={{ fontSize: 12 }}>
                  {r.period_type} · {r.year}{r.quarter ? ` Q${r.quarter}` : ""} · {r.report_form}
                </div>
              </div>
              <div style={{ display: "flex", gap: 8 }}>
                {r.excel_url && <a href={r.excel_url} target="_blank" rel="noreferrer" className="ghost-btn" style={{ fontSize: 12 }}>Excel →</a>}
                {r.excel_url_form1 && r.excel_url_form1 !== r.excel_url && <a href={r.excel_url_form1} target="_blank" rel="noreferrer" className="ghost-btn" style={{ fontSize: 12 }}>{lang === "ru" ? "Баланс →" : lang === "uz" ? "Balans →" : "Balance →"}</a>}
                {r.pdf_url && !r.pdf_url.includes("/reports/to_pdf") && <a href={r.pdf_url} target="_blank" rel="noreferrer" className="ghost-btn" style={{ fontSize: 12 }}>PDF →</a>}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// The Финансы tab, on the reference page's shape: sub-tabs across the statement,
// a multi-series chart of the section's headline lines, then a table with one
// column per YEAR and a growth row under each absolute figure.
//
// The series comes from /api/company/{t}/financials — the fact store, which has
// held nine to eleven annual periods per issuer all along and was serving
// nobody. This tab used to show ONE period's five ratios out of the reports
// cache, and «не кешированы» for every issuer whose cache was cold.
//
// No Cash Flow sub-tab: NSBU form 4 is not parsed, so there is no cash-flow
// series to put behind it. An empty fourth tab would look like a loading bug.
const FIN_SECTIONS = [
  {
    key: "income",
    label: ["Прибыли и убытки", "Foyda va zarar", "Income Statement"],
    // The reference page's income statement, in its order: what came in, what
    // the goods cost, what running the business cost, what was left.
    rows: ["net_revenue", "gross_profit", "operating_expenses", "operating_income", "net_profit"],
    // Percentages get their own block, as on the reference: mixing a margin
    // into a column of sums invites reading 5.62 as five sums.
    // Only the margin this platform computes itself — see the note on
    // FACT_PERCENT_FIELDS for the ones the feed publishes and we do not trust.
    margins: ["net_margin"],
    chart: ["net_revenue", "operating_expenses", "operating_income"],
  },
  {
    key: "balance",
    label: ["Баланс", "Balans", "Balance Sheet"],
    rows: ["total_assets", "total_liabilities", "total_equity"],
    chart: ["total_assets", "total_liabilities", "total_equity"],
  },
  {
    key: "ratios",
    label: ["Коэффициенты", "Koeffitsiyentlar", "Key Ratios"],
    margins: ["roe", "roa", "current_ratio", "quick_ratio", "debt_ratio",
              "debt_to_equity", "total_asset_turnover", "return_to_capital_employed"],
    chart: ["roe", "roa"],
  },
];

// The quarterly view carries only what the quarterly FILINGS carry: the income
// statement plus the balance snapshots the parse keeps. Its Баланс sub-tab
// shows the SAME three lines as the annual one — Активы, Обязательства,
// Капитал (customer, 2026-08-16: the two views must read alike; cash came off
// the display, though the endpoint still serves it).
// No Коэффициенты sub-tab — quarterly ROE/ROA off a cumulative income against a
// point-in-time balance is a figure that needs annualising to mean anything,
// and a wrong ratio beside a right one discredits both.
const FIN_SECTIONS_QUARTER = [
  {
    key: "income",
    label: ["Прибыли и убытки", "Foyda va zarar", "Income Statement"],
    rows: ["net_revenue", "gross_profit", "operating_expenses", "operating_income", "net_profit"],
    margins: ["net_margin"],
    chart: ["net_revenue", "operating_expenses", "operating_income"],
  },
  {
    key: "balance",
    label: ["Баланс", "Balans", "Balance Sheet"],
    rows: ["total_assets", "total_liabilities", "total_equity"],
    chart: ["total_assets", "total_liabilities", "total_equity"],
  },
];

// "2024Q2" → {y: 2024, q: 2}; anything else → null.
const parseQPeriod = (p) => {
  const m = /^(\d{4})Q([1-4])$/.exec(String(p));
  return m ? { y: +m[1], q: +m[2] } : null;
};
const finPeriodLabel = (p, compact) => {
  const pq = parseQPeriod(p);
  return pq ? (compact ? `Q${pq.q}'${String(pq.y).slice(2)}` : `Q${pq.q} ${pq.y}`) : String(p);
};

const FIN_FIELD_LABELS = {
  net_revenue: ["Выручка", "Tushum", "Revenue"],
  net_profit: ["Чистая прибыль", "Sof foyda", "Net Profit"],
  gross_profit: ["Валовая прибыль", "Yalpi foyda", "Gross Profit"],
  operating_expenses: ["Операционные расходы", "Operatsion xarajatlar", "Operating Expenses"],
  operating_income: ["Операционная прибыль", "Operatsion foyda", "Operating Income"],
  cash: ["Денежные средства", "Pul mablaglari", "Cash"],
  total_assets: ["Активы", "Aktivlar", "Total Assets"],
  total_liabilities: ["Обязательства", "Majburiyatlar", "Total Liabilities"],
  total_equity: ["Капитал", "Kapital", "Total Equity"],
  gross_profit_margin: ["Валовая маржа", "Yalpi marja", "Gross Margin"],
  ebit_margin: ["EBIT-маржа", "EBIT marja", "EBIT Margin"],
  net_margin: ["Чистая маржа", "Sof marja", "Net Margin"],
  roe: ["ROE", "ROE", "ROE"],
  roa: ["ROA", "ROA", "ROA"],
  current_ratio: ["Текущая ликвидность", "Joriy likvidlik", "Current Ratio"],
  quick_ratio: ["Быстрая ликвидность", "Tez likvidlik", "Quick Ratio"],
  debt_ratio: ["Долг/Активы", "Qarz/Aktivlar", "Debt Ratio"],
  debt_to_equity: ["Долг/Капитал", "Qarz/Kapital", "Debt/Equity"],
  total_asset_turnover: ["Оборачиваемость активов", "Aktivlar aylanmasi", "Asset Turnover"],
  return_to_capital_employed: ["ROCE", "ROCE", "ROCE"],
};

const finLabel = (field, lang) =>
  (FIN_FIELD_LABELS[field] || [field, field, field])[lang === "uz" ? 1 : lang === "en" ? 2 : 0];

// Which glossary entry explains a row of the Финансы table (lib/glossary.js is
// the one definition store; `id` matches the market board's column key, so most
// of these are the field's own name and the map only bridges the two that are
// not). A ratio is where the reader actually needs the explanation: «Выручка»
// says what it is, «ROCE» and «Долг/Активы» do not, and a coefficient printed
// bare — 0,07 — says least of all. Only the fields listed here get an ⓘ; the
// marker renders nothing for a term that has no entry, so an unmapped row
// simply stays plain.
const FIN_FIELD_TERMS = {
  net_margin: "netMargin",
  roe: "roe",
  roa: "roa",
  current_ratio: "currentRatio",
  quick_ratio: "quickRatio",
  debt_ratio: "debtAssets",
  debt_to_equity: "debtEq",
  total_asset_turnover: "assetTurnover",
  return_to_capital_employed: "roce",
};

// One palette for the chart, the legend and the table's row dots. A field's
// colour comes from its position in the SECTION's row list, not in the current
// selection — toggling a line on or off must not repaint the others.
const FIN_CHART_COLORS = ["#38bdf8", "#f59e0b", "#a855f7", "#34d399", "#f472b6",
                          "#facc15", "#60a5fa", "#fb7185", "#4ade80", "#c084fc"];

// The section's headline lines over time. Deliberately not the price chart: no
// range buttons, no hover — this is a shape, and the table underneath is the data.
function FinancialsChart({ fields, series, periods, lang, colorOf, onToggle }) {
  // A chart nobody can interrogate is a picture. This one had no hover at all:
  // pointing at a year gave nothing, which is what «no info» meant.
  const [hover, setHover] = React.useState(null);
  const [hoverY, setHoverY] = React.useState(0);
  const cols = periods;               // already oldest → newest, left → right
  const drawn = fields
    .map((f, i) => ({ f, color: colorOf ? colorOf(f) : FIN_CHART_COLORS[i % FIN_CHART_COLORS.length], s: series[f] }))
    .filter((d) => d.s && cols.some((c) => Number.isFinite(d.s.values[c])));
  if (drawn.length === 0 || cols.length < 2) return null;

  const all = drawn.flatMap((d) => cols.map((c) => d.s.values[c]).filter(Number.isFinite));
  // Zero-based, as on the reference: an axis that starts at its own minimum
  // turns a three-percent move into a cliff.
  const max = Math.max(...all, 0), min = Math.min(...all, 0);
  const span = max - min || 1;
  const W = 820, H = 210, PAD = { t: 12, r: 14, b: 26, l: 70 };
  const x = (i) => PAD.l + (i / Math.max(1, cols.length - 1)) * (W - PAD.l - PAD.r);
  const y = (v) => PAD.t + (1 - (v - min) / span) * (H - PAD.t - PAD.b);
  const money = drawn[0].s.money;
  // The axis carries the % sign only when EVERY drawn line is a percentage:
  // ROE beside Долг/Капитал shares a numeric scale, not a unit, and the
  // per-row unit lives in the tooltip.
  const pct = drawn.every((d) => d.s.unit === "%");
  const axis = (v) => (money ? formatCompactVolume(v, lang)
    : `${formatRatio(v, 1, lang)}${pct ? "%" : ""}`);
  const onMove = (e) => {
    const r = e.currentTarget.getBoundingClientRect();
    if (!r.width) return;
    const relX = ((e.clientX - r.left) / r.width) * W;
    const i = Math.max(0, Math.min(cols.length - 1,
      Math.round(((relX - PAD.l) / (W - PAD.l - PAD.r)) * (cols.length - 1))));
    setHover(i);
    const wrap = e.currentTarget.parentElement;
    setHoverY(e.clientY - (wrap ? wrap.getBoundingClientRect().top : r.top));
  };

  return (
    <div className="fin-chart">
      <svg viewBox={`0 0 ${W} ${H}`} style={{ width: "100%", height: "auto" }}
        onMouseMove={onMove} onMouseLeave={() => setHover(null)}>
        {[0, 0.5, 1].map((f, i) => (
          <line key={i} x1={PAD.l} y1={y(min + f * span)} x2={W - PAD.r} y2={y(min + f * span)}
            stroke="currentColor" strokeOpacity="0.16" strokeDasharray="4 6" strokeWidth="0.8" />
        ))}
        {[0, 0.5, 1].map((f, i) => (
          <text key={`l${i}`} x={PAD.l - 8} y={y(min + f * span) + 3.5} textAnchor="end"
            fontSize="10" fill="currentColor" opacity="0.5">{axis(min + f * span)}</text>
        ))}
        {drawn.map((d) => {
          const pts = cols.map((c, i) => ({ i, v: d.s.values[c] })).filter((pt) => Number.isFinite(pt.v));
          if (pts.length < 2) return null;
          const path = pts.map((pt, k) => `${k ? "L" : "M"}${x(pt.i).toFixed(1)},${y(pt.v).toFixed(1)}`).join(" ");
          return <path key={d.f} d={path} fill="none" stroke={d.color} strokeWidth="2"
            strokeLinejoin="round" vectorEffect="non-scaling-stroke" />;
        })}
        {cols.map((c, i) => {
          // A quarterly series can put 15+ columns here; labels every ~60px at
          // most, the ends always named.
          const step = Math.max(1, Math.ceil(cols.length / 13));
          if (i % step !== 0 && i !== cols.length - 1) return null;
          return (
            <text key={c} x={x(i)} y={H - 8} fontSize="10" fill="currentColor" opacity="0.5"
              textAnchor={i === 0 ? "start" : i === cols.length - 1 ? "end" : "middle"}>
              {finPeriodLabel(c, true)}
            </text>
          );
        })}
        {hover != null && (
          <>
            <line x1={x(hover)} y1={PAD.t} x2={x(hover)} y2={H - PAD.b}
              stroke="currentColor" strokeOpacity="0.38" strokeDasharray="3 3" />
            {drawn.map((d) => (Number.isFinite(d.s.values[cols[hover]]) ? (
              <circle key={d.f} cx={x(hover)} cy={y(d.s.values[cols[hover]])} r="3.6"
                fill={d.color} stroke="var(--panel, #0b0f1a)" strokeWidth="1.5" />
            ) : null))}
          </>
        )}
      </svg>
      {hover != null && (
        <div className={`cpc-tooltip ${x(hover) > W * 0.62 ? "" : ""}`}
          style={{
            top: `${Math.max(6, hoverY - 40)}px`,
            ...(x(hover) > W * 0.62
              ? { right: `calc(${((W - x(hover)) / W) * 100}% + 12px)` }
              : { left: `calc(${(x(hover) / W) * 100}% + 12px)` }),
          }}>
          <div className="cpc-tt-date">{finPeriodLabel(cols[hover])}</div>
          {drawn.map((d) => {
            const v = d.s.values[cols[hover]];
            return (
              <div className="cpc-tt-row" key={d.f}>
                <span><i className="fin-tt-dot" style={{ background: d.color }} />{finLabel(d.f, lang)}</span>
                <b>{!Number.isFinite(v) ? "—"
                  : d.s.money ? formatCompactVolume(v, lang)
                  : `${formatRatio(v, 2, lang)}${d.s.unit === "%" ? "%" : ""}`}</b>
              </div>
            );
          })}
        </div>
      )}
      <div className="fin-legend">
        {drawn.map((d) => (onToggle ? (
          <button key={d.f} type="button" className="fin-legend-item clickable"
            onClick={() => onToggle(d.f)}>
            <i style={{ background: d.color }} />{finLabel(d.f, lang)}
          </button>
        ) : (
          <span key={d.f} className="fin-legend-item">
            <i style={{ background: d.color }} />{finLabel(d.f, lang)}
          </span>
        )))}
      </div>
    </div>
  );
}

// The same series as columns of bars. A line says "this is the shape of a
// trend"; a bar says "this is how big each period was" — for revenue or profit,
// which is what most readers open this tab for, the second is the honest picture,
// and a line between two annual points implies twelve months of movement nobody
// measured.
//
// Deliberately the same frame as FinancialsChart — same viewBox, padding, axis
// formatter, palette and tooltip — so switching the view does not re-teach the
// reader where to look. The zero line is drawn, not implied: on this market a
// year of losses is common, and a bar hanging below the axis has to hang from
// something.
function FinancialsBars({ fields, series, periods, lang, colorOf, onToggle }) {
  const [hover, setHover] = React.useState(null);
  const [hoverY, setHoverY] = React.useState(0);
  const cols = periods;
  const drawn = fields
    .map((f, i) => ({ f, color: colorOf ? colorOf(f) : FIN_CHART_COLORS[i % FIN_CHART_COLORS.length], s: series[f] }))
    .filter((d) => d.s && cols.some((c) => Number.isFinite(d.s.values[c])));
  if (drawn.length === 0 || cols.length === 0) return null;

  const all = drawn.flatMap((d) => cols.map((c) => d.s.values[c]).filter(Number.isFinite));
  const max = Math.max(...all, 0), min = Math.min(...all, 0);
  const span = max - min || 1;
  const W = 820, H = 210, PAD = { t: 12, r: 14, b: 26, l: 70 };
  const plot = W - PAD.l - PAD.r;
  const y = (v) => PAD.t + (1 - (v - min) / span) * (H - PAD.t - PAD.b);
  const zero = y(0);
  const money = drawn[0].s.money;
  const pct = drawn.every((d) => d.s.unit === "%");
  const axis = (v) => (money ? formatCompactVolume(v, lang)
    : `${formatRatio(v, 1, lang)}${pct ? "%" : ""}`);
  // One slot per period, the bars of a period sharing it. A tenth of the slot
  // stays empty on each side so neighbouring periods do not touch.
  const slot = plot / cols.length;
  const groupW = slot * 0.8;
  const barW = Math.max(1.5, groupW / drawn.length);
  const slotX = (i) => PAD.l + i * slot;
  const onMove = (e) => {
    const r = e.currentTarget.getBoundingClientRect();
    if (!r.width) return;
    const relX = ((e.clientX - r.left) / r.width) * W;
    const i = Math.max(0, Math.min(cols.length - 1, Math.floor((relX - PAD.l) / slot)));
    setHover(i);
    const wrap = e.currentTarget.parentElement;
    setHoverY(e.clientY - (wrap ? wrap.getBoundingClientRect().top : r.top));
  };

  return (
    <div className="fin-chart">
      <svg viewBox={`0 0 ${W} ${H}`} style={{ width: "100%", height: "auto" }}
        onMouseMove={onMove} onMouseLeave={() => setHover(null)}>
        {[0, 0.5, 1].map((f, i) => (
          <line key={i} x1={PAD.l} y1={y(min + f * span)} x2={W - PAD.r} y2={y(min + f * span)}
            stroke="currentColor" strokeOpacity="0.16" strokeDasharray="4 6" strokeWidth="0.8" />
        ))}
        {[0, 0.5, 1].map((f, i) => (
          <text key={`l${i}`} x={PAD.l - 8} y={y(min + f * span) + 3.5} textAnchor="end"
            fontSize="10" fill="currentColor" opacity="0.5">{axis(min + f * span)}</text>
        ))}
        {min < 0 && (
          <line x1={PAD.l} y1={zero} x2={W - PAD.r} y2={zero}
            stroke="currentColor" strokeOpacity="0.45" strokeWidth="1" />
        )}
        {hover != null && (
          <rect x={slotX(hover)} y={PAD.t} width={slot} height={H - PAD.t - PAD.b}
            fill="currentColor" opacity="0.06" />
        )}
        {cols.map((c, i) => drawn.map((d, k) => {
          const v = d.s.values[c];
          if (!Number.isFinite(v)) return null;
          const top = Math.min(y(v), zero);
          // A period whose value rounds to nothing still gets a visible sliver:
          // «0» and «not filed» are different statements and the chart must not
          // render them the same way.
          const height = Math.max(1, Math.abs(zero - y(v)));
          const x = slotX(i) + (slot - groupW) / 2 + k * barW;
          return <rect key={`${c}-${d.f}`} x={x.toFixed(1)} y={top.toFixed(1)}
            width={Math.max(1, barW - 1.5).toFixed(1)} height={height.toFixed(1)}
            fill={d.color} rx={Math.min(2, barW / 3)} />;
        }))}
        {cols.map((c, i) => {
          const step = Math.max(1, Math.ceil(cols.length / 13));
          if (i % step !== 0 && i !== cols.length - 1) return null;
          return (
            <text key={c} x={slotX(i) + slot / 2} y={H - 8} fontSize="10" fill="currentColor"
              opacity="0.5" textAnchor="middle">{finPeriodLabel(c, true)}</text>
          );
        })}
      </svg>
      {hover != null && (
        <div className="cpc-tooltip"
          style={{
            top: `${Math.max(6, hoverY - 40)}px`,
            ...((slotX(hover) + slot / 2) > W * 0.62
              ? { right: `calc(${((W - slotX(hover)) / W) * 100}% + 12px)` }
              : { left: `calc(${((slotX(hover) + slot) / W) * 100}% + 12px)` }),
          }}>
          <div className="cpc-tt-date">{finPeriodLabel(cols[hover])}</div>
          {drawn.map((d) => {
            const v = d.s.values[cols[hover]];
            return (
              <div className="cpc-tt-row" key={d.f}>
                <span><i className="fin-tt-dot" style={{ background: d.color }} />{finLabel(d.f, lang)}</span>
                <b>{!Number.isFinite(v) ? "—"
                  : d.s.money ? formatCompactVolume(v, lang)
                  : `${formatRatio(v, 2, lang)}${d.s.unit === "%" ? "%" : ""}`}</b>
              </div>
            );
          })}
        </div>
      )}
      <div className="fin-legend">
        {drawn.map((d) => (onToggle ? (
          <button key={d.f} type="button" className="fin-legend-item clickable"
            onClick={() => onToggle(d.f)}>
            <i style={{ background: d.color }} />{finLabel(d.f, lang)}
          </button>
        ) : (
          <span key={d.f} className="fin-legend-item">
            <i style={{ background: d.color }} />{finLabel(d.f, lang)}
          </span>
        )))}
      </div>
    </div>
  );
}

// How the financial section is drawn. Three, because that is what the customer
// asked for and because they answer three different questions: a line for the
// trend, bars for the size of each period, the table for the figures themselves.
const FIN_DASHBOARDS = [
  { key: "line", label: ["Линейный", "Chizmali", "Line"] },
  { key: "bar", label: ["Столбчатый", "Ustunli", "Bars"] },
  { key: "table", label: ["Таблица", "Jadval", "Table"] },
];
const FIN_DASHBOARD_KEY = "uz_fin_dashboard";

// The «Сплиты» sub-tab: the corporate-actions register every price series on
// the site is back-adjusted by, shown as its own record. uzse.uz keeps the
// same thing behind «Посмотреть сплиты» on the quote page, but lists only the
// redenominations — this table also carries the free issues out of own funds,
// because a holder's 3× on ALSM is the two together. For most securities the
// honest content is «не зафиксировано», and that renders as a sentence, not
// as an empty table.
function CompanySplitsTable({ items, lang }) {
  const t = (ru, uz, en) => (lang === "uz" ? uz : lang === "en" ? en : ru);
  const locale = lang === "en" ? "en-US" : "ru-RU";
  if (items === null) return <div className="chart-loading muted">{t("Загрузка…", "Yuklanmoqda…", "Loading…")}</div>;
  const rows = items || [];
  if (rows.length === 0) return (
    <div className="panel" style={{ padding: 32, textAlign: "center" }}>
      <p className="muted">{t("Сплитов и бонусных эмиссий по этой бумаге не зафиксировано",
                              "Bu qog'oz bo'yicha splitlar va bonus emissiyalar qayd etilmagan",
                              "No splits or bonus issues on record for this security")}</p>
    </div>
  );
  const fmtDate = (d) => (d ? new Date(d).toLocaleDateString(locale, { year: "numeric", month: "short", day: "numeric" }) : "—");
  const fmtN = (v) => Number(v).toLocaleString(locale, { maximumFractionDigits: 2 });
  const kindLabel = (k) => (k === "bonus"
    ? t("Бонусная эмиссия", "Bonus emissiya", "Bonus issue")
    : t("Сплит", "Split", "Split"));
  // «1 → 1,69» on its own is a riddle; the sentence beside it is the row.
  const effectLabel = (r) => {
    const n = Number(r.ratio) || 1;
    if (r.kind === "bonus") {
      const per100 = Math.round((n - 1) * 100);
      return t(`держателю начислено ${fmtN(per100)} новых акций на каждые 100`,
               `har 100 aksiyaga ${fmtN(per100)} ta yangi aksiya qo'shildi`,
               `${fmtN(per100)} new shares credited for every 100 held`);
    }
    return t(`каждая акция раздроблена на ${fmtN(n)}`,
             `har bir aksiya ${fmtN(n)} taga bo'lindi`,
             `each share was split into ${fmtN(n)}`);
  };
  // The events compound: one pre-2024 ALKB share is 121 × 205/121 = 205 of
  // today's, and that product — not either row alone — is what explains the
  // step a reader remembers seeing in an unadjusted price.
  const total = rows.reduce((acc, r) => acc * (Number(r.ratio) || 1), 1);
  return (
    <div className="panel fin-panel">
      <div className="fin-table-wrap">
        <table className="fin-table splits-table">
          <thead>
            <tr>
              <th scope="col" className="splits-col-date">{t("Дата", "Sana", "Date")}</th>
              <th scope="col" className="splits-col-kind">{t("Событие", "Hodisa", "Event")}</th>
              <th scope="col" className="num splits-col-ratio">{t("Коэффициент", "Koeffitsiyent", "Ratio")}</th>
              <th scope="col">{t("Что произошло", "Nima bo'ldi", "What happened")}</th>
              <th scope="col" className="splits-col-src">{t("Раскрытие", "Oshkor qilish", "Disclosure")}</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((r, i) => (
              <tr key={i}>
                <td>{fmtDate(r.ex_date)}</td>
                <td><span className={`splits-kind splits-kind--${r.kind === "bonus" ? "bonus" : "split"}`}>{kindLabel(r.kind)}</span></td>
                <td className="num">{`1 → ${fmtN(r.ratio)}`}</td>
                <td className="splits-effect">{effectLabel(r)}</td>
                <td className="splits-src">{r.source
                  ? <a href={r.source} target="_blank" rel="noreferrer">openinfo ↗</a>
                  : "—"}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <p className="fin-note muted">
        {rows.length > 1 && (
          <>{t("Итого одна акция до всех событий — это ", "Jami: barcha hodisalargacha bitta aksiya — bugungi ", "In total one pre-event share is ")}
            <strong>{fmtN(total)}</strong>
            {t(" сегодняшних. ", " ta aksiya. ", " of today's. ")}</>
        )}
        {t("Дата — первая торговая сессия на новом количестве акций. Цены на графиках и в истории до этой даты уже пересчитаны на сегодняшнюю акцию; объёмы торгов не пересчитываются.",
           "Sana — yangi aksiyalar sonidagi birinchi savdo sessiyasi. Grafiklardagi narxlar bugungi aksiyaga qayta hisoblangan; savdo hajmlari qayta hisoblanmaydi.",
           "The date is the first session traded on the new share count. Prices on the charts and in the history before it are already restated onto today's share; traded volumes are not restated.")}
      </p>
    </div>
  );
}

function FinancialPassportDialog({ passport, loading, field, period, lang, onClose }) {
  const dialogRef = React.useRef(null);
  const closeRef = React.useRef(null);
  const t = (ru, uz, en) => (lang === "uz" ? uz : lang === "en" ? en : ru);
  const titleId = `financial-passport-${String(field || "value").replace(/[^a-zA-Z0-9_-]/g, "-")}`;
  const source = passport?.source;

  React.useEffect(() => {
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    closeRef.current?.focus();
    const onKey = (event) => {
      if (event.key === "Escape") { event.preventDefault(); onClose(); }
    };
    document.addEventListener("keydown", onKey);
    return () => { document.body.style.overflow = previousOverflow; document.removeEventListener("keydown", onKey); };
  }, [onClose]);

  const label = finLabel(field, lang);
  const stateLabel = passport?.status === "SOURCED"
    ? t("Источник подтверждён", "Manba tasdiqlangan", "Source linked")
    : passport?.status === "DERIVED"
      ? t("Рассчитано платформой", "Platforma hisoblagan", "Calculated by the platform")
      : t("Паспорт источника недоступен", "Manba pasporti mavjud emas", "Source passport unavailable");

  return createPortal((
    <div className="company-insight-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}>
      <article ref={dialogRef} className="company-insight-dialog financial-passport-dialog" role="dialog" aria-modal="true" aria-labelledby={titleId}>
        <header className="company-insight-dialog-head">
          <button ref={closeRef} className="company-insight-close" type="button" onClick={onClose}
            aria-label={t("Закрыть паспорт источника", "Manba pasportini yopish", "Close source passport")}>×</button>
          <div>
            <div className="company-insight-eyebrow">{t("Паспорт значения", "Qiymat pasporti", "Value passport")}</div>
            <h2 id={titleId}>{label}</h2>
            <p>{period}</p>
          </div>
        </header>
        {loading ? <div className="chart-loading muted" style={{ padding: "28px 0" }}>{t("Загрузка…", "Yuklanmoqda…", "Loading…")}</div> : (
          <div className="financial-passport-copy">
            <div className={`financial-passport-status ${passport?.status || "unknown"}`}>{stateLabel}</div>
            {passport?.status === "SOURCED" && source && (
              <dl className="financial-passport-grid">
                <div><dt>{t("Отчёт", "Hisobot", "Report")}</dt><dd>{source.title || `${source.report_form || "—"} ${source.period_year || ""}`}</dd></div>
                <div><dt>{t("Период отчёта", "Hisobot davri", "Report period")}</dt><dd>{source.period_quarter ? `${source.period_year} Q${source.period_quarter}` : source.period_year || "—"}</dd></div>
                <div><dt>{t("Стандарт", "Standart", "Standard")}</dt><dd>{source.standard || passport.standard || "—"}</dd></div>
                <div><dt>{t("Периметр", "Qamrov", "Perimeter")}</dt><dd>{source.perimeter || source.source_ticker || "—"}</dd></div>
                <div><dt>{t("Статус проверки", "Tekshiruv holati", "Review status")}</dt><dd>{source.state || "—"}{source.state_reason ? ` — ${source.state_reason}` : ""}</dd></div>
                <div><dt>{t("Строка источника", "Manba satri", "Source line")}</dt><dd>{source.raw_label || "—"}</dd></div>
                <div><dt>{t("Исходная сумма", "Asl summa", "Raw value")}</dt><dd>{source.raw_value ?? "—"}</dd></div>
                <div><dt>{t("Нормализованное значение", "Normallashtirilgan qiymat", "Normalized value")}</dt><dd>{source.normalized_value ?? "—"}{source.normalization_formula ? ` (${source.normalization_formula})` : ""}</dd></div>
                <div><dt>{t("Знак", "Belgi", "Sign")}</dt><dd>{source.sign || "—"}</dd></div>
                <div><dt>{t("Страница", "Sahifa", "Page")}</dt><dd>{source.page || "—"}</dd></div>
                <div><dt>{t("Единица / масштаб", "Birlik / masshtab", "Unit / scale")}</dt><dd>{source.unit_scale ? `×${source.unit_scale}` : "—"}</dd></div>
                <div><dt>{t("Дата публикации источника", "Manba e’lon qilingan sana", "Source publication date")}</dt><dd>{source.source_published_at || "—"}</dd></div>
                <div><dt>{t("Получен платформой", "Platforma olgan vaqt", "Received by platform")}</dt><dd>{source.received_at || "—"}</dd></div>
                <div><dt>{t("Версия извлечения", "Ajratib olish versiyasi", "Extraction version")}</dt><dd>{source.extraction_version || "—"}</dd></div>
                <div><dt>{t("Хеш файла", "Fayl xeshi", "File hash")}</dt><dd className="financial-passport-hash">{source.file_hash || "—"}</dd></div>
              </dl>
            )}
            {passport?.status === "DERIVED" && (
              <section className="financial-passport-formula">
                <span>{t("Формула", "Formula", "Formula")}</span>
                <code>{passport.formula}</code>
                <p>{t("Это расчёт платформы. Откройте входные значения в таблице, чтобы увидеть их источники.", "Bu platforma hisobi. Manbalarni ko‘rish uchun jadvaldagi kirish qiymatlarini oching.", "This is a platform calculation. Open its input values in the table to inspect their filing sources.")}</p>
              </section>
            )}
            {passport?.status !== "SOURCED" && passport?.status !== "DERIVED" && (
              <p className="financial-passport-reason">{passport?.reason || t("Для этого значения нет проверяемой связи с исходным документом.", "Bu qiymat uchun asl hujjat bilan tekshiriladigan bog‘lanish yo‘q.", "This value has no verifiable link to a source document.")}</p>
            )}
            {passport?.reason && passport?.status === "SOURCED" && <p className="financial-passport-reason">{passport.reason}</p>}
            {source?.excel_url && <a className="company-insight-action" href={source.excel_url} target="_blank" rel="noreferrer">{t("Открыть Excel-отчёт ↗", "Excel hisobotni ochish ↗", "Open Excel report ↗")}</a>}
            {!source?.excel_url && source?.pdf_url && <a className="company-insight-action" href={source.pdf_url} target="_blank" rel="noreferrer">{t("Открыть PDF-отчёт ↗", "PDF hisobotni ochish ↗", "Open PDF report ↗")}</a>}
          </div>
        )}
      </article>
    </div>
  ), document.body);
}

function CompanyFinancialsTab({ ticker, ratios, series, periods, loading, lang, standard = "NSBU", onStandardChange, freq = "annual", onFreqChange, splits }) {
  const t = (ru, uz, en) => (lang === "uz" ? uz : lang === "en" ? en : ru);
  const [section, setSection] = React.useState("income");
  // Which lines the chart draws, per section (annual and quarterly sections
  // share a key space, which is fine — «income» means the same lines in both).
  // Unset = the section's default; from the first click the reader owns it.
  const [chartSel, setChartSel] = React.useState({});
  const [passport, setPassport] = React.useState(null);
  const [passportTarget, setPassportTarget] = React.useState(null);
  const [passportLoading, setPassportLoading] = React.useState(false);
  // Line | Bars | Table — the reader's choice, remembered. Exclusive on purpose:
  // «TABLE» is one of the three, so it cannot also be permanently underneath the
  // other two, and a chart with the whole table below it is what this tab was.
  const [dashboard, setDashboard] = React.useState(() => {
    try {
      const saved = localStorage.getItem(FIN_DASHBOARD_KEY);
      if (FIN_DASHBOARDS.some((d) => d.key === saved)) return saved;
    } catch (e) { /* ignore */ }
    return "table";
  });
  React.useEffect(() => {
    try { localStorage.setItem(FIN_DASHBOARD_KEY, dashboard); } catch (e) { /* ignore */ }
  }, [dashboard]);
  const quarterly = freq === "quarterly";

  const openPassport = React.useCallback((field, period) => {
    if (!ticker) return;
    setPassportTarget({ field, period });
    setPassport(null);
    setPassportLoading(true);
    const params = new URLSearchParams({ period, field, form: standard });
    fetch(`/api/company/${encodeURIComponent(ticker)}/financials/passport?${params.toString()}`)
      .then((response) => response.json())
      .then((body) => setPassport(body?.ok ? body : { status: "NO_SOURCE_PASSPORT" }))
      .catch(() => setPassport({ status: "NO_SOURCE_PASSPORT", reason: t("Не удалось загрузить паспорт источника.", "Manba pasportini yuklab bo‘lmadi.", "The source passport could not be loaded.") }))
      .finally(() => setPassportLoading(false));
  }, [ticker, standard, t]);

  const standardToggle = onStandardChange ? (
    <div className="fin-freq" role="group" aria-label={t("Стандарт", "Standart", "Standard")}>
      {[["NSBU", "НСБУ"], ["MSFO", "МСФО"]].map(([code, label]) => (
        <button key={code} type="button" className={`fin-freq-btn ${standard === code ? "active" : ""}`}
          aria-pressed={standard === code} onClick={() => onStandardChange(code)}>{label}</button>
      ))}
    </div>
  ) : null;

  // Годовые | Квартальные. The switch stays on screen in every state —
  // including "this issuer files no quarterlies" — or there is no way back.
  const freqToggle = onFreqChange && standard === "NSBU" ? (
    <div className="fin-freq" role="group" aria-label={t("Период", "Davr", "Period")}>
      {[["annual", t("Годовые", "Yillik", "Annual")],
        ["quarterly", t("Квартальные", "Choraklik", "Quarterly")]].map(([k, label]) => (
        <button key={k} type="button"
          className={`fin-freq-btn ${freq === k ? "active" : ""}`}
          onClick={() => onFreqChange(k)}>{label}</button>
      ))}
    </div>
  ) : null;

  if (loading) return (
    <div className="company-financials">
      <div className="fin-subtabs">{standardToggle}{freqToggle}</div>
      <div className="chart-loading muted">{t("Загрузка…", "Yuklanmoqda…", "Loading…")}</div>
    </div>
  );

  // The server sends newest-first; the table reads oldest → newest, left → right.
  const cols = [...(periods || [])].reverse();
  const has = (f) => series?.[f] && cols.some((p) => Number.isFinite(series[f].values[p]));
  const available = (quarterly ? FIN_SECTIONS_QUARTER : FIN_SECTIONS)
    .map((sec) => ({ ...sec, rows: (sec.rows || []).filter(has), margins: (sec.margins || []).filter(has) }))
    .filter((sec) => sec.rows.length + sec.margins.length > 0);

  // 66 of ~110 issuers file quarterlies; for the rest this view is honestly
  // empty. The annual fallback below must not answer for it — a reader who
  // asked for quarters and got a single year's ratios would take them for one.
  if (available.length === 0 && quarterly) {
    return (
      <div className="company-financials">
        <div className="fin-subtabs">{standardToggle}{freqToggle}</div>
        <div className="panel" style={{ padding: 32, textAlign: "center" }}>
          <p className="muted">{t("Эмитент не публикует квартальную отчётность",
                                  "Emitent choraklik hisobot e'lon qilmaydi",
                                  "No quarterly filings published")}</p>
        </div>
      </div>
    );
  }

  // Nothing in the fact store.  The legacy ratios cache has no reliable
  // accounting-standard dimension, so it is a NSBU-only fallback.  Reusing it
  // while the reader selected IFRS would put a familiar number under a false
  // label — the exact cross-standard substitution the product prohibits.
  if (available.length === 0) {
    if (standard !== "NSBU") return (
      <div className="company-financials">
        <div className="fin-subtabs">{standardToggle}</div>
        <div className="panel" style={{ padding: 32, textAlign: "center" }}>
          <p className="muted">{t("Годовая отчётность по МСФО не опубликована",
                                  "МСФО бўйича йиллик ҳисобот эълон қилинмаган",
                                  "No annual IFRS financial statements published")}</p>
        </div>
      </div>
    );
    const m = ratios?.metrics || {};
    const legacy = [["ROA", "ROA"], ["ROE", "ROE"],
                    ["net_margin", finLabel("net_profit_margin", lang)],
                    ["debt_ratio", finLabel("debt_ratio", lang)],
                    ["debt_to_equity", finLabel("debt_to_equity", lang)]]
      .filter(([k]) => m[k] != null);
    if (legacy.length === 0) return (
      <div className="company-financials">
        <div className="fin-subtabs">{standardToggle}{freqToggle}</div>
        <div className="panel" style={{ padding: 32, textAlign: "center" }}>
          <p className="muted">{t("Финансовые показатели не опубликованы",
                                  "Moliyaviy korsatkichlar elon qilinmagan",
                                  "No financial indicators published")}</p>
        </div>
      </div>
    );
    return (
      <div className="company-financials">
        <div className="fin-subtabs">{standardToggle}{freqToggle}</div>
        <div className="panel" style={{ padding: "16px 20px" }}>
          {ratios?.year && (
            <div className="muted" style={{ marginBottom: 12, fontSize: 13 }}>
              {t("Последние данные", "Songgi malumotlar", "Latest")}: {ratios.year}
              {ratios.quarter ? ` Q${ratios.quarter}` : ""}
            </div>
          )}
          <div className="company-metrics-list">
            {legacy.map(([k, l]) => (
              <div key={k} className="company-metric-row">
                <span className="panel-label">{l}</span>
                <span className="company-metric-val">{formatRatio(m[k], 2, lang)}</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  const active = available.find((sec) => sec.key === section) || available[0];

  // Every row of the active section is a candidate line — the list is built
  // from the section's rows, so a field added to FIN_SECTIONS later is
  // clickable with no further wiring. Colours are keyed to this canonical
  // order: toggling one line must not repaint the rest.
  const sectionFields = [...(active.rows || []), ...(active.margins || [])];
  const colorOf = (f) =>
    FIN_CHART_COLORS[Math.max(0, sectionFields.indexOf(f)) % FIN_CHART_COLORS.length];
  const defaultChart = (active.chart || []).filter(has);
  const selected = (chartSel[active.key] || defaultChart)
    .filter((f) => sectionFields.includes(f) && has(f));
  const chartFields = sectionFields.filter((f) => selected.includes(f));
  const toggleChartField = (f) => {
    if (!has(f)) return;
    setChartSel((prev) => {
      const cur = prev[active.key] || defaultChart;
      // Sums and coefficients cannot share an axis — a billion-сум revenue
      // line flattens ROE into the baseline. Adding a line from the other
      // register keeps only the rows it can honestly be drawn beside.
      const next = cur.includes(f)
        ? cur.filter((x) => x !== f)
        : [...cur.filter((x) => !!series[x]?.money === !!series[f]?.money), f];
      return { ...prev, [active.key]: next };
    });
  };

  // Years the issuer filed nothing for, between the oldest and newest it did.
  const yearNums = cols.map((p) => Number(p)).filter((n) => Number.isFinite(n));
  const missingYears = yearNums.length > 1
    ? Array.from({ length: Math.max(...yearNums) - Math.min(...yearNums) + 1 },
                 (_, i) => Math.min(...yearNums) + i)
        .filter((y) => !yearNums.includes(y))
    : [];

  // «Рост г/г» has to be year OVER YEAR, and on this market the column to the
  // left is often not last year. 53 of 100 issuers have a hole in their annual
  // series — AGBA is missing 2019, BECM is missing 2019, 2021 AND 2023 — and the
  // row happily compared 2020 with 2018 and called it a year. A two-year change
  // labelled as one is the kind of figure a reader takes to a valuation.
  //
  // So a gap yields a dash, and the dash says which year is missing. The value
  // is not lost: both columns are on screen, and a reader who wants the two-year
  // change can see both numbers. What is gone is the wrong label.
  const yearOf = (p) => (/^\d{4}$/.test(String(p)) ? Number(p) : null);
  const growth = (f, i) => {
    // Quarters compare with the SAME quarter a year earlier — the standard
    // comparison, because Q4 against Q3 measures the season, not the business.
    // The base is looked up by key, not by the column to the left, so a hole
    // in the filings yields a dash instead of a mislabelled change.
    if (quarterly) {
      const pq = parseQPeriod(cols[i]);
      if (!pq) return null;
      const v = series[f].values[cols[i]];
      const prev = series[f].values[`${pq.y - 1}Q${pq.q}`];
      if (!Number.isFinite(v) || !Number.isFinite(prev) || prev === 0) return null;
      return { value: ((v - prev) / Math.abs(prev)) * 100 };
    }
    const v = series[f].values[cols[i]], prev = series[f].values[cols[i - 1]];
    const y = yearOf(cols[i]), yPrev = yearOf(cols[i - 1]);
    if (y != null && yPrev != null && y - yPrev !== 1) {
      return { gap: true, missing: y - yPrev === 2 ? `${y - 1}` : `${yPrev + 1}–${y - 1}` };
    }
    if (!Number.isFinite(v) || !Number.isFinite(prev) || prev === 0) return null;
    return { value: ((v - prev) / Math.abs(prev)) * 100 };
  };
  // The secondary convention, quarterly only: against the PREVIOUS quarter
  // (Q1's predecessor is last year's Q4). Also keyed, never the neighbouring
  // column, for the same reason as above.
  const growthQoQ = (f, i) => {
    const pq = parseQPeriod(cols[i]);
    if (!pq) return null;
    const prevKey = pq.q === 1 ? `${pq.y - 1}Q4` : `${pq.y}Q${pq.q - 1}`;
    const v = series[f].values[cols[i]], prev = series[f].values[prevKey];
    if (!Number.isFinite(v) || !Number.isFinite(prev) || prev === 0) return null;
    return { value: ((v - prev) / Math.abs(prev)) * 100 };
  };
  // The unit comes from the server, which owns the scale contract: money in
  // full UZS, every margin already converted to percent, plain coefficients
  // left alone. Nothing here decides what a number means.
  //
  // Sums print in full, not «3,1B»: the wrap scrolls sideways, so a long number
  // cannot break the layout — a bank's trillions just make the table wider.
  // The chart keeps compact figures: its axis has 70px, not a column.
  const fmtFull = new Intl.NumberFormat(lang === "en" ? "en-US" : "ru-RU",
                                        { maximumFractionDigits: 0 });
  const cell = (f, p) => {
    const v = series[f].values[p];
    if (!Number.isFinite(v)) return "—";
    if (series[f].money) return fmtFull.format(v);
    const suffix = series[f].unit === "%" ? "%" : "";
    return `${formatRatio(v, 2, lang)}${suffix}`;
  };

  const rowsBlock = (fields, withGrowth) => fields.map((f) => (
    <React.Fragment key={f}>
      <tr>
        <th scope="row">
          <button type="button"
            className={`fin-row-toggle ${selected.includes(f) ? "on" : ""}`}
            aria-pressed={selected.includes(f)}
            onClick={() => toggleChartField(f)}
            title={selected.includes(f)
              ? t("Убрать с графика", "Grafikdan olib tashlash", "Remove from chart")
              : t("Показать на графике", "Grafikda korsatish", "Show on chart")}>
            <i className="fin-row-dot"
              style={selected.includes(f) ? { background: colorOf(f) } : undefined} />
            {finLabel(f, lang)}
          </button>
          {/* Beside the label, not inside the toggle: the row header is already
              a button (it draws the line on the chart), and a button inside a
              button is invalid markup — the ⓘ would put a line on the chart
              instead of explaining the term. */}
          <TermInfo termId={FIN_FIELD_TERMS[f]} lang={lang} label={finLabel(f, lang)} />
        </th>
        {cols.map((p) => {
          const value = series[f].values[p];
          if (!Number.isFinite(value)) return <td key={p} className="num">—</td>;
          return (
            <td key={p} className="num fin-passport-cell">
              <button type="button" onClick={() => openPassport(f, p)}
                title={t("Открыть паспорт источника", "Manba pasportini ochish", "Open source passport")}>
                {cell(f, p)}
              </button>
            </td>
          );
        })}
      </tr>
      {/* Only when there is a year to compare against: on a single-period
          issuer (ACMT1B2, UZNF and seven more) this row was a line of dashes
          under a heading promising growth. */}
      {withGrowth && cols.length > 1 && (
        <tr className="fin-growth">
          <th scope="row">{t("Рост г/г", "Osish y/y", "Growth YoY")}</th>
          {cols.map((p, i) => {
            const g = growth(f, i);
            const v = g && !g.gap ? g.value : null;
            return (
              <td key={p} className={`num ${v == null ? "" : v >= 0 ? "pos" : "neg"}`}
                title={g && g.gap
                  ? t(`Нет отчёта за ${g.missing} — рост за год не посчитать`,
                      `${g.missing} uchun hisobot yo'q`,
                      `No filing for ${g.missing} — a year-on-year change cannot be formed`)
                  : undefined}>
                {v == null ? "—" : `${signedFixed(v)}%`}
              </td>
            );
          })}
        </tr>
      )}
      {withGrowth && quarterly && cols.length > 1 && (
        <tr className="fin-growth">
          <th scope="row">{t("Рост кв/кв", "Osish ch/ch", "Growth QoQ")}</th>
          {cols.map((p, i) => {
            const g = growthQoQ(f, i);
            const v = g ? g.value : null;
            return (
              <td key={p} className={`num ${v == null ? "" : v >= 0 ? "pos" : "neg"}`}>
                {v == null ? "—" : `${signedFixed(v)}%`}
              </td>
            );
          })}
        </tr>
      )}
    </React.Fragment>
  ));

  return (
    <div className="company-financials">
      <div className="fin-subtabs">
        {available.map((sec) => (
          <button key={sec.key} type="button"
            className={`fin-subtab ${section !== "splits" && active.key === sec.key ? "active" : ""}`}
            onClick={() => setSection(sec.key)}>
            {sec.label[lang === "uz" ? 1 : lang === "en" ? 2 : 0]}
          </button>
        ))}
        {/* «Сплиты» is always on the bar, as uzse.uz always shows the link:
            for most securities its content is honestly «не зафиксировано»,
            and hiding the tab would make the seven that DID split look like
            the only ones anyone checked. */}
        <button type="button"
          className={`fin-subtab ${section === "splits" ? "active" : ""}`}
          onClick={() => setSection("splits")}>
          {t("Сплиты", "Splitlar", "Splits")}
        </button>
        {section !== "splits" && (
          <>
        {standardToggle}
        {freqToggle}
            {/* Line | Bars | Table. Sits with the period switch because it answers
                the same kind of question — how to READ this section, not which
                section — and the two are the only controls this tab has. Neither
                applies to the splits register, so both leave the bar with it. */}
            <div className="fin-freq fin-dash" role="group"
              aria-label={t("Вид", "Ko'rinish", "View")}>
              {FIN_DASHBOARDS.map((d) => (
                <button key={d.key} type="button"
                  className={`fin-freq-btn ${dashboard === d.key ? "active" : ""}`}
                  aria-pressed={dashboard === d.key}
                  onClick={() => setDashboard(d.key)}>
                  {d.label[lang === "uz" ? 1 : lang === "en" ? 2 : 0]}
                </button>
              ))}
            </div>
          </>
        )}
      </div>

      {section === "splits" ? (
        <CompanySplitsTable items={splits === undefined ? null : splits} lang={lang} />
      ) : (
      <div className="panel fin-panel">
        {dashboard !== "table" && (
          <>
            {/* In a chart view the table is not on screen, so its row headers
                cannot be what picks the lines. Every row of the section is a
                chip here: the legend below the chart can only take a line away,
                and a reader who has switched them all off would otherwise be
                looking at an empty frame with no way back. */}
            <div className="fin-picker">
              {sectionFields.filter(has).map((f) => (
                <button key={f} type="button"
                  className={`fin-picker-chip ${selected.includes(f) ? "on" : ""}`}
                  aria-pressed={selected.includes(f)}
                  onClick={() => toggleChartField(f)}>
                  <i style={selected.includes(f) ? { background: colorOf(f) } : undefined} />
                  {finLabel(f, lang)}
                </button>
              ))}
            </div>
            {dashboard === "bar"
              ? <FinancialsBars fields={chartFields} series={series} periods={cols} lang={lang}
                  colorOf={colorOf} onToggle={toggleChartField} />
              : <FinancialsChart fields={chartFields} series={series} periods={cols} lang={lang}
                  colorOf={colorOf} onToggle={toggleChartField} />}
            {chartFields.length === 0 && (
              <p className="fin-note muted" style={{ textAlign: "center" }}>
                {t("Выберите показатель выше, чтобы построить график",
                   "Grafik uchun yuqoridan ko'rsatkich tanlang",
                   "Pick an indicator above to draw the chart")}
              </p>
            )}
          </>
        )}

        {dashboard === "table" && (
        <div className="fin-table-wrap">
          <table className="fin-table">
            <thead>
              <tr>
                <th scope="col">{quarterly
                  ? t("Квартальные данные", "Choraklik malumotlar", "Fiscal quarter")
                  : t("Годовые данные", "Yillik malumotlar", "Fiscal year")}</th>
                {cols.map((p) => <th key={p} scope="col" className="num">{finPeriodLabel(p)}</th>)}
              </tr>
            </thead>
            <tbody>
              {rowsBlock(active.rows || [], true)}
              {(active.margins || []).length > 0 && (active.rows || []).length > 0 && (
                <tr className="fin-section-row">
                  <th scope="row" colSpan={cols.length + 1}>
                    {t("Маржинальность", "Marjinallik", "Margin Analysis")}
                  </th>
                </tr>
              )}
              {rowsBlock(active.margins || [], false)}
            </tbody>
          </table>
        </div>
        )}

        <p className="fin-note muted">
          {quarterly
            ? t("Суммы в сумах, за отдельный квартал (3 месяца) — рассчитаны из накопительных квартальных отчётов НСБУ; IV квартал — разница годового и девятимесячного отчётов. Рост г/г — к тому же кварталу прошлого года, кв/кв — к предыдущему кварталу. Активы, обязательства и капитал — на конец квартала.",
                "Summalar somda, alohida chorak (3 oy) uchun — NSBU choraklik hisobotlaridan hisoblangan; IV chorak — yillik va 9 oylik hisobotlar farqi. Osish y/y — otgan yilning shu chorogiga, ch/ch — oldingi chorakka nisbatan. Aktivlar, majburiyatlar va kapital — chorak oxiriga.",
                "Sums in UZS per discrete quarter (3 months), derived from the cumulative NSBU filings; Q4 is the annual less the nine-month filing. Growth YoY compares the same quarter a year earlier, QoQ the preceding quarter. Assets, liabilities and equity are quarter-end snapshots.")
            : t("Суммы в сумах, по годовым отчётам эмитента. Коэффициенты — в тех единицах, в которых они опубликованы.",
                "Summalar somda, emitentning yillik hisobotlari boyicha.",
                "Sums in UZS, from the issuer's annual filings. Ratios in the units they were published in.")}
          {/* Said once, under the table, rather than left for the reader to
              notice that 2019 is simply not there. Half the issuers on this
              market have at least one such hole. */}
          {!quarterly && missingYears.length > 0 && (
            <> {t(`За ${missingYears.join(", ")} годовой отчётности нет — эти годы пропущены, и рост к ним не считается.`,
                  `${missingYears.join(", ")} uchun yillik hisobot yo'q.`,
                  `No annual filing for ${missingYears.join(", ")} — those years are absent, and no growth is formed against them.`)}</>
          )}
        </p>
      </div>
      )}
      {passportTarget && (
        <FinancialPassportDialog passport={passport} loading={passportLoading}
          field={passportTarget.field} period={passportTarget.period} lang={lang}
          onClose={() => { setPassportTarget(null); setPassport(null); }} />
      )}
    </div>
  );
}

function CompanyDividendsTab({ items, loading, lang, isPreferred, lastPrice }) {
  // openinfo's calendar also carries decisions that declared nothing — Aloqabank
  // files four of them dated 11.06.2013 alone, and they render as rows of dashes
  // that read like a broken table. They stay available behind the toggle, because
  // "the meeting resolved to pay nothing" is an answer to the question the tab asks.
  const [showSilent, setShowSilent] = React.useState(false);
  const t = (ru, uz, en) => (lang === "uz" ? uz : lang === "en" ? en : ru);
  const locale = lang === "en" ? "en-US" : "ru-RU";
  const fmt = (v) => v == null ? "—" : Number(v).toLocaleString(locale, { maximumFractionDigits: 2 });
  const fmtDate = (d) => d ? new Date(d).toLocaleDateString(locale, { year: "numeric", month: "short", day: "numeric" }) : "—";

  if (loading) return <div className="chart-loading muted">{t("Загрузка...", "Yuklanmoqda...", "Loading...")}</div>;
  const rows = items || [];
  if (rows.length === 0) return (
    <div className="panel" style={{ padding: 32, textAlign: "center" }}>
      <p className="muted">{t("Дивиденды не объявлялись", "Dividendlar e'lon qilinmagan", "No dividends on record")}</p>
    </div>
  );

  // Same rule as the key-stats rail — see dividendSummary().
  const { latest, latestAmt, yieldPct, declared, payouts, latestYear, latestIsRecent } =
    dividendSummary(rows, { isPreferred, lastPrice });
  // O'zsanoatqurilishbank files 92 calendar entries and declared a payout in 9 of
  // them. When an issuer declared nothing at all there is nothing to fold away —
  // the silent filings ARE the record, so they stay on screen.
  const silent = payouts === 0 ? 0 : rows.length - payouts;
  const visible = (showSilent || payouts === 0) ? rows : declared;

  return (
    <div className="company-dividends">
      <div className="dividend-cards">
        <div className="dividend-card panel">
          <div className="dividend-card-label">{t("Последний дивиденд", "Oxirgi dividend", "Latest dividend")}</div>
          <div className="dividend-card-val">{fmt(latestAmt)} <span className="dividend-card-unit">{t("сум/акц.", "so'm/aksiya", "UZS/sh")}</span></div>
          {latest && <div className="muted" style={{ fontSize: 12 }}>{fmtDate(latest.decision_date)}</div>}
        </div>
        {yieldPct != null && (
          <div className="dividend-card panel">
            <div className="dividend-card-label">{t("Дивидендная доходность", "Dividend daromadliligi", "Dividend yield")}</div>
            <div className="dividend-card-val">{yieldPct.toFixed(2)}%</div>
            {/* The last payout is not always a recent one: SQBN's ordinary line was
                last paid in 2019 while its preferred line still pays every year. A
                bare "к текущей цене" then reads as this year's yield, so the caption
                names the year the figure actually comes from. */}
            <div className="muted" style={{ fontSize: 12 }}>
              {latestYear && !latestIsRecent
                ? t(`по выплате ${latestYear} г. к текущей цене`, `${latestYear}-yil to'lovi bo'yicha`, `on the ${latestYear} payout, at the current price`)
                : t("к текущей цене", "joriy narxga", "to current price")}
            </div>
          </div>
        )}
        <div className="dividend-card panel">
          <div className="dividend-card-label">{t("Выплат в истории", "Tarixdagi to'lovlar", "Payouts on record")}</div>
          <div className="dividend-card-val">{payouts}</div>
        </div>
      </div>
      <div className="dividend-table-wrap panel">
        <table className="dividend-table">
          <thead>
            <tr>
              <th>{t("Дата решения", "Qaror sanasi", "Decision date")}</th>
              <th className="dividend-num">{t("Обыкн., сум", "Oddiy, so'm", "Ordinary, UZS")}</th>
              <th className="dividend-num">%</th>
              <th className="dividend-num">{t("Прив., сум", "Imtiyozli, so'm", "Preferred, UZS")}</th>
              <th className="dividend-num">%</th>
              <th>{t("Реестр / выплата", "Reyestr / to'lov", "Record / payment")}</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {visible.map((r, i) => (
              <tr key={i}>
                <td>{fmtDate(r.decision_date)}</td>
                <td className="dividend-num">{r.ordinary_amount ? fmt(r.ordinary_amount) : "—"}</td>
                <td className="dividend-num muted">{r.ordinary_percent ? `${fmt(r.ordinary_percent)}%` : "—"}</td>
                <td className="dividend-num">{r.preferred_amount ? fmt(r.preferred_amount) : "—"}</td>
                <td className="dividend-num muted">{r.preferred_percent ? `${fmt(r.preferred_percent)}%` : "—"}</td>
                {/* The payment window belongs to the share class being viewed: a
                    filing declares a separate one for the preferred line, and a
                    preferred page showing the ordinary window dates the wrong payout. */}
                <td className="muted" style={{ fontSize: 12, whiteSpace: "nowrap" }}>{(() => {
                  const start = isPreferred ? (r.preferred_start || r.ordinary_start) : r.ordinary_start;
                  const end = isPreferred ? (r.preferred_end || r.ordinary_end) : r.ordinary_end;
                  return (start || end) ? `${fmtDate(start)} – ${fmtDate(end)}` : "—";
                })()}</td>
                <td>{r.link && <a href={r.link} target="_blank" rel="noreferrer" className="ghost-btn" style={{ fontSize: 12 }}>→</a>}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {silent > 0 && (
        <button type="button" className="ghost-btn" style={{ fontSize: 12, marginTop: 10 }}
                onClick={() => setShowSilent((v) => !v)}>
          {showSilent
            ? t("Скрыть решения без выплаты", "To'lovsiz qarorlarni yashirish", "Hide no-payout decisions")
            : t(`Показать ещё ${silent} решений без выплаты`, `Yana ${silent} ta to'lovsiz qaror`, `Show ${silent} more no-payout decisions`)}
        </button>
      )}
      {yieldPct != null && (
        <p className="muted" style={{ fontSize: 11, marginTop: 10 }}>
          {t("Доходность рассчитана по последней цене и без учёта даты закрытия реестра.", "Daromadlilik oxirgi narx bo'yicha hisoblangan.", "Yield is computed against the latest price, before the record date.")}
        </p>
      )}
    </div>
  );
}

function CompanyForecastTab({ ticker, language, apiFetch, signedIn, hasProAccess, onUpgrade }) {
  const lang = normalizeLanguage(language);
  const t = (ru, uz, en) => (lang === "uz" ? uz : lang === "en" ? en : ru);
  const [standard, setStandard] = React.useState("NSBU");
  const [state, setState] = React.useState({ loading: false, forecast: null, backtest: null, error: "" });
  const [retry, setRetry] = React.useState(0);

  React.useEffect(() => {
    if (!hasProAccess || !ticker) return undefined;
    let alive = true;
    setState({ loading: true, forecast: null, backtest: null, error: "" });
    const qs = `form=${encodeURIComponent(standard)}`;
    Promise.all([
      apiFetch(`/api/company/${encodeURIComponent(ticker)}/forecast?${qs}`).then(async (response) => {
        const body = await response.json().catch(() => null);
        if (!response.ok || !body?.ok) throw new Error(body?.detail?.message || body?.detail || "Forecast unavailable");
        return body;
      }),
      apiFetch(`/api/company/${encodeURIComponent(ticker)}/forecast/backtest?${qs}`).then(async (response) => {
        const body = await response.json().catch(() => null);
        if (!response.ok || !body?.ok) throw new Error(body?.detail?.message || body?.detail || "Backtest unavailable");
        return body;
      }),
    ]).then(([forecast, backtest]) => {
      if (alive) setState({ loading: false, forecast, backtest, error: "" });
    }).catch((error) => {
      if (alive) setState({ loading: false, forecast: null, backtest: null, error: String(error?.message || error) });
    });
    return () => { alive = false; };
  }, [ticker, standard, retry, hasProAccess, apiFetch]);

  const title = t("Прогноз и справедливая цена", "Prognoz va adolatli qiymat", "Forecast & fair value");
  if (!hasProAccess) return <ProFeatureGate language={lang} title={title}
    description={t("Три сценария, прозрачные предпосылки, диапазон справедливой цены и бэктест доступны в PRO.", "Uchta ssenariy, shaffof taxminlar, adolatli narx oralig‘i va backtest PROda mavjud.", "Three scenarios, transparent assumptions, fair-value range and backtest are available with PRO.")}
    signedIn={signedIn} onUpgrade={onUpgrade} />;

  const forecast = state.forecast;
  const backtest = state.backtest;
  const fmtMoney = (value) => Number.isFinite(Number(value))
    ? `${formatMarketNumber(Number(value) * 1000, lang)} ${t("сум", "so‘m", "UZS")}` : "—";
  const fmtPrice = (value) => Number.isFinite(Number(value))
    ? `${formatMarketNumber(value, lang)} ${t("сум", "so‘m", "UZS")}` : "—";
  return (
    <section className="company-forecast stack">
      <div className="basis-bar">
        <div>
          <strong>{title}</strong>
          <span className="muted" style={{ display: "block", marginTop: 4, fontSize: 12 }}>
            {t("Модель не является инвестиционной рекомендацией. Вероятности не публикуются без калибровки.", "Model investitsiya tavsiyasi emas. Kalibrlashsiz ehtimollar chop etilmaydi.", "This model is not investment advice. Probabilities are withheld until calibrated.")}
          </span>
        </div>
        <div className="fin-freq" role="group" aria-label={t("Стандарт", "Standart", "Standard")}>
          {["NSBU", "MSFO"].map((code) => <button key={code} type="button"
            className={`fin-freq-btn ${standard === code ? "active" : ""}`} onClick={() => setStandard(code)}>{code === "NSBU" ? "НСБУ" : "МСФО"}</button>)}
        </div>
      </div>
      {state.loading && <div className="chart-loading muted">{t("Загрузка прогноза…", "Prognoz yuklanmoqda…", "Loading forecast…")}</div>}
      {state.error && <div className="panel" style={{ padding: 20 }}><p>{state.error}</p><button className="primary-btn" type="button" onClick={() => setRetry((n) => n + 1)}>{t("Повторить", "Qayta urinish", "Retry")}</button></div>}
      {!state.loading && forecast?.status === "NO_DATA" && <div className="panel" style={{ padding: 24 }}>
        <h3>{t("Прогноз пока недоступен", "Prognoz hozircha mavjud emas", "Forecast is not available yet")}</h3><p className="muted">{forecast.reason}</p>
      </div>}
      {!state.loading && forecast?.status === "AVAILABLE" && <>
        <div className="grid3">
          {(forecast.scenarios || []).map((row) => <article className="panel pad" key={row.scenario}>
            <span className="panel-label">{row.scenario === "downside" ? t("Негативный", "Salbiy", "Downside") : row.scenario === "upside" ? t("Позитивный", "Ijobiy", "Upside") : t("Базовый", "Asosiy", "Base")}</span>
            <strong className="big-number">{formatSignedPercent(row.revenue_growth_pct, 1)}</strong>
            <div className="metric-list"><div><span>{t("Выручка", "Tushum", "Revenue")}</span><b>{fmtMoney(row.revenue)}</b></div><div><span>{t("Чистая прибыль", "Sof foyda", "Net income")}</span><b>{fmtMoney(row.net_profit)}</b></div><div><span>EPS</span><b>{fmtPrice(row.eps)}</b></div></div>
          </article>)}
        </div>
        <article className="panel pad">
          <div className="section-title" style={{ marginTop: 0 }}><h2>{t("Справедливая цена", "Adolatli narx", "Fair value")}</h2><span className="muted">{forecast.fair_value?.method || t("Нет проверяемого метода", "Tekshiriladigan usul yo‘q", "No verified method")}</span></div>
          {forecast.fair_value?.status === "AVAILABLE" ? <div className="grid3">
            {[["lower", t("Нижняя", "Pastki", "Lower")], ["mid", t("Базовая", "Asosiy", "Mid")], ["upper", t("Верхняя", "Yuqori", "Upper")]].map(([key, label]) => <div className="kpi" key={key}><div className="label">{label}</div><div className="value">{fmtPrice(forecast.fair_value[key])}</div><div className="hint">P/E {formatRatio(forecast.fair_value.peer_pe?.[key], 2, lang)}</div></div>)}
          </div> : <p className="muted">{forecast.fair_value?.reason}</p>}
          <div className="panel-foot">{t("Факты по состоянию на", "Faktlar holati", "Facts as of")}: {forecast.facts_as_of_year || "—"} · {t("Группа аналогов", "Taqqoslanadigan guruh", "Peer group")}: {forecast.peer_population?.count || 0} ({forecast.peer_population?.sector || t("не определён", "aniqlanmagan", "not mapped")})</div>
        </article>
        <article className="panel pad">
          <h2 className="section-heading">{t("Предпосылки и контроль качества", "Taxminlar va sifat nazorati", "Assumptions & quality control")}</h2>
          <div className="metric-list"><div><span>{t("Метод", "Usul", "Method")}</span><b>{forecast.assumptions?.method}</b></div><div><span>{t("Исторические годы", "Tarixiy yillar", "Historical years")}</span><b>{(forecast.historical_years || []).join(", ") || "—"}</b></div><div><span>{t("Версия модели", "Model versiyasi", "Model version")}</span><b>{forecast.model_version || "—"}</b></div></div>
          <div className="callout amber" style={{ marginTop: 14 }}><span className="ico">!</span><div><strong>{t("Публикация заблокирована", "Chop etish bloklangan", "Publication blocked")}</strong><br />{forecast.quality?.reason}</div></div>
        </article>
      </>}
      {!state.loading && backtest && <article className="panel pad">
        <div className="section-title" style={{ marginTop: 0 }}><h2>{t("Walk-forward бэктест", "Walk-forward backtest", "Walk-forward backtest")}</h2><span className={`status-tag ${backtest.status === "AVAILABLE" ? "warn" : ""}`}>{backtest.status}</span></div>
        {backtest.status === "AVAILABLE" ? <><div className="grid3"><div className="kpi"><div className="label">MAE</div><div className="value">{formatRatio(backtest.mae_pct, 2, lang)}%</div></div><div className="kpi"><div className="label">{t("Наблюдения", "Kuzatuvlar", "Observations")}</div><div className="value">{backtest.trials?.length || 0}</div></div><div className="kpi"><div className="label">{t("Хронология", "Xronologiya", "Chronology")}</div><div className="value">{backtest.chronology_verified ? t("Проверена", "Tekshirilgan", "Verified") : t("Неполная", "To‘liq emas", "Incomplete")}</div></div></div><p className="muted" style={{ marginTop: 14 }}>{backtest.reason}</p></> : <p className="muted">{backtest.reason}</p>}
      </article>}
    </section>
  );
}

function CompanyPage({ ticker, securitiesMap, language, onBack, onAnalyze, onOpenCompany, onOpenChart, marketRows, financials, tradeStats, favoriteTickers, onToggleFavorite, signedIn, hasProAccess = false, apiFetch = fetch, onUpgrade }) {
  const lang = normalizeLanguage(language);
  const [tab, setTab] = React.useState("overview");

  // A company is a new page, even though the SPA swaps it into the same
  // document. Reset the previous view's scroll offset before paint so opening
  // a row near the bottom of the market board still shows the company header.
  React.useLayoutEffect(() => {
    window.scrollTo({ top: 0, left: 0, behavior: "auto" });
  }, [ticker]);
  // Issuer-level multiples, straight from the endpoint the market board reads.
  const [mult, setMult] = React.useState(null);
  // A SECOND metrics call, pinned to twelve months. The main one follows the
  // period button by design (ТЗ §5), so reading the 52-week range off it would
  // relabel a one-month high as a yearly one the moment somebody pressed «1М».
  const [metrics12, setMetrics12] = React.useState(null);
  const [priceHistory, setPriceHistory] = React.useState(null);
  // Non-empty only for a series that spans a split or a bonus issue — the chart has to
  // say the older prices were restated, or they read as wrong against uzse.uz.
  const [priceAdjustments, setPriceAdjustments] = React.useState([]);
  // Hourly bars from the exchange's executions log (/api/intraday) — what 1Д
  // draws and what 1Н mixes with daily closes. Fetched once per ticker, not per
  // range: the whole answer is a week of bars.
  const [intraday, setIntraday] = React.useState(null);
  // The button's identity, not a month count: 1Н and 1М both fetch one month,
  // and YTD's month count moves through the year. `chartRangeMonths` turns it
  // into what the endpoint understands.
  const [priceRange, setPriceRange] = React.useState("1y");
  const priceMonths = chartRangeMonths(priceRange);
  // The chart initially shows `priceRange`, but Ctrl+wheel and dragging can
  // reveal the archive behind it. Fetch the same depth as «Макс» once per
  // issuer; metrics remain pinned to the selected range below.
  const priceArchiveMonths = chartRangeMonths("max");
  const [priceLoading, setPriceLoading] = React.useState(false);
  // Window + absolute price metrics from /api/company/{ticker}/metrics.
  const [metrics, setMetrics] = React.useState(null);
  const [secInfo, setSecInfo] = React.useState((securitiesMap || {})[ticker] || null);
  const [infoLoading, setInfoLoading] = React.useState(false);
  const [companyData, setCompanyData] = React.useState(null);
  const [dividends, setDividends] = React.useState(null);
  // The issuer's annual series (fact store). Lazy: only the Финансы tab
  // reads it, and most visits never open that tab.
  const [finSeries, setFinSeries] = React.useState(null);
  const [finLoading, setFinLoading] = React.useState(false);
  // IFRS and NSBU are separate accounting contours.  A form choice therefore
  // invalidates the cached series; retaining NSBU rows while the header says
  // IFRS would be worse than a temporary loading state.
  const [finStandard, setFinStandard] = React.useState("NSBU");
  // The Финансы tab's period switch. The quarterly series is its own request
  // and its own cache: nobody pays for quarters they never open.
  const [finFreq, setFinFreq] = React.useState("annual");
  const [finQSeries, setFinQSeries] = React.useState(null);
  const [finQLoading, setFinQLoading] = React.useState(false);
  // The splits register for the «Сплиты» sub-tab. Lazy with the rest of the
  // Финансы data; null = not asked yet, [] = asked and the record is empty.
  const [splits, setSplits] = React.useState(null);
  const [divLoading, setDivLoading] = React.useState(false);

  // Failed requests must be visible and retryable: every fetch below reports
  // an error state instead of silently leaving the page blank, and an `alive`
  // guard keeps a late response for a previous ticker from overwriting state.
  const [priceError, setPriceError] = React.useState(false);
  const [priceRetry, setPriceRetry] = React.useState(0);
  const [companyDataError, setCompanyDataError] = React.useState(false);
  const [companyDataRetry, setCompanyDataRetry] = React.useState(0);
  const [insightReport, setInsightReport] = React.useState(null);
  const [insightLoading, setInsightLoading] = React.useState(true);
  const [insightError, setInsightError] = React.useState(false);
  const [insightRetry, setInsightRetry] = React.useState(0);
  const [insightOpen, setInsightOpen] = React.useState(false);
  const insightTriggerRef = React.useRef(null);
  const closeInsight = React.useCallback(() => {
    setInsightOpen(false);
    window.requestAnimationFrame(() => insightTriggerRef.current?.focus());
  }, []);

  // Every board row, reconciled against the stored day statistics exactly as the
  // market table does it — the watch rail quotes other securities and must quote
  // them the way the board does. Computed here, above the effects, because the
  // sparkline request is keyed on which tickers the rail will show.
  const preparedRows = React.useMemo(() => {
    const day = latestTradeStatsDay(tradeStats || {});
    return (marketRows || []).map(enrichMarketStock)
      .map((r) => applyTradeStats(r, tradeStats || {}, day));
  }, [marketRows, tradeStats]);
  const railTickers = React.useMemo(() => {
    const { favRows, bySector, movers } = watchRailLists({
      ticker, rows: preparedRows, securitiesMap, favorites: favoriteTickers,
    });
    return [...new Set([...favRows, ...bySector, ...movers]
      .map((r) => String(r.ticker || "").toUpperCase()))].sort();
  }, [ticker, preparedRows, securitiesMap, favoriteTickers]);

  // Быстрое сравнение: which securities the strip offers, which of them are on
  // the chart, and their stored closes. The selection is the reader's and is
  // dropped when the page changes issuer — carrying UZTL's peers onto KSCM's
  // chart would compare a set nobody chose.
  const comparePeers = React.useMemo(
    () => quickComparePeers({ ticker, rows: preparedRows, securitiesMap }),
    [ticker, preparedRows, securitiesMap],
  );
  const [compareTickers, setCompareTickers] = React.useState([]);
  const [compareSeries, setCompareSeries] = React.useState({});
  const [compareLoading, setCompareLoading] = React.useState(false);
  React.useEffect(() => { setCompareTickers([]); }, [ticker]);
  const toggleCompare = React.useCallback((tk) => {
    const up = String(tk || "").toUpperCase();
    setCompareTickers((cur) => (cur.includes(up)
      ? cur.filter((x) => x !== up)
      : cur.length >= QC_MAX ? cur : [...cur, up]));
  }, []);
  // The same stored-close endpoint the watch rail's sparklines read — one
  // request for the whole selection, not one per line. `days` is a count of
  // SESSIONS, not calendar days, so ask for everything the store holds and let
  // the chart trim to the range on screen.
  const compareKey = [...compareTickers].sort().join(",");
  React.useEffect(() => {
    // Cleared while a request was in flight: the flag has to fall with the
    // selection, or the strip keeps saying «загрузка…» over an empty chart.
    if (!compareKey) { setCompareLoading(false); return undefined; }
    let alive = true;
    setCompareLoading(true);
    fetch(`/api/quotes/series?tickers=${encodeURIComponent(compareKey)}&days=3650`)
      .then((r) => r.json())
      // Merged, not replaced: adding a second security must not make the first
      // one's line blink out while the request is in flight.
      .then((d) => { if (alive && d && d.ok) setCompareSeries((s) => ({ ...s, ...(d.series || {}) })); })
      .catch(() => {})
      .finally(() => { if (alive) setCompareLoading(false); });
    return () => { alive = false; };
  }, [compareKey]);
  const compareLines = React.useMemo(() => compareTickers.map((tk, i) => ({
    ticker: tk,
    color: QC_COLORS[i % QC_COLORS.length],
    points: compareSeries[tk] || null,
  })), [compareTickers, compareSeries]);

  React.useEffect(() => {
    if (!ticker) return undefined;
    let alive = true;
    setPriceLoading(true);
    setPriceError(false);
    fetch(`/api/price-history/${encodeURIComponent(ticker)}?months=${priceArchiveMonths}`)
      .then((r) => r.json())
      .then((d) => {
        if (!alive) return;
        if (d.ok) {
          setPriceHistory(d.points || []);
          setPriceAdjustments(d.adjustments || []);
        } else setPriceError(true);
      })
      .catch(() => { if (alive) setPriceError(true); })
      .finally(() => { if (alive) setPriceLoading(false); });
    return () => { alive = false; };
  }, [ticker, priceArchiveMonths, priceRetry]);

  React.useEffect(() => {
    if (!ticker) return undefined;
    let alive = true;
    setIntraday(null);
    // Failure degrades, never blocks: with no bars the 1Н button draws daily
    // closes exactly as before, and 1Д says the bank is still empty.
    fetch(`/api/intraday/${encodeURIComponent(ticker)}?days=8`)
      .then((r) => r.json())
      .then((d) => { if (alive) setIntraday(d.ok ? (d.points || []) : []); })
      .catch(() => { if (alive) setIntraday([]); });
    return () => { alive = false; };
  }, [ticker]);

  // Metrics are the server's job (ТЗ §3, second principle: one calc layer, and
  // the screen is not one of its implementations). The page reads `quality`
  // — whether the security trades often enough to be drawn as a slope rather
  // than a step — `ma_windows`, and now the `window` block, which is what the
  // rail's «За период» states. Keyed on the RANGE, not on the month count: 1Н
  // and 1М both fetch one month of history but measure different windows.
  React.useEffect(() => {
    if (!ticker) return undefined;
    let alive = true;
    fetch(`/api/company/${encodeURIComponent(ticker)}/metrics?months=${priceMonths}${chartRangeWindowQuery(priceRange)}`)
      .then((r) => r.json())
      .then((d) => { if (alive) setMetrics(d.ok ? d : null); })
      .catch(() => { if (alive) setMetrics(null); });
    return () => { alive = false; };
  }, [ticker, priceMonths, priceRange, priceRetry]);

  // Dividends are no longer lazy: the key-stats rail states the last payout and
  // its yield on the Обзор tab, so waiting for the Дивиденды tab to be opened
  // would leave the rail permanently short of the one figure an equity holder
  // opens the page for.
  React.useEffect(() => {
    if (!ticker) return undefined;
    let alive = true;
    setDividends(null);
    setDivLoading(true);
    fetch(`/api/dividends/${encodeURIComponent(ticker)}`)
      .then((r) => r.json())
      .then((d) => { if (alive) setDividends(d.ok ? (d.items || []) : []); })
      .catch(() => { if (alive) setDividends([]); })
      .finally(() => { if (alive) setDivLoading(false); });
    return () => { alive = false; };
  }, [ticker]);

  React.useEffect(() => {
    setFinSeries(null);
    setFinQSeries(null);
    setSplits(null);
    if (finStandard !== "NSBU") setFinFreq("annual");
  }, [ticker, finStandard]);
  React.useEffect(() => {
    if (!ticker || tab !== "financials" || finSeries !== null) return undefined;
    let alive = true;
    setFinLoading(true);
    fetch(`/api/company/${encodeURIComponent(ticker)}/financials?form=${encodeURIComponent(finStandard)}`)
      .then((r) => r.json())
      .then((d) => { if (alive) setFinSeries(d.ok ? d : { periods: [], series: {} }); })
      .catch(() => { if (alive) setFinSeries({ periods: [], series: {} }); })
      .finally(() => { if (alive) setFinLoading(false); });
    return () => { alive = false; };
  }, [ticker, tab, finStandard, finSeries]);
  React.useEffect(() => {
    if (!ticker || tab !== "financials" || finFreq !== "quarterly" || finQSeries !== null) return undefined;
    let alive = true;
    setFinQLoading(true);
    fetch(`/api/company/${encodeURIComponent(ticker)}/financials?freq=quarterly&form=${encodeURIComponent(finStandard)}`)
      .then((r) => r.json())
      .then((d) => { if (alive) setFinQSeries(d.ok ? d : { periods: [], series: {} }); })
      .catch(() => { if (alive) setFinQSeries({ periods: [], series: {} }); })
      .finally(() => { if (alive) setFinQLoading(false); });
    return () => { alive = false; };
  }, [ticker, tab, finStandard, finFreq, finQSeries]);
  // The splits register, once per ticker and only when the Финансы tab is
  // open — the same laziness as the series above. An error resolves to [],
  // which the table renders as the honest «не зафиксировано».
  React.useEffect(() => {
    if (!ticker || tab !== "financials" || splits !== null) return undefined;
    let alive = true;
    fetch(`/api/company/${encodeURIComponent(ticker)}/splits`)
      .then((r) => r.json())
      .then((d) => { if (alive) setSplits(d.ok ? (d.items || []) : []); })
      .catch(() => { if (alive) setSplits([]); });
    return () => { alive = false; };
  }, [ticker, tab, splits]);

  // ТЗ §8: the server owns this arithmetic, per ISSUER, with the auditor's
  // blocking findings already applied. A failure leaves `mult` null and the rail
  // simply omits the valuation rows — it never falls back to computing them.
  React.useEffect(() => {
    let alive = true;
    fetch("/api/market/multiples")
      .then((r) => r.json())
      .then((d) => {
        if (!alive || !d || !d.ok) return;
        const up = String(ticker || "").toUpperCase();
        setMult((d.items || []).find((it) => String(it.ticker || "").toUpperCase() === up) || null);
      })
      .catch(() => { if (alive) setMult(null); });
    return () => { alive = false; };
  }, [ticker]);

  React.useEffect(() => {
    if (!ticker) return undefined;
    let alive = true;
    fetch(`/api/company/${encodeURIComponent(ticker)}/metrics?months=12`)
      .then((r) => r.json())
      .then((d) => { if (alive) setMetrics12(d.ok ? d : null); })
      .catch(() => { if (alive) setMetrics12(null); });
    return () => { alive = false; };
  }, [ticker, priceRetry]);

  // One request for every sparkline in the watch rail. Keyed on the ticker LIST,
  // so it refetches when the lists change and not when a price ticks — the whole
  // reason this data is stored rather than fetched per row is to keep a list of
  // securities from costing one upstream request each.
  const [railSeries, setRailSeries] = React.useState({});
  const railKey = railTickers.join(",");
  React.useEffect(() => {
    if (!railKey) return undefined;
    let alive = true;
    fetch(`/api/quotes/series?tickers=${encodeURIComponent(railKey)}&days=30`)
      .then((r) => r.json())
      .then((d) => { if (alive && d && d.ok) setRailSeries(d.series || {}); })
      .catch(() => {});
    return () => { alive = false; };
  }, [railKey]);

  React.useEffect(() => {
    if (!ticker) return undefined;
    let alive = true;
    const local = (securitiesMap || {})[ticker];
    if (local) setSecInfo(local);
    setInfoLoading(true);
    fetch(`/api/securities/${encodeURIComponent(ticker)}/info?language=${lang}`)
      .then((r) => r.json())
      .then((d) => {
        if (!alive || !d.ok) return;
        setSecInfo({
          ...(d.security || {}),
          company_description: d.wiki?.extract || d.security?.company_description || null,
          source_url: d.wiki?.page_url || d.security?.source_url || null,
          wiki_title: d.wiki?.title || null,
          info_source: d.wiki?.source || (d.wiki?.extract ? "wikipedia" : null),
        });
      })
      .catch(() => {})
      .finally(() => { if (alive) setInfoLoading(false); });
    return () => { alive = false; };
  }, [ticker, lang]);

  React.useEffect(() => {
    if (!ticker) return undefined;
    let alive = true;
    setCompanyDataError(false);
    fetch(`/api/catalog/company/${encodeURIComponent(ticker)}/reports`)
      .then((r) => r.json())
      .then((d) => {
        if (!alive) return;
        if (d.ok) setCompanyData(d);
        else setCompanyDataError(true);
      })
      .catch(() => { if (alive) setCompanyDataError(true); });
    return () => { alive = false; };
  }, [ticker, companyDataRetry]);

  // The profile teaser and its full report are one response: the concise
  // headline is derived from the same traceable observations as the dialog,
  // so opening «Подробнее» cannot reveal a contradictory assessment.
  React.useEffect(() => {
    if (!ticker) return undefined;
    let alive = true;
    setInsightLoading(true);
    setInsightError(false);
    setInsightReport(null);
    setInsightOpen(false);
    fetch(`/api/v1/issuers/${encodeURIComponent(ticker)}/ai-report?standard=nsbu&scope=separate&lang=${lang}`)
      .then(async (response) => {
        const body = await response.json().catch(() => null);
        if (!response.ok || !body?.ok || !body?.headline) throw new Error("company insight unavailable");
        return body;
      })
      .then((body) => { if (alive) setInsightReport(body); })
      .catch(() => { if (alive) setInsightError(true); })
      .finally(() => { if (alive) setInsightLoading(false); });
    return () => { alive = false; };
  }, [ticker, lang, insightRetry]);

  if (!ticker) return null;
  const sec = secInfo || (securitiesMap || {})[ticker] || {};
  // The header's own row. It used to derive its move as a bare
  // `last_price - close_price`, which is the two-sessions-in-one-day defect
  // previousClose() exists to prevent — see applyTradeStats.
  const marketRow = preparedRows.find((r) => (r.ticker || "").toUpperCase() === ticker.toUpperCase()) || null;
  // Company-level financials for P/E and P/B; mirror the preferred-sibling fallback (TKDM <-> TKDMP).
  const companyFin = (() => {
    const f = financials || {};
    const up = ticker.toUpperCase();
    return f[up] || f[up.endsWith("P") ? up.slice(0, -1) : `${up}P`] || null;
  })();
  // A zero is not a quote: the board mirror fills never-traded listings (MXUS)
  // with literal 0s, and the header was announcing «0 сум» as if it were a price.
  const posPrice = (v) => (Number.isFinite(v) && v > 0 ? v : null);
  const lastPrice = posPrice(marketRow?.lastPrice) ?? posPrice(marketRow?.last_price) ?? posPrice(sec.last_price) ?? null;
  // The move the reconciled row settled on. Only when there is no board row at
  // all does the header fall back to differencing the securities-map closes —
  // and then it has no session to check them against, so it says nothing rather
  // than publishing a difference between two undated prices.
  const priceChange = marketRow
    ? (Number.isFinite(marketRow.changeValue) && Number.isFinite(marketRow.changePercent)
        ? { value: marketRow.changeValue, pct: marketRow.changePercent }
        : null)
    : null;
  // The securities map uses `type`/`share_type`/`is_preferred`/`sector`; some
  // callers pass `security_type`/`stock_type`/`industry`. Accept both shapes.
  const securityType = sec.security_type || sec.type;
  const isPreferred = sec.stock_type === "preferred" || sec.share_type === "preferred" || sec.is_preferred === true;
  const industry = sec.industry || sec.sector;
  const typeLabel = securityType === "bond"
    ? (lang === "ru" ? "Облигация" : lang === "uz" ? "Obligatsiya" : "Bond")
    : isPreferred
      ? (lang === "ru" ? "Прив. акция" : lang === "uz" ? "Imtiyozli" : "Preferred")
      : (lang === "ru" ? "Обыкн. акция" : lang === "uz" ? "Oddiy aksiya" : "Common Share");
  // The feed names only some preferred listings «(привилегированные)» — KFSKP,
  // FRAZP, IPKYP, PLSTP and UPOSP arrive without the suffix while HMKBP and
  // IPTBP carry it. One rule for every header, not the feed's mood.
  const baseName = sec.company_name || sec.name || ticker;
  const displayName = isPreferred && securityType !== "bond" && !/привилегирован/i.test(baseName)
    ? `${baseName} (привилегированные)`
    : baseName;
  const TABS = [
    { key: "overview", label: lang === "ru" ? "Обзор" : lang === "uz" ? "Umumiy" : "Overview" },
    { key: "chart", label: lang === "ru" ? "История цен" : lang === "uz" ? "Narxlar tarixi" : "Price History" },
    ...(securityType !== "bond" ? [{ key: "dividends", label: lang === "ru" ? "Дивиденды" : lang === "uz" ? "Dividendlar" : "Dividends" }] : []),
    { key: "reports", label: lang === "ru" ? "Отчёты" : lang === "uz" ? "Hisobotlar" : "Reports" },
    { key: "financials", label: lang === "ru" ? "Финансы" : lang === "uz" ? "Moliya" : "Financials" },
    ...(securityType !== "bond" ? [{ key: "forecast", label: lang === "ru" ? "Прогноз" : lang === "uz" ? "Prognoz" : "Forecast" }] : []),
  ];
  return (
    <div className="company-page">
      <div className="company-page-header">
        <button className="company-page-back" type="button" onClick={onBack}>
          ← {lang === "ru" ? "Назад" : lang === "uz" ? "Orqaga" : "Back"}
        </button>
        <div className="company-page-hero">
          <CompanyLogo logo={sec.company_logo_url || sec.logo_url} name={baseName} ticker={ticker} />
          <div className="company-page-title">
            <h1>{displayName}</h1>
            <div className="company-page-meta">
              <span className="company-page-ticker">{ticker}</span>
              {sec.isin && <span className="muted" style={{ fontSize: 12 }}>{sec.isin}</span>}
              <span className="company-type-badge">{typeLabel}</span>
              {industry && <span className="sector-chip active" style={{ fontSize: 11, padding: "2px 10px" }}>{sectorLabel(lang, industry)}</span>}
            </div>
          </div>
          <div className="company-page-price">
            {lastPrice != null ? (
              <>
                <div className="company-page-price-val">{Number(lastPrice).toLocaleString("ru-RU")} сум</div>
                {priceChange && (
                  <div className={`company-page-price-change ${priceChange.value >= 0 ? "pos" : "neg"}`}>
                    {signedFixed(priceChange.value)} ({signedFixed(priceChange.pct)}%)
                  </div>
                )}
              </>
            ) : (
              <div className="muted" style={{ fontSize: 13 }}>{lang === "ru" ? "Нет данных" : "No data"}</div>
            )}
            <button className="primary-btn" type="button" style={{ marginTop: 8 }} onClick={() => onAnalyze(ticker)}>
              {lang === "ru" ? "Запустить анализ" : lang === "uz" ? "Tahlil qilish" : "Run Analysis"}
            </button>
          </div>
        </div>
        <div className="company-page-tabs">
          {TABS.map((t) => (
            <button key={t.key} type="button"
              className={`company-tab-btn ${tab === t.key ? "active" : ""}`}
              onClick={() => setTab(t.key)}>
              {t.label}
            </button>
          ))}
        </div>
      </div>
      <div className="company-page-body">
        {tab === "overview" && (
          <CompanyInsightCard
            report={insightReport}
            loading={insightLoading}
            error={insightError}
            onOpen={() => setInsightOpen(true)}
            onRetry={() => setInsightRetry((value) => value + 1)}
            buttonRef={insightTriggerRef}
            lang={lang}
          />
        )}
        {companyDataError && (
          <div className="panel" style={{ padding: "12px 16px", marginBottom: 12, display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, border: "1px solid rgba(220, 80, 80, 0.5)" }}>
            <span style={{ fontSize: 13 }}>
              {lang === "ru" ? "Не удалось загрузить отчёты и показатели компании."
                : lang === "uz" ? "Kompaniya hisobotlari va ko'rsatkichlarini yuklab bo'lmadi."
                : "Failed to load company reports and metrics."}
            </span>
            <button className="primary-btn" type="button" style={{ padding: "6px 14px", fontSize: 13 }}
              onClick={() => setCompanyDataRetry((n) => n + 1)}>
              {lang === "ru" ? "Повторить" : lang === "uz" ? "Qayta urinish" : "Retry"}
            </button>
          </div>
        )}
        {priceError && (tab === "overview" || tab === "chart") && (
          <div className="panel" style={{ padding: "12px 16px", marginBottom: 12, display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, border: "1px solid rgba(220, 80, 80, 0.5)" }}>
            <span style={{ fontSize: 13 }}>
              {lang === "ru" ? "Не удалось загрузить историю цен."
                : lang === "uz" ? "Narxlar tarixini yuklab bo'lmadi."
                : "Failed to load price history."}
            </span>
            <button className="primary-btn" type="button" style={{ padding: "6px 14px", fontSize: 13 }}
              onClick={() => setPriceRetry((n) => n + 1)}>
              {lang === "ru" ? "Повторить" : lang === "uz" ? "Qayta urinish" : "Retry"}
            </button>
          </div>
        )}
        {tab === "overview" && (
          <CompanyOverviewTab sec={sec} ticker={ticker} priceHistory={priceHistory} priceLoading={priceLoading}
            priceAdjustments={priceAdjustments} intraday={intraday}
            compare={{
              peers: comparePeers, securitiesMap, selected: compareTickers,
              onToggle: toggleCompare, series: compareLines, loading: compareLoading,
            }}
            onExpandChart={onOpenChart
              // The advanced chart draws the daily archive and offers no 1Д —
              // expanding from it opens the week instead of an empty frame.
              ? () => onOpenChart(ticker, { range: priceRange === "1d" ? "1w" : priceRange,
                                            type: "line", compare: compareTickers,
                                            indicators: [], fin: [], from: "", to: "" })
              : null}
            priceRange={priceRange} onRangeChange={setPriceRange}
            securityType={securityType} isPreferred={isPreferred} industry={industry}
            marketRow={marketRow} companyData={companyData} financials={companyFin} lang={lang} infoLoading={infoLoading}
            priceMetrics={metrics}
            metrics12={metrics12} mult={mult} dividends={dividends} lastPrice={lastPrice}
            watchRail={
              <CompanyWatchRail ticker={ticker} rows={preparedRows} securitiesMap={securitiesMap}
                series={railSeries} favorites={favoriteTickers} onToggleFavorite={onToggleFavorite}
                onOpen={onOpenCompany} signedIn={signedIn} lang={lang} />
            } />
        )}
        {tab === "chart" && (
          <div className="panel" style={{ padding: 24 }}>
            <h3 className="section-heading" style={{ marginBottom: 16 }}>{lang === "ru" ? `История цен — ${ticker}` : `Price History — ${ticker}`}</h3>
            <CompanyPriceChart history={priceHistory} loading={priceLoading} range={priceRange} onRangeChange={setPriceRange} lang={lang}
              intraday={intraday} quality={metrics?.quality} metricsWindows={metrics?.ma_windows}
              ticker={ticker} compare={compareLines} compareLoading={compareLoading}
              compareTools={{ peers: comparePeers, securitiesMap, selected: compareTickers, onToggle: toggleCompare }}
              onExpand={onOpenChart
                ? () => onOpenChart(ticker, { range: priceRange === "1d" ? "1w" : priceRange,
                                              type: "line", compare: compareTickers,
                                              indicators: [], fin: [], from: "", to: "" })
                : null} />
            <QuickCompareStrip peers={comparePeers} securitiesMap={securitiesMap}
              selected={compareTickers} colors={QC_COLORS} onToggle={toggleCompare}
              lang={lang} loading={compareLoading} />
          </div>
        )}
        {tab === "dividends" && (
          <CompanyDividendsTab items={dividends} loading={divLoading} lang={lang} isPreferred={isPreferred} lastPrice={lastPrice} />
        )}
        {tab === "reports" && (
          <CompanyReportsTab reports={companyData?.reports || []} lang={lang} />
        )}
        {tab === "financials" && (
          <CompanyFinancialsTab ticker={ticker} ratios={companyData?.ratios || {}} lang={lang}
            standard={finStandard} onStandardChange={setFinStandard}
            series={(finFreq === "quarterly" ? finQSeries?.series : finSeries?.series) || {}}
            periods={(finFreq === "quarterly" ? finQSeries?.periods : finSeries?.periods) || []}
            loading={finFreq === "quarterly"
              ? (finQLoading && finQSeries === null)
              : (finLoading && finSeries === null)}
            freq={finFreq} onFreqChange={setFinFreq} splits={splits} />
        )}
        {tab === "forecast" && (
          <CompanyForecastTab ticker={ticker} language={language} apiFetch={apiFetch}
            signedIn={signedIn} hasProAccess={hasProAccess} onUpgrade={onUpgrade} />
        )}
        {insightOpen && insightReport && (
          <CompanyInsightDialog report={insightReport} ticker={ticker} companyName={displayName} lang={lang} onClose={closeInsight} />
        )}
      </div>
    </div>
  );
}

/* ── Расширенный график ─────────────────────────────────────────────────────
 * The reference page's «Expand to advanced chart», on our data: a page of its
 * own at /chart/{TICKER} carrying the whole toolbox — periods and a custom
 * range, four chart types, indicators, fundamentals as their own panes, the
 * peer comparison, a volume strip and a crosshair that reads every series at
 * once.
 *
 * Three things the reference has that our data cannot honestly carry, and are
 * therefore absent rather than faked:
 *   • 1D and 5D. The exchange publishes a SESSION, not a tape we keep — the
 *     smallest true unit here is one close. An intraday button would draw a
 *     day out of a single point.
 *   • Delayed live prices. Ours is the settled record; the header says so.
 *   • Analyst/estimate overlays. Nobody publishes them for this market.
 * ------------------------------------------------------------------------ */

/* The four chart types, as icons — the reference draws the shape each button
 * produces rather than naming it. The name stays as the tooltip and the
 * accessible label: an icon-only control that no screen reader can read is not
 * a simplification, and «От базы» is not a shape anyone recognises cold.
 *
 * Drawn at 24×24 with currentColor so one glyph serves idle, hover, active and
 * disabled without a second asset. */
const AC_TYPE_ICONS = {
  line: (
    <path d="M3 16.5l5-5.5 3.5 3L15 8l6 6.5" />
  ),
  candle: (
    <>
      <path d="M8.5 3.5v17M16 5v14" />
      <rect x="6" y="7.5" width="5" height="8" rx="1" />
      <rect x="13.5" y="9" width="5" height="6.5" rx="1" />
    </>
  ),
  area: (
    <>
      <path d="M3 19V9.5l5 4L12 6l4.5 6 4.5-3.5V19z" fill="currentColor" fillOpacity="0.22" />
      <path d="M3 9.5l5 4L12 6l4.5 6 4.5-3.5" />
    </>
  ),
  baseline: (
    <>
      <path d="M3 12.5h18" strokeDasharray="2.5 2.5" strokeOpacity="0.75" />
      <path d="M3 17l4-7.5 3.5 5 4-8.5 6.5 8" />
    </>
  ),
};

const AC_TYPES = [
  { key: "line", label: ["Линия", "Chiziq", "Line"] },
  { key: "area", label: ["Область", "Maydon", "Area"] },
  { key: "baseline", label: ["От базы", "Bazadan", "Baseline"] },
  { key: "candle", label: ["Свечи", "Shamlar", "Candles"] },
  { key: "bars", label: ["Бары", "Barlar", "Bars"] },
  { key: "columns", label: ["Колонки", "Ustunlar", "Columns"] },
  { key: "kagi", label: ["Каги", "Kagi", "Kagi"] },
  { key: "point_figure", label: ["Крестики-нолики", "Nuqta va shakl", "Point and Figure"] },
  { key: "heikin_ashi", label: ["Хейкин Аши", "Heikin Ashi", "Heikin Ashi"] },
  { key: "renko", label: ["Ренко", "Renko", "Renko"] },
];

const AC_SYNTHETIC_TYPES = new Set(["kagi", "point_figure", "heikin_ashi", "renko"]);
const AC_OHLC_TYPES = new Set(["candle", "bars", "heikin_ashi"]);
const AC_COMPARISON_TYPES = new Set(["line", "area", "baseline", "columns"]);

function acHeikinAshi(points) {
  let previous = null;
  return points.map((point) => {
    const source = [point.open, point.high, point.low, point.close].every((value) => Number.isFinite(value) && value > 0)
      ? point : { ...point, open: point.close, high: point.close, low: point.close };
    const close = (source.open + source.high + source.low + source.close) / 4;
    const open = previous ? (previous.open + previous.close) / 2 : (source.open + source.close) / 2;
    const next = { ...source, open, close, high: Math.max(source.high, open, close), low: Math.min(source.low, open, close) };
    previous = next;
    return next;
  });
}

function acMovementBox(points) {
  const moves = points.slice(1).map((point, i) => Math.abs(point.close - points[i].close)).filter((value) => value > 0).sort((a, b) => a - b);
  if (moves.length) return moves[Math.floor(moves.length / 2)];
  const closes = points.map((point) => point.close).filter(Number.isFinite);
  return Math.max(0.01, (Math.max(...closes) - Math.min(...closes)) / 30 || closes[0] * 0.01 || 1);
}

function acRenko(points) {
  if (!points.length) return { box: 1, bricks: [] };
  const box = acMovementBox(points);
  let level = points[0].close;
  const bricks = [];
  points.slice(1).forEach((point) => {
    while (Math.abs(point.close - level) >= box && bricks.length < 400) {
      const direction = point.close > level ? 1 : -1;
      const next = level + direction * box;
      bricks.push({ from: level, to: next, direction, date: point.date });
      level = next;
    }
  });
  return { box, bricks };
}

function acKagi(points) {
  if (!points.length) return { box: 1, turns: [] };
  const box = acMovementBox(points);
  const turns = [{ value: points[0].close, direction: 0 }];
  let extreme = points[0].close, direction = 0;
  points.slice(1).forEach((point) => {
    const price = point.close;
    if (!direction && Math.abs(price - extreme) >= box) direction = price > extreme ? 1 : -1;
    if ((direction >= 0 && price >= extreme) || (direction <= 0 && price <= extreme)) {
      extreme = price;
      turns[turns.length - 1] = { value: price, direction };
    } else if (Math.abs(price - extreme) >= box) {
      turns.push({ value: extreme, direction }, { value: price, direction: -direction });
      direction *= -1;
      extreme = price;
    }
  });
  return { box, turns };
}

function acPointFigure(points) {
  if (!points.length) return { box: 1, columns: [] };
  const box = acMovementBox(points);
  const columns = [];
  let anchor = points[0].close;
  points.slice(1).forEach((point) => {
    const boxes = Math.floor(Math.abs(point.close - anchor) / box);
    if (!boxes) return;
    const direction = point.close > anchor ? 1 : -1;
    const last = columns.at(-1);
    if (!last || last.direction === direction) {
      if (!last) columns.push({ direction, from: anchor, to: anchor + direction * boxes * box });
      else if ((direction > 0 && point.close > last.to) || (direction < 0 && point.close < last.to)) last.to = anchor + direction * boxes * box;
    } else if (boxes >= 3) {
      columns.push({ direction, from: anchor + direction * box, to: anchor + direction * boxes * box });
    }
    anchor = columns.at(-1)?.to ?? anchor;
  });
  return { box, columns: columns.slice(-120) };
}

// The candle chart is the one view where horizontal density is part of the
// question: a reader needs to open the bars up, then move back through the
// archive without guessing a succession of date ranges. Keep enough bars in
// view that the resulting shape is still a chart rather than a handful of
// disconnected sessions.
const AC_MIN_CANDLE_POINTS = 12;
const acNearestInt = (value) => (value < 0
  ? Math.ceil(value - 0.5)
  : Math.floor(value + 0.5));

function acClampView(view, fallback, total) {
  if (total <= 0) return { start: 0, end: 0 };
  const source = view || fallback || { start: 0, end: total };
  const size = Math.max(1, Math.min(total, acNearestInt(source.end - source.start)));
  const start = Math.max(0, Math.min(total - size, acNearestInt(source.start)));
  return { start, end: start + size };
}

function acZoomView(view, total, anchorRatio, zoomIn, minimumPoints = AC_MIN_CANDLE_POINTS) {
  const size = view.end - view.start;
  const minSize = Math.min(minimumPoints, total);
  const nextSize = Math.max(minSize, Math.min(total,
    acNearestInt(size * (zoomIn ? 0.8 : 1.25))));
  if (nextSize === size) return view;
  const ratio = Math.max(0, Math.min(1, anchorRatio));
  const anchor = view.start + ratio * Math.max(0, size - 1);
  const start = Math.max(0, Math.min(total - nextSize,
    acNearestInt(anchor - ratio * Math.max(0, nextSize - 1))));
  return { start, end: start + nextSize };
}

// Windows are CALENDAR DAYS, never bars — see lib/indicators.js for why that
// is a correctness matter here and not a preference. The labels say «дн.» so
// the screen states the same window the calculation used.
const AC_INDICATORS = [
  { key: "sma50", pane: "price", n: 50, color: "#3b82f6", label: ["SMA 50 дн.", "SMA 50 kun", "SMA 50d"] },
  { key: "sma200", pane: "price", n: 200, color: "#8b5cf6", label: ["SMA 200 дн.", "SMA 200 kun", "SMA 200d"] },
  { key: "ema50", pane: "price", n: 50, color: "#f59e0b", label: ["EMA 50 дн.", "EMA 50 kun", "EMA 50d"] },
  { key: "ema200", pane: "price", n: 200, color: "#ec4899", label: ["EMA 200 дн.", "EMA 200 kun", "EMA 200d"] },
  { key: "bb", pane: "price", n: 20, color: "#14b8a6", label: ["Полосы Боллинджера 20 дн.", "Bollinger 20 kun", "Bollinger Bands 20d"] },
  { key: "rsi", pane: "sub", n: 14, color: "#22d3ee", label: ["RSI 14 дн.", "RSI 14 kun", "RSI 14d"] },
  { key: "macd", pane: "sub", color: "#f472b6", label: ["MACD 12/26/9", "MACD 12/26/9", "MACD 12/26/9"] },
  { key: "stoch", pane: "sub", n: 14, color: "#a3e635", label: ["Стохастик 14/3", "Stoxastik 14/3", "Stochastic 14/3"] },
];

// The fundamentals the fact store actually holds, in statement order. The
// reference offers twenty-five lines because it buys an estimates feed; these
// twenty are the ones /api/company/{t}/financials can answer from filings.
const AC_FIN_FIELDS = [
  "net_revenue", "gross_profit", "operating_expenses", "operating_income", "net_profit",
  "total_assets", "total_liabilities", "total_equity", "cash",
  "roe", "roa", "return_to_capital_employed",
  "net_margin", "gross_profit_margin", "ebit_margin",
  "current_ratio", "quick_ratio", "debt_ratio", "debt_to_equity", "total_asset_turnover",
];
const AC_FIN_MAX = 2;
const AC_FIN_COLORS = ["#38bdf8", "#fb923c"];

/** A percentage-style fundamental is drawn and labelled as one. */
const acFinIsRate = (field) => /(_margin|^roe$|^roa$|_ratio$|return_to_capital|_turnover$)/.test(field);

/**
 * An annual figure placed on a daily axis.
 *
 * The value of period Y is attached to 31 December Y and carried forward from
 * there — never backwards over the year it describes. A reader looking at
 * March 2025 must not see the 2025 result: it did not exist yet, and drawing
 * it there is the one mistake that turns a fundamentals overlay into
 * hindsight dressed as information.
 */
function acFinancialAtDates(values, dates) {
  const years = Object.keys(values || {})
    .filter((y) => Number.isFinite(Number(values[y])))
    .sort();
  if (!years.length) return dates.map(() => null);
  let j = 0, held = null;
  return dates.map((d) => {
    const iso = String(d);
    while (j < years.length && `${years[j]}-12-31` <= iso) { held = Number(values[years[j]]); j += 1; }
    return held;
  });
}

/**
 * «Сравнить с» — the reference's compare strip, a row of peer cards under the
 * toolbar. A click puts that security's line on the chart.
 *
 * A strip rather than the dropdown this replaced: a menu makes the reader
 * remember which peers exist and what they did today, and then choose blind.
 * The card carries the price and the day's move, so the choice is informed
 * before it is made — which is the whole reason the reference spends a row of
 * the page on it.
 *
 * The card shows the TICKER, not the company name the reference shows. Their
 * names are «Microsoft C…»; ours truncate to «"O'zbekneftgaz…» and
 * «"Kafolat sug'urt…», which name nothing — and the ticker is what the chart's
 * own legend and tooltip use, so the card and the line it draws agree.
 */
function AdvancedCompareBar({ peers, allRows, securitiesMap, selected, colors, onToggle, lang, max }) {
  const t = (ru, uz, en) => (lang === "uz" ? uz : lang === "en" ? en : ru);
  const [q, setQ] = React.useState("");
  const [searching, setSearching] = React.useState(false);
  const scroller = React.useRef(null);
  const [arrows, setArrows] = React.useState({ left: false, right: false });
  const sync = React.useCallback(() => {
    const el = scroller.current;
    if (!el) return;
    setArrows({ left: el.scrollLeft > 4, right: el.scrollLeft + el.clientWidth < el.scrollWidth - 4 });
  }, []);
  const needle = q.trim().toUpperCase();
  const matches = (r) => String(r.ticker || "").toUpperCase().includes(needle)
    || String(r.name || "").toUpperCase().includes(needle);
  const found = needle
    ? (allRows || []).filter((r) => Number.isFinite(r.lastPrice) && r.lastPrice > 0 && matches(r)).slice(0, 40)
    : peers;
  // Whatever is ON the chart stays at the head of the strip, even when a search
  // excludes it: otherwise taking a line off means first searching for it again.
  const chosen = (allRows || []).filter((r) => selected.includes(String(r.ticker || "").toUpperCase()));
  const list = [...chosen, ...found.filter((r) => !selected.includes(String(r.ticker || "").toUpperCase()))];
  React.useEffect(() => {
    sync();
    if (typeof window === "undefined") return undefined;
    window.addEventListener("resize", sync);
    return () => window.removeEventListener("resize", sync);
  }, [sync, list.length]);
  const nudge = (dir) => {
    const el = scroller.current;
    if (el) el.scrollBy({ left: dir * Math.max(240, el.clientWidth * 0.8), behavior: "smooth" });
  };
  const full = selected.length >= max;

  return (
    <div className="ac-compare">
      <button type="button" className={`ac-compare-btn ${searching ? "on" : ""}`}
        onClick={() => { setSearching((v) => !v); if (searching) setQ(""); }}>
        <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor"
          strokeWidth="2" strokeLinecap="round"><circle cx="11" cy="11" r="7" /><path d="M20 20l-3.5-3.5" /></svg>
        {t("Сравнить с", "Taqqoslash", "Compare to")}
      </button>
      {searching && (
        <input className="ac-compare-input" type="search" autoFocus value={q}
          onChange={(e) => setQ(e.target.value)}
          onKeyDown={(e) => { if (e.key === "Escape") { setQ(""); setSearching(false); } }}
          placeholder={t("Тикер или название", "Tiker yoki nom", "Ticker or name")} />
      )}
      <div className="ac-compare-scroll">
        {arrows.left && (
          <button type="button" className="ac-compare-arrow left" onClick={() => nudge(-1)}
            aria-label={t("Назад", "Orqaga", "Back")}>‹</button>
        )}
        <div className="ac-compare-cards" ref={scroller} onScroll={sync}>
          {/* «Ничего не найдено» only answers a SEARCH. Before the board has
              loaded the strip is empty for a different reason, and saying the
              market holds nothing would be a false answer to a question the
              reader never asked. */}
          {list.length === 0 && (needle
            ? <span className="muted ac-compare-empty">{t("Ничего не найдено", "Hech narsa topilmadi", "Nothing found")}</span>
            : <span className="muted ac-compare-empty">{t("Загрузка списка…", "Ro'yxat yuklanmoqda…", "Loading the list…")}</span>
          )}
          {list.map((r) => {
            const tk = String(r.ticker || "").toUpperCase();
            const on = selected.includes(tk);
            const color = on ? colors[selected.indexOf(tk) % colors.length] : null;
            const tone = r.changePercent > 0 ? "pos" : r.changePercent < 0 ? "neg" : "";
            return (
              <button key={tk} type="button" className={`ac-cmp-card ${on ? "on" : ""}`}
                style={color ? { "--ac-color": color } : undefined}
                disabled={!on && full}
                aria-pressed={on}
                title={!on && full
                  ? t(`Не больше ${max} — уберите одну бумагу`, `${max} tadan ko'p emas`, `Up to ${max} — remove one first`)
                  : `${r.name || tk} — ${on ? t("убрать с графика", "grafikdan olib tashlash", "remove from the chart")
                                             : t("добавить на график", "grafikka qo'shish", "add to the chart")}`}
                onClick={() => onToggle(tk)}>
                <CompanyLogo logo={(securitiesMap || {})[tk]?.logo_url} name={r.name || tk} ticker={tk} />
                <span className="ac-cmp-tk">{tk}</span>
                <span className="ac-cmp-price">{formatMarketNumber(r.lastPrice, lang)}</span>
                <span className={`ac-cmp-chg ${tone}`}>
                  {Number.isFinite(r.changePercent)
                    ? `${signedFixed(r.changePercent)}%` : "—"}
                </span>
              </button>
            );
          })}
        </div>
        {arrows.right && (
          <button type="button" className="ac-compare-arrow right" onClick={() => nudge(1)}
            aria-label={t("Вперёд", "Oldinga", "Forward")}>›</button>
        )}
      </div>
    </div>
  );
}

/** The rail beside the advanced chart: search, favourites, peers. */
function AdvancedChartRail({ rows, securitiesMap, ticker, favorites, onToggleFavorite,
                             onOpen, lang, signedIn }) {
  const t = (ru, uz, en) => (lang === "uz" ? uz : lang === "en" ? en : ru);
  const [q, setQ] = React.useState("");
  const up = String(ticker || "").toUpperCase();
  const favSet = favorites || new Set();
  const priced = (rows || []).filter((r) => Number.isFinite(r.lastPrice) && r.lastPrice > 0);
  const needle = q.trim().toUpperCase();

  const list = needle
    ? priced.filter((r) => String(r.ticker || "").toUpperCase().includes(needle)
        || String(r.name || "").toUpperCase().includes(needle)).slice(0, 40)
    : null;

  const row = (r) => {
    const tk = String(r.ticker || "").toUpperCase();
    const isFav = favSet.has(tk);
    const tone = r.changePercent > 0 ? "pos" : r.changePercent < 0 ? "neg" : "";
    return (
      <div className={`ac-rail-row ${tk === up ? "is-current" : ""}`} key={tk}>
        <button type="button" className="ac-rail-name" onClick={() => onOpen && onOpen(tk)}>
          <span className="ac-rail-tk">{tk}</span>
          <span className="ac-rail-sub">{r.name || sectorLabel(lang, sectorOf(tk, securitiesMap, null))}</span>
        </button>
        <span className="ac-rail-figures">
          <span className="ac-rail-price">{formatMarketNumber(r.lastPrice, lang)}</span>
          <span className={`ac-rail-chg ${tone}`}>
            {Number.isFinite(r.changePercent)
              ? `${signedFixed(r.changePercent)}%` : "—"}
          </span>
        </span>
        <button type="button" className={`rail-fav ${isFav ? "on" : ""}`}
          onClick={() => onToggleFavorite && onToggleFavorite(tk, r.name)}>{isFav ? "★" : "☆"}</button>
      </div>
    );
  };

  const favRows = priced.filter((r) => favSet.has(String(r.ticker || "").toUpperCase()));
  const mine = sectorOf(up, securitiesMap, null);
  const sector = (!mine || mine === "other") ? [] : priced
    .filter((r) => String(r.ticker || "").toUpperCase() !== up
      && sectorOf(r.ticker, securitiesMap, null) === mine)
    .sort((a, b) => (b.marketCap || 0) - (a.marketCap || 0)).slice(0, 12);

  return (
    <div className="ac-rail">
      <input className="ac-rail-search" type="search" value={q} onChange={(e) => setQ(e.target.value)}
        placeholder={t("Поиск бумаги", "Qog'oz qidirish", "Search securities")} />
      {list ? (
        <div className="ac-rail-block">
          <h4 className="ac-rail-head">{t("Найдено", "Topildi", "Found")}</h4>
          {list.length ? <div>{list.map(row)}</div>
            : <p className="muted ac-rail-empty">{t("Ничего не найдено", "Hech narsa topilmadi", "Nothing found")}</p>}
        </div>
      ) : (
        <>
          <div className="ac-rail-block">
            <h4 className="ac-rail-head">{t("Избранное", "Tanlanganlar", "Watchlist")}</h4>
            {favRows.length ? <div>{favRows.map(row)}</div>
              : <p className="muted ac-rail-empty">
                  {signedIn ? t("Пока пусто", "Hozircha bo'sh", "Empty")
                            : t("Войдите, чтобы вести список", "Ro'yxat uchun kiring", "Sign in to keep a list")}
                </p>}
          </div>
          {sector.length > 0 && (
            <div className="ac-rail-block">
              <h4 className="ac-rail-head">{t("Тот же сектор", "Xuddi shu soha", "Same sector")}</h4>
              <div>{sector.map(row)}</div>
            </div>
          )}
        </>
      )}
    </div>
  );
}

function TechnicalBacktestCard({ ticker, lang, apiFetch, signedIn, hasProAccess, onUpgrade }) {
  const t = (ru, uz, en) => (lang === "uz" ? uz : lang === "en" ? en : ru);
  const [data, setData] = React.useState(null);
  const [loading, setLoading] = React.useState(false);
  const [error, setError] = React.useState("");
  const run = async () => {
    setLoading(true); setError("");
    try {
      const response = await apiFetch(`/api/company/${encodeURIComponent(ticker)}/technical-backtest`);
      const body = await response.json().catch(() => null);
      if (!response.ok || !body?.ok) throw new Error(body?.detail?.message || body?.detail || "Backtest unavailable");
      setData(body);
    } catch (err) { setError(String(err?.message || err)); } finally { setLoading(false); }
  };
  const metric = data?.metrics || {};
  return <article className="panel pad" style={{ marginTop: 16 }}>
    <div className="section-title" style={{ marginTop: 0 }}><h2>{t("Бэктест торгового правила", "Savdo qoidasi backtesti", "Trading-rule backtest")}</h2>{data?.model_version && <span className="muted">{data.model_version}</span>}</div>
    {!hasProAccess ? <div className="callout amber"><span className="ico">🔒</span><div><strong>{t("PRO-функция", "PRO funksiya", "PRO feature")}</strong><br />{t("Бэктест использует только подтверждённые сессии, следующую сессию для исполнения, комиссию и проскальзывание.", "Backtest faqat tasdiqlangan sessiyalar, ijro uchun keyingi sessiya, komissiya va sirpanishni ishlatadi.", "The backtest uses confirmed sessions only, next-session execution, fees and slippage.")}</div><button className="primary-btn" type="button" onClick={onUpgrade}>{signedIn ? "PRO" : t("Войти", "Kirish", "Sign in")}</button></div> : <>
      {!data && <button className="primary-btn" type="button" disabled={loading} onClick={run}>{loading ? t("Расчёт…", "Hisoblanmoqda…", "Running…") : t("Запустить SMA(20)", "SMA(20)ni ishga tushirish", "Run SMA(20)")}</button>}
      {error && <p className="neg">{error}</p>}
      {data?.status === "NO_DATA" && <p className="muted">{data.reason}</p>}
      {data?.status === "AVAILABLE" && <><div className="grid3" style={{ marginTop: 14 }}><div className="kpi"><div className="label">{t("Доходность", "Daromadlilik", "Return")}</div><div className="value">{formatSignedPercent(metric.total_return_pct, 2)}</div></div><div className="kpi"><div className="label">Max drawdown</div><div className="value">{formatRatio(metric.max_drawdown_pct, 2, lang)}%</div></div><div className="kpi"><div className="label">Sharpe</div><div className="value">{formatRatio(metric.sharpe, 2, lang)}</div></div></div><p className="muted" style={{ marginTop: 12 }}>{data.rule} · {data.period?.from} — {data.period?.to} · {data.period?.observations} {t("сессий", "sessiya", "sessions")}. {data.disclaimer}</p></>}
    </>}
  </article>;
}

function AdvancedChart({ ticker, securitiesMap, marketRows, tradeStats, lang, favorites,
                         onToggleFavorite, signedIn, hasProAccess = false, apiFetch = fetch,
                         onUpgrade, onBack, onOpenCompany, onOpenChart, initial }) {
  const t = (ru, uz, en) => (lang === "uz" ? uz : lang === "en" ? en : ru);
  const up = String(ticker || "").toUpperCase();

  // ── State the URL carries, so an advanced chart can be linked to ──────────
  const [range, setRange] = React.useState(initial?.range || "1y");
  const [span, setSpan] = React.useState({ from: initial?.from || "", to: initial?.to || "" });
  const [type, setType] = React.useState(initial?.type || "line");
  const [indicators, setIndicators] = React.useState(() => new Set(initial?.indicators || []));
  const [finFields, setFinFields] = React.useState(initial?.fin || []);
  const [compareTickers, setCompareTickers] = React.useState(initial?.compare || []);
  const [menu, setMenu] = React.useState(null);            // "ind" | "fin" | "cmp" | null
  const [cursorOn, setCursorOn] = React.useState(true);
  const [drawMode, setDrawMode] = React.useState(false);
  const [drawPoints, setDrawPoints] = React.useState([]);
  const [isFullscreen, setIsFullscreen] = React.useState(false);
  const chartShellRef = React.useRef(null);
  const [railOpen, setRailOpen] = React.useState(() => (typeof window === "undefined"
    ? true
    : !window.matchMedia("(max-width: 900px)").matches));

  React.useEffect(() => {
    if (!menu || typeof document === "undefined") return undefined;
    const closeMenu = (event) => {
      if (event.key === "Escape") setMenu(null);
    };
    document.addEventListener("keydown", closeMenu);
    return () => document.removeEventListener("keydown", closeMenu);
  }, [menu]);

  // Full-screen here means the chart workspace fills the browser viewport,
  // while keeping every period, indicator and comparison control reachable.
  // Lock the page underneath it and make Escape behave like a native dialog.
  React.useEffect(() => {
    if (typeof document === "undefined") return undefined;
    const onFullscreenChange = () => setIsFullscreen(document.fullscreenElement === chartShellRef.current);
    document.addEventListener("fullscreenchange", onFullscreenChange);
    return () => document.removeEventListener("fullscreenchange", onFullscreenChange);
  }, []);

  React.useEffect(() => {
    if (!isFullscreen || typeof document === "undefined") return undefined;
    const previousOverflow = document.body.style.overflow;
    const onKeyDown = (event) => {
      if (event.key === "Escape") setIsFullscreen(false);
    };
    document.body.style.overflow = "hidden";
    document.body.classList.add("advanced-chart-fullscreen");
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.body.style.overflow = previousOverflow;
      document.body.classList.remove("advanced-chart-fullscreen");
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [isFullscreen]);

  const toggleFullscreen = async () => {
    const node = chartShellRef.current;
    if (!node || typeof document === "undefined") return;
    try {
      if (document.fullscreenElement === node) await document.exitFullscreen();
      else if (node.requestFullscreen) await node.requestFullscreen();
      else setIsFullscreen((value) => !value);
    } catch {
      setIsFullscreen((value) => !value);
    }
  };

  const [history, setHistory] = React.useState(null);
  const [adjustments, setAdjustments] = React.useState([]);
  const [loading, setLoading] = React.useState(true);
  const [failed, setFailed] = React.useState(false);
  const [retry, setRetry] = React.useState(0);
  const [quality, setQuality] = React.useState(null);
  const [sec, setSec] = React.useState((securitiesMap || {})[up] || {});
  const [fin, setFin] = React.useState(null);
  const [cmpSeries, setCmpSeries] = React.useState({});
  const [cmpLoading, setCmpLoading] = React.useState(false);
  const [candleView, setCandleView] = React.useState(null);
  const [candleDragging, setCandleDragging] = React.useState(false);
  const candleDrag = React.useRef(null);
  const candleWheelHandler = React.useRef(null);

  const custom = Boolean(span.from && span.to);
  // How much history to ask for. A custom span asks back to its own start; the
  // buttons ask for what they show. Either way the fetch is a MONTH count,
  // which is the only unit /api/price-history understands. Every chart type
  // keeps the archive behind the selected window so dragging can browse older
  // sessions instead of stopping at an artificial fetch edge.
  const months = React.useMemo(() => {
    if (!custom) return 360;
    if (!custom) return chartRangeMonths(range);
    const d = new Date(span.from);
    const now = new Date();
    if (Number.isNaN(d.getTime())) return chartRangeMonths(range);
    return Math.max(1, Math.min(360,
      (now.getFullYear() - d.getFullYear()) * 12 + (now.getMonth() - d.getMonth()) + 2));
  }, [custom, span.from, range, type]);

  React.useEffect(() => {
    if (!up) return undefined;
    let alive = true;
    setLoading(true);
    setFailed(false);
    fetch(`/api/price-history/${encodeURIComponent(up)}?months=${months}`)
      .then((r) => r.json())
      .then((d) => {
        if (!alive) return;
        if (d.ok) { setHistory(d.points || []); setAdjustments(d.adjustments || []); }
        else setFailed(true);
      })
      .catch(() => { if (alive) setFailed(true); })
      .finally(() => { if (alive) setLoading(false); });
    return () => { alive = false; };
  }, [up, months, retry]);

  // Only `quality` is read here: whether this security trades often enough for
  // a candle to describe a day rather than invent one (ТЗ §6). The rest of the
  // metrics envelope belongs to the company page.
  React.useEffect(() => {
    if (!up) return undefined;
    let alive = true;
    fetch(`/api/company/${encodeURIComponent(up)}/metrics?months=${months}`)
      .then((r) => r.json())
      .then((d) => { if (alive) setQuality(d.ok ? d.quality : null); })
      .catch(() => { if (alive) setQuality(null); });
    return () => { alive = false; };
  }, [up, months]);

  React.useEffect(() => {
    if (!up) return undefined;
    let alive = true;
    fetch(`/api/securities/${encodeURIComponent(up)}/info?language=${lang}`)
      .then((r) => r.json())
      .then((d) => { if (alive && d.ok) setSec({ ...(d.security || {}) }); })
      .catch(() => {});
    return () => { alive = false; };
  }, [up, lang]);

  // The fact store, fetched once a fundamental is actually asked for — most
  // visits never open that menu.
  React.useEffect(() => {
    if (!up || !finFields.length || fin !== null) return undefined;
    let alive = true;
    fetch(`/api/company/${encodeURIComponent(up)}/financials`)
      .then((r) => r.json())
      .then((d) => { if (alive) setFin(d.ok ? d : { periods: [], series: {} }); })
      .catch(() => { if (alive) setFin({ periods: [], series: {} }); });
    return () => { alive = false; };
  }, [up, finFields.length, fin]);
  React.useEffect(() => { setFin(null); }, [up]);

  const cmpKey = [...compareTickers].sort().join(",");
  React.useEffect(() => {
    if (!cmpKey) { setCmpLoading(false); return undefined; }
    let alive = true;
    setCmpLoading(true);
    fetch(`/api/quotes/series?tickers=${encodeURIComponent(cmpKey)}&days=3650`)
      .then((r) => r.json())
      .then((d) => { if (alive && d && d.ok) setCmpSeries((s) => ({ ...s, ...(d.series || {}) })); })
      .catch(() => {})
      .finally(() => { if (alive) setCmpLoading(false); });
    return () => { alive = false; };
  }, [cmpKey]);

  // ── The URL mirrors the toolbar, so this view can be sent to somebody ─────
  React.useEffect(() => {
    if (typeof window === "undefined") return;
    const p = new URLSearchParams();
    if (custom) { p.set("from", span.from); p.set("to", span.to); } else if (range !== "1y") p.set("range", range);
    if (type !== "line") p.set("type", type);
    if (indicators.size) p.set("ind", [...indicators].join(","));
    if (finFields.length) p.set("fin", finFields.join(","));
    if (compareTickers.length) p.set("cmp", compareTickers.join(","));
    const q = p.toString();
    window.history.replaceState(null, "", `/chart/${encodeURIComponent(up)}${q ? `?${q}` : ""}`);
  }, [up, range, span, type, indicators, finFields, compareTickers, custom]);

  // ── Data preparation ─────────────────────────────────────────────────────
  const daily = React.useMemo(() => (history || []).map((h) => (Array.isArray(h)
    ? { date: h[0], close: Number(h[1]) || 0, volume: 0, turnover: Number(h[2]) || 0 }
    : {
        date: h.date || h.trade_date,
        open: h.open != null ? Number(h.open) : null,
        high: h.high != null ? Number(h.high) : null,
        low: h.low != null ? Number(h.low) : null,
        close: Number(h.close ?? h.price ?? h.close_price ?? 0),
        volume: Number(h.volume ?? h.trading_volume ?? 0) || 0,
        // Money, not a security count — see the note on the company chart's
        // normalizer. The pane, its scale label and the readout all use it.
        turnover: Number(h.value ?? h.trading_value ?? 0) || 0,
        change: h.change != null ? Number(h.change) : null,
      }))
    .filter((p) => p.close > 0 && p.date)
    .sort((a, b) => String(a.date).localeCompare(String(b.date))), [history]);

  const windowed = React.useMemo(() => {
    if (custom) return daily.filter((p) => String(p.date) >= span.from && String(p.date) <= span.to);
    let cutoff = chartRangeCutoff(range, daily.at(-1)?.date);
    // Normally the API request itself enforces month-based presets. Candle
    // mode deliberately fetches farther back for panning, so reproduce that
    // preset boundary here before opening the interactive viewport.
    if (!cutoff && range !== "max") {
      const spanMonths = chartRangeSpan(range);
      if (spanMonths) {
        const d = new Date(daily.at(-1)?.date || Date.now());
        d.setUTCMonth(d.getUTCMonth() - spanMonths);
        cutoff = d.toISOString().slice(0, 10);
      }
    }
    return cutoff ? daily.filter((p) => String(p.date) >= cutoff) : daily;
  }, [daily, custom, span.from, span.to, range, type]);

  // A preset defines the view we open with, not a wall around the data.
  // The full fetched archive stays behind it so a zoomed view can be dragged
  // into earlier history. A custom range remains a hard boundary because the
  // dates were an explicit request rather than a convenient zoom preset.
  const candleSource = custom ? windowed : daily;
  const defaultCandleView = React.useMemo(() => {
    if (!candleSource.length) return { start: 0, end: 0 };
    if (custom || !windowed.length) return { start: 0, end: candleSource.length };
    const first = String(windowed[0].date);
    const found = candleSource.findIndex((p) => String(p.date) >= first);
    return { start: found < 0 ? 0 : found, end: candleSource.length };
  }, [candleSource, custom, windowed]);
  const resolvedCandleView = acClampView(candleView, defaultCandleView, candleSource.length);
  const candlesAllowed = quality ? quality.candles_enabled !== false : true;
  const chartNavigation = !custom && compareTickers.length === 0
    && (type !== "candle" || candlesAllowed);
  const visibleWindow = chartNavigation
    ? candleSource.slice(resolvedCandleView.start, resolvedCandleView.end)
    : windowed;

  React.useEffect(() => {
    setCandleView(null);
    candleDrag.current = null;
    setCandleDragging(false);
    setDrawPoints([]);
  }, [up, range, span.from, span.to, type]);

  // Indicators run on the WHOLE fetched series, not on the visible window: a
  // 200-day average at the left edge of a one-month view is a real average of
  // the two hundred days before it, not a truncated one.
  const cal = React.useMemo(() => indCalendar(daily), [daily]);

  const cmpLines = React.useMemo(() => compareTickers.map((tk, i) => ({
    ticker: tk,
    color: QC_COLORS[i % QC_COLORS.length],
    points: cmpSeries[tk] || null,
  })), [compareTickers, cmpSeries]);
  const cmp = React.useMemo(() => buildCompareSeries(visibleWindow, cmpLines), [visibleWindow, cmpLines]);
  const cmpOn = Boolean(cmp && cmp.series.length);

  const points = cmpOn ? cmp.points : visibleWindow;
  const dates = React.useMemo(() => points.map((p) => String(p.date)), [points]);

  // A comparison is a percent question, so the price pane answers in percent —
  // and a candle has no meaning on a rebased axis. The type control says so
  // rather than silently drawing something else.
  const effType = cmpOn && !AC_COMPARISON_TYPES.has(type) ? "line" : type;
  // ТЗ §6: candles are only drawn where a day HAS a body worth drawing.
  const stepLine = quality ? quality.candles_enabled === false : false;
  const drawType = (AC_OHLC_TYPES.has(effType) && !candlesAllowed) ? "line" : effType;

  const ind = React.useMemo(() => {
    if (!cal.days.length) return {};
    const out = {};
    const put = (key, daily2) => { out[key] = indAlign(daily2, cal.indexByDate, dates); };
    if (indicators.has("sma50")) put("sma50", indSma(cal.close, 50));
    if (indicators.has("sma200")) put("sma200", indSma(cal.close, 200));
    if (indicators.has("ema50")) put("ema50", indEma(cal.close, 50));
    if (indicators.has("ema200")) put("ema200", indEma(cal.close, 200));
    if (indicators.has("bb")) {
      const b = indBollinger(cal.close, 20, 2);
      out.bb = {
        mid: indAlign(b.mid, cal.indexByDate, dates),
        upper: indAlign(b.upper, cal.indexByDate, dates),
        lower: indAlign(b.lower, cal.indexByDate, dates),
      };
    }
    if (indicators.has("rsi")) put("rsi", indRsi(cal.close, 14));
    if (indicators.has("macd")) {
      const m = indMacd(cal.close, 12, 26, 9);
      out.macd = {
        line: indAlign(m.line, cal.indexByDate, dates),
        signal: indAlign(m.signal, cal.indexByDate, dates),
        hist: indAlign(m.hist, cal.indexByDate, dates),
      };
    }
    if (indicators.has("stoch")) {
      const s = indStochastic(cal.high, cal.low, cal.close, 14, 3);
      out.stoch = {
        k: indAlign(s.k, cal.indexByDate, dates),
        d: indAlign(s.d, cal.indexByDate, dates),
      };
    }
    return out;
  }, [cal, indicators, dates]);

  const finPanes = React.useMemo(() => finFields.map((field, i) => {
    const series = fin?.series?.[field];
    return {
      field,
      color: AC_FIN_COLORS[i % AC_FIN_COLORS.length],
      unit: series?.unit || (acFinIsRate(field) ? "%" : null),
      values: series ? acFinancialAtDates(series.values || {}, dates) : dates.map(() => null),
      empty: !series,
    };
  }), [finFields, fin, dates]);

  // ── Geometry ─────────────────────────────────────────────────────────────
  const [box, setBox] = React.useState({ w: 0, h: 0, view: 0 });
  const boxNode = React.useRef(null);
  const roRef = React.useRef(null);
  const measure = React.useCallback(() => {
    const n = boxNode.current;
    if (!n || typeof window === "undefined") return;
    const r = n.getBoundingClientRect();
    setBox({ w: Math.round(r.width), h: Math.round(r.height), view: window.innerHeight });
  }, []);
  const attach = React.useCallback((node) => {
    if (roRef.current) { roRef.current.disconnect(); roRef.current = null; }
    boxNode.current = node;
    if (!node) return;
    measure();
    if (typeof ResizeObserver !== "undefined") {
      roRef.current = new ResizeObserver(measure);
      roRef.current.observe(node);
    }
  }, [measure]);

  const [hover, setHover] = React.useState(null);
  const [pointer, setPointer] = React.useState({ x: 0, y: 0 });

  const toggleIndicator = (key) => setIndicators((cur) => {
    const next = new Set(cur);
    if (next.has(key)) next.delete(key); else next.add(key);
    return next;
  });
  const toggleFin = (field) => setFinFields((cur) => (cur.includes(field)
    ? cur.filter((f) => f !== field)
    : cur.length >= AC_FIN_MAX ? cur : [...cur, field]));
  const toggleCompare = (tk) => {
    const k = String(tk || "").toUpperCase();
    setCompareTickers((cur) => (cur.includes(k) ? cur.filter((x) => x !== k)
      : cur.length >= QC_MAX ? cur : [...cur, k]));
  };

  /**
   * Open another security's chart from the rail.
   *
   * The VIEW carries over — period, chart type, indicators, the fundamentals
   * on show are all questions about how to look, and a reader who set them up
   * wants to keep looking that way. The COMPARISON does not: a peer set is
   * chosen against one security, so carrying it over compares the new security
   * against the old one's neighbours — and opening a security that was itself
   * on the chart would compare it with itself, a flat line at 0 %.
   */
  const openPeerChart = (tk) => {
    if (!onOpenChart) return;
    onOpenChart(tk, {
      range,
      from: span.from,
      to: span.to,
      type,
      indicators: [...indicators],
      fin: finFields,
      compare: [],
    });
  };

  const preparedRows = React.useMemo(() => {
    const day = latestTradeStatsDay(tradeStats || {});
    return (marketRows || []).map(enrichMarketStock).map((r) => applyTradeStats(r, tradeStats || {}, day));
  }, [marketRows, tradeStats]);
  const marketRow = preparedRows.find((r) => String(r.ticker || "").toUpperCase() === up) || null;
  const peers = React.useMemo(
    () => quickComparePeers({ ticker: up, rows: preparedRows, securitiesMap, limit: 24 }),
    [up, preparedRows, securitiesMap],
  );

  const dateLocale = lang === "en" ? "en-US" : "ru-RU";
  const fmtDate = (d, withYear) => (d
    ? new Date(d).toLocaleDateString(dateLocale, withYear
        ? { year: "2-digit", month: "short", day: "numeric" }
        : { month: "short", day: "numeric" })
    : "");
  const fmtFull = (v) => (v == null || !Number.isFinite(v) ? "—"
    : Number(v).toLocaleString(dateLocale, { maximumFractionDigits: 2 }));
  const fmtPctVal = (v) => (v == null || !Number.isFinite(v) ? "—" : `${signedFixed(v, 1)}%`);
  const abbrev = (v) => (v == null ? "—" : Math.abs(v) >= 1e9 ? `${(v / 1e9).toFixed(2)}B`
    : Math.abs(v) >= 1e6 ? `${(v / 1e6).toFixed(2)}M`
    : Math.abs(v) >= 1e3 ? `${(v / 1e3).toFixed(1)}K` : `${v.toFixed(0)}`);

  const lastPrice = marketRow?.lastPrice ?? sec.last_price ?? (points.length ? points[points.length - 1].close : null);
  const dayChange = marketRow && Number.isFinite(marketRow.changePercent)
    ? { v: marketRow.changeValue, p: marketRow.changePercent } : null;
  // What the VIEW did, which is not what the day did — the reference states
  // both, and on a range button they are different questions.
  const windowChange = points.length >= 2 && points[0].close > 0
    ? ((points[points.length - 1].close / points[0].close) - 1) * 100 : null;

  const rangeBar = (
    <div className="ac-ranges">
      {/* No 1Д here: the advanced chart draws the daily archive and computes
          calendar-windowed indicators on it — a one-session window would be a
          button that answers nothing. The hourly view lives on the company page. */}
      {CHART_RANGES.filter((r) => r.key !== "1d").map((r) => (
        <button key={r.key} type="button"
          className={`ac-range-btn ${!custom && range === r.key ? "active" : ""}`}
          onClick={() => { setSpan({ from: "", to: "" }); setRange(r.key); }}>
          {r.label[lang === "uz" ? 1 : lang === "en" ? 2 : 0]}
        </button>
      ))}
      <button type="button" className={`ac-range-btn ac-range-custom ${custom ? "active" : ""}`}
        onClick={() => setMenu(menu === "span" ? null : "span")}
        title={t("Свой период", "O'z davri", "Custom range")}>
        {custom ? `${fmtDate(span.from, true)} — ${fmtDate(span.to, true)}` : t("Период…", "Davr…", "Range…")}
      </button>
    </div>
  );

  const menuPanel = (key, children) => (menu === key
    ? <div className="ac-menu" onMouseLeave={() => setMenu(null)}>{children}</div> : null);

  // ── Drawing ──────────────────────────────────────────────────────────────
  const GAP = 12;
  // Volume needs enough of its own pane to be readable. UZSE sessions often
  // contain one block trade that is orders of magnitude larger than normal
  // turnover, so using the absolute maximum would flatten every other bar.
  const VOL_H = 160;
  const SUB_H = 92;
  const subPanes = [
    ...(indicators.has("rsi") ? [{ key: "rsi" }] : []),
    ...(indicators.has("macd") ? [{ key: "macd" }] : []),
    ...(indicators.has("stoch") ? [{ key: "stoch" }] : []),
    ...finPanes.map((f) => ({ key: `fin:${f.field}`, fin: f })),
  ];
  // The panel GROWS with what is on it. A fixed height would take an
  // oscillator's ninety pixels out of the price pane, which is the one pane
  // that was the reason to open this page.
  const plotH = Math.max(420, Math.round((box.view || 900) * 0.62))
    + subPanes.length * (SUB_H + GAP);
  const W = Math.max(320, box.w || 900);
  const H = Math.max(320, box.h || plotH);
  // The legend floats over the top-left of the price pane; without the extra
  // gutter the first candles are drawn underneath it.
  const legendCount = compareTickers.length + indicators.size + finFields.length;
  const PAD = { top: legendCount ? 34 : 10, right: 66, bottom: 26, left: 10 };
  const innerW = W - PAD.left - PAD.right;
  const stackH = VOL_H + subPanes.length * (SUB_H + GAP);
  const priceTop = PAD.top;
  const priceBot = Math.max(priceTop + 80, H - PAD.bottom - stackH - GAP);
  const volTop = priceBot + GAP;
  const volBot = volTop + VOL_H;
  const subTop = (i) => volBot + GAP + i * (SUB_H + GAP);

  const n = points.length;
  const xs = (i) => PAD.left + (n > 1 ? (i / (n - 1)) * innerW : innerW / 2);
  const gapPx = n > 1 ? innerW / (n - 1) : innerW;

  const ohlcOk = (p) => p.open > 0 && p.high > 0 && p.low > 0 && p.close > 0
    && p.low <= Math.min(p.open, p.close) && Math.max(p.open, p.close) <= p.high;

  // What the price pane measures: сумы, or percent from the shared start when
  // a peer is on the chart.
  const baseVals = cmpOn ? cmp.basePct : points.map((p) => p.close);
  const toScale = (price) => (cmpOn ? (price / cmp.base0 - 1) * 100 : price);
  const heikinPoints = React.useMemo(() => acHeikinAshi(points), [points]);
  const candleDrawPoints = drawType === "heikin_ashi" ? heikinPoints : points;
  const drawCandles = ["candle", "heikin_ashi"].includes(drawType) && !cmpOn;
  const renko = React.useMemo(() => acRenko(points), [points]);
  const kagi = React.useMemo(() => acKagi(points), [points]);
  const pointFigure = React.useMemo(() => acPointFigure(points), [points]);

  const priceExtent = () => {
    const vals = [];
    points.forEach((p, i) => {
      const candlePoint = candleDrawPoints[i];
      if (drawCandles && ohlcOk(candlePoint)) { vals.push(toScale(candlePoint.high)); vals.push(toScale(candlePoint.low)); }
      else vals.push(baseVals[i]);
    });
    if (drawType === "renko") renko.bricks.forEach((brick) => vals.push(brick.from, brick.to));
    if (drawType === "kagi") kagi.turns.forEach((turn) => vals.push(turn.value));
    if (drawType === "point_figure") pointFigure.columns.forEach((column) => vals.push(column.from, column.to));
    if (cmpOn) cmp.series.forEach((s) => s.pct.forEach((v) => { if (v != null) vals.push(v); }));
    ["sma50", "sma200", "ema50", "ema200"].forEach((k) => {
      (ind[k] || []).forEach((v) => { if (v != null) vals.push(toScale(v)); });
    });
    if (ind.bb) {
      ind.bb.upper.forEach((v) => { if (v != null) vals.push(toScale(v)); });
      ind.bb.lower.forEach((v) => { if (v != null) vals.push(toScale(v)); });
    }
    const lo = Math.min(...vals), hi = Math.max(...vals);
    return Number.isFinite(lo) && Number.isFinite(hi) ? [lo, hi] : [0, 1];
  };
  const [minP, maxP] = n ? priceExtent() : [0, 1];
  const rangeP = maxP - minP || Math.abs(maxP) || 1;
  const ys = (v) => priceTop + (1 - (v - minP) / rangeP) * (priceBot - priceTop);

  const niceStep = (spanV, count) => {
    const raw = spanV / count;
    const mag = Math.pow(10, Math.floor(Math.log10(raw || 1)));
    const norm = (raw || 1) / mag;
    return (norm <= 1 ? 1 : norm <= 2 ? 2 : norm <= 2.5 ? 2.5 : norm <= 5 ? 5 : 10) * mag;
  };
  const yLabels = [];
  {
    const step = niceStep(rangeP, 5);
    // Same rule as the company chart: enough decimals that neighbouring
    // gridlines never print the same number (a 0.005 step at two decimals did).
    const dec = Math.max(2, Math.min(6, Math.ceil(-Math.log10(step))));
    const fmtY = (v) => (v == null || !Number.isFinite(v) ? "—"
      : Number(v).toLocaleString(dateLocale, { maximumFractionDigits: dec }));
    const fmtAxisVal = cmpOn ? fmtPctVal : fmtY;
    for (let v = Math.ceil(minP / step) * step; v <= maxP + step * 1e-9; v += step) {
      yLabels.push({ y: ys(v), label: fmtAxisVal(v) });
    }
  }

  const xLabels = [];
  {
    const withYear = (chartRangeSpan(range) || 12) >= 12 || custom;
    const spanMonths = chartRangeSpan(range) || 12;
    if (spanMonths <= 12) {
      let previousMonth = null;
      points.forEach((point, i) => {
        const month = String(point.date).slice(0, 7);
        if (month === previousMonth) return;
        previousMonth = month;
        xLabels.push({ x: xs(i), label: fmtDate(point.date, true) });
      });
    } else {
      const step = Math.max(1, Math.floor(n / Math.max(2, Math.floor(innerW / 110))));
      for (let i = 0; i < n; i += step) {
        xLabels.push({ x: xs(i), label: withYear ? fmtDate(points[i].date, true) : fmtDate(points[i].date) });
      }
    }
  }

  const linePath = (vals, toY) => {
    let d = "", started = false;
    vals.forEach((v, i) => {
      if (v == null || !Number.isFinite(v)) { started = false; return; }
      d += `${started ? "L" : "M"}${xs(i).toFixed(1)},${toY(v).toFixed(1)}`;
      started = true;
    });
    return d;
  };
  const stepPath = (vals, toY) => {
    let d = "", prev = null;
    vals.forEach((v, i) => {
      if (v == null || !Number.isFinite(v)) return;
      const x = xs(i).toFixed(1);
      if (prev == null) { d += `M${x},${toY(v).toFixed(1)}`; } else {
        d += ` L${x},${toY(prev).toFixed(1)} L${x},${toY(v).toFixed(1)}`;
      }
      prev = v;
    });
    return d;
  };

  const baseD = stepLine && !drawCandles ? stepPath(baseVals, ys) : linePath(baseVals, ys);
  const isUp = n >= 2 && baseVals[n - 1] >= baseVals[0];
  const priceColor = cmpOn ? "#2fc584" : isUp ? "#2fc584" : "#ee6a60";
  const baseLevel = n ? baseVals[0] : 0;

  const volumeValues = points.map((p) => p.turnover || 0).filter((v) => v > 0).sort((a, b) => a - b);
  const maxVol = Math.max(1, volumeValues.at(-1) || 0);
  const volumeScale = volumeValues.length
    ? Math.max(1, volumeValues[Math.min(volumeValues.length - 1, Math.floor((volumeValues.length - 1) * 0.95))])
    : 1;

  const onMove = (e) => {
    if (!cursorOn && !drawMode) return;
    const rect = e.currentTarget.getBoundingClientRect();
    if (!rect.width || n < 1) return;
    const x = ((e.clientX - rect.left) / rect.width) * W;
    let i = Math.round(((x - PAD.left) / innerW) * (n - 1));
    i = Math.max(0, Math.min(n - 1, i));
    setHover(i);
    setPointer({ x: e.clientX - rect.left, y: e.clientY - rect.top });
  };

  const onCandleWheel = (e) => {
    if (!chartNavigation || !e.ctrlKey || !candleSource.length || e.deltaY === 0) return;
    // Ctrl+wheel normally zooms the whole browser. Inside a candle chart the
    // modifier has a local, visible meaning, so keep the page itself steady.
    e.preventDefault();
    e.stopPropagation();
    const rect = e.currentTarget.getBoundingClientRect();
    const plotLeft = rect.left + (PAD.left / W) * rect.width;
    const plotWidth = (innerW / W) * rect.width;
    const anchorRatio = plotWidth > 0 ? (e.clientX - plotLeft) / plotWidth : 0.5;
    const next = acZoomView(resolvedCandleView, candleSource.length, anchorRatio, e.deltaY < 0);
    setCandleView(next);
    setHover(null);
  };
  candleWheelHandler.current = onCandleWheel;

  // React delegates wheel events with a passive root listener. The chart must
  // cancel the browser's Ctrl+wheel page zoom, so this one listener belongs on
  // the plot node itself and explicitly opts out of passive handling.
  React.useEffect(() => {
    const node = boxNode.current;
    if (!node) return undefined;
    const onWheel = (event) => candleWheelHandler.current?.(event);
    node.addEventListener("wheel", onWheel, { passive: false });
    return () => node.removeEventListener("wheel", onWheel);
  }, []);

  const onCandlePointerDown = (e) => {
    if (drawMode || !chartNavigation || (e.pointerType === "mouse" && e.button !== 0) || !candleSource.length) return;
    const size = resolvedCandleView.end - resolvedCandleView.start;
    if (size >= candleSource.length) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const plotWidth = (innerW / W) * rect.width;
    candleDrag.current = {
      pointerId: e.pointerId,
      startX: e.clientX,
      start: resolvedCandleView.start,
      size,
      pixelsPerPoint: plotWidth / Math.max(1, size - 1),
    };
    e.currentTarget.setPointerCapture?.(e.pointerId);
    e.preventDefault();
    setCandleDragging(true);
    setHover(null);
  };

  const onCandlePointerMove = (e) => {
    const drag = candleDrag.current;
    if (!drag || drag.pointerId !== e.pointerId) { onMove(e); return; }
    const delta = acNearestInt((e.clientX - drag.startX) / Math.max(0.5, drag.pixelsPerPoint));
    const start = Math.max(0, Math.min(candleSource.length - drag.size, drag.start - delta));
    setCandleView({ start, end: start + drag.size });
  };

  const endCandleDrag = (e) => {
    if (!candleDrag.current || candleDrag.current.pointerId !== e.pointerId) return;
    try { e.currentTarget.releasePointerCapture?.(e.pointerId); } catch { /* capture may already be gone */ }
    candleDrag.current = null;
    setCandleDragging(false);
  };

  const hp = hover != null && points[hover] ? points[hover] : null;
  const initialCandleView = acClampView(null, defaultCandleView, candleSource.length);
  const candleViewChanged = Boolean(candleView)
    && (resolvedCandleView.start !== initialCandleView.start
      || resolvedCandleView.end !== initialCandleView.end);
  const relVol = hp ? relativeVolume(daily, hp.date, hp.turnover) : null;
  const addTrendPoint = () => {
    if (!drawMode || hover == null) return;
    setDrawPoints((current) => current.length >= 2 ? [hover] : [...current, hover]);
  };

  const legendChips = [
    ...(cmpOn ? cmp.series.map((s) => ({ key: `c:${s.ticker}`, color: s.color, text: s.ticker, off: () => toggleCompare(s.ticker) })) : []),
    ...AC_INDICATORS.filter((d) => indicators.has(d.key)).map((d) => ({
      key: `i:${d.key}`, color: d.color, off: () => toggleIndicator(d.key),
      text: d.label[lang === "uz" ? 1 : lang === "en" ? 2 : 0],
    })),
    ...finPanes.map((f) => ({
      key: `f:${f.field}`, color: f.color, off: () => toggleFin(f.field),
      text: finLabel(f.field, lang),
    })),
  ];

  const emptyState = !loading && n < 2;

  return (
    <div ref={chartShellRef} className={`advanced-chart ${railOpen ? "rail-open" : ""} ${isFullscreen ? "is-fullscreen" : ""}`}>
      <div className="ac-head">
        <button className="ac-back" type="button" onClick={onBack}>
          ← {t("Назад", "Orqaga", "Back")}
        </button>
        <CompanyLogo logo={sec.company_logo_url || sec.logo_url || (securitiesMap || {})[up]?.logo_url}
          name={sec.company_name || sec.name || up} ticker={up} />
        <div className="ac-title">
          <h1>{sec.company_name || sec.name || up}</h1>
          <div className="ac-meta">
            <span className="ac-tk">{up}</span>
            {sec.isin && <span className="muted">{sec.isin}</span>}
            <span className="muted">{t("Расчётные цены закрытия · UZSE", "Hisob-kitob yopilish narxlari · UZSE", "Settled closing prices · UZSE")}</span>
          </div>
        </div>
        <div className="ac-quote">
          <span className="ac-price">{lastPrice != null ? formatMarketNumber(lastPrice, lang) : "—"}</span>
          {dayChange && (
            <span className={`ac-change ${dayChange.p >= 0 ? "pos" : "neg"}`}>
              {dayChange.v >= 0 ? "+" : ""}{fmtFull(dayChange.v)} ({signedFixed(dayChange.p)}%)
            </span>
          )}
          {windowChange != null && (
            <span className={`ac-window-change ${windowChange >= 0 ? "pos" : "neg"}`}>
              {t("за период", "davr uchun", "over the period")} {fmtPctVal(windowChange)}
            </span>
          )}
        </div>
        <button className="ac-open-company" type="button" onClick={() => onOpenCompany && onOpenCompany(up)}>
          {t("Страница компании →", "Kompaniya sahifasi →", "Company page →")}
        </button>
      </div>

      <div className="ac-toolbar">
        {rangeBar}
        <div className="cpc-tool-strip ac-company-tools" data-testid="advanced-chart-tool-strip">
          <button type="button" className="cpc-tool-btn" aria-label={t("Дневной интервал", "Kunlik interval", "Daily interval")} title={t("Дневной интервал", "Kunlik interval", "Daily interval")}>D</button>
          <button type="button" className={`cpc-tool-btn ${cursorOn ? "active" : ""}`}
            aria-pressed={cursorOn} aria-label={t("Перекрестие и подсказки", "Kursor va ko'rsatmalar", "Crosshair and tooltips")}
            onClick={() => { setCursorOn((value) => !value); setHover(null); }}>
            <CompanyChartToolIcon kind="pointer" />
          </button>
          <div className="cpc-tool-slot">
            <button type="button" className={`cpc-tool-btn ${menu === "type" ? "active" : ""}`}
              aria-haspopup="menu" aria-expanded={menu === "type"} aria-label={t("Вид графика", "Grafik turi", "Chart type")}
              onClick={() => setMenu(menu === "type" ? null : "type")}>
              <CompanyChartToolIcon kind="candle" />
            </button>
            {menuPanel("type", AC_TYPES.map((tp) => {
              const name = tp.label[lang === "uz" ? 1 : lang === "en" ? 2 : 0];
              return <button key={tp.key} type="button" className={`ac-menu-item ${effType === tp.key ? "on" : ""}`}
                disabled={(cmpOn && !AC_COMPARISON_TYPES.has(tp.key)) || (AC_OHLC_TYPES.has(tp.key) && !candlesAllowed)}
                onClick={() => { setType(tp.key); setMenu(null); }}>{name}</button>;
            }))}
          </div>
          <div className="cpc-tool-slot">
            <button type="button" className={`cpc-tool-btn ${compareTickers.length ? "has-value" : ""} ${menu === "cmp" ? "active" : ""}`}
              aria-haspopup="menu" aria-expanded={menu === "cmp"} aria-label={t("Сравнить", "Taqqoslash", "Compare")}
              onClick={() => setMenu(menu === "cmp" ? null : "cmp")}>
              <CompanyChartToolIcon kind="compare" />
            </button>
            {menuPanel("cmp", peers.slice(0, 30).map((peer) => {
              const tk = String(peer.ticker || "").toUpperCase();
              return <button key={tk} type="button" className={`ac-menu-item ${compareTickers.includes(tk) ? "on" : ""}`}
                disabled={!compareTickers.includes(tk) && compareTickers.length >= QC_MAX}
                onClick={() => toggleCompare(tk)}>{peer.name || tk} <b className="ac-menu-tk">{tk}</b></button>;
            }))}
          </div>
          <button type="button" className={`cpc-tool-btn ${drawMode || drawPoints.length ? "active" : ""}`}
            aria-pressed={drawMode} aria-label={t("Линия тренда", "Trend chizig'i", "Trend line")}
            onClick={() => { setMenu(null); setDrawMode((value) => !value); setHover(null); }}>
            <CompanyChartToolIcon kind="draw" />
          </button>
          <button type="button" className={`cpc-tool-btn ${indicators.size ? "has-value" : ""} ${menu === "ind" ? "active" : ""}`}
            aria-label={t("Индикаторы", "Indikatorlar", "Indicators")} onClick={() => setMenu(menu === "ind" ? null : "ind")}>
            <CompanyChartToolIcon kind="fx" />
          </button>
          <button type="button" className={`cpc-tool-btn ${finFields.length ? "has-value" : ""} ${menu === "fin" ? "active" : ""}`}
            aria-label={t("Настройки и финансовые слои", "Sozlamalar va moliyaviy qatlamlar", "Settings and financial overlays")}
            onClick={() => setMenu(menu === "fin" ? null : "fin")}>
            <CompanyChartToolIcon kind="settings" />
          </button>
        </div>
        <div className="ac-toolbar-group ac-types" role="group"
          aria-label={t("Вид графика", "Grafik turi", "Chart type")}>
          {AC_TYPES.filter((tp) => ["line", "candle", "area", "baseline"].includes(tp.key)).map((tp) => {
            const name = tp.label[lang === "uz" ? 1 : lang === "en" ? 2 : 0];
            // A disabled button still has to say WHY, and the reason differs:
            // one is a fact about the security, the other about the axis.
            const why = !AC_OHLC_TYPES.has(tp.key) ? null
              : !candlesAllowed
                ? t("Слишком мало сделок — день не имеет тела",
                    "Bitimlar juda kam — kunning tanasi yo'q",
                    "Too few trades — the day has no body")
                : cmpOn
                  ? t("В сравнении шкала процентная — у свечи нет тела",
                      "Taqqoslashda shkala foizli — shamning tanasi yo'q",
                      "The scale is percent while comparing — a candle has no body")
                  : null;
            return (
              <button key={tp.key} type="button"
                className={`ac-type-btn ${effType === tp.key ? "active" : ""}`}
                disabled={(cmpOn && !AC_COMPARISON_TYPES.has(tp.key)) || (AC_OHLC_TYPES.has(tp.key) && !candlesAllowed)}
                aria-pressed={effType === tp.key}
                aria-label={name}
                title={why ? `${name} — ${why}` : name}
                onClick={() => setType(tp.key)}>
                <svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor"
                  strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                  {AC_TYPE_ICONS[tp.key]}
                </svg>
              </button>
            );
          })}
        </div>
        <div className="ac-toolbar-group ac-menus">
          <div className="ac-menu-wrap">
            <button type="button" className={`ac-menu-btn ${indicators.size ? "on" : ""}`}
              onClick={() => setMenu(menu === "ind" ? null : "ind")}>
              {t("Индикаторы", "Indikatorlar", "Indicators")}{indicators.size ? ` · ${indicators.size}` : ""}
            </button>
            {menuPanel("ind", AC_INDICATORS.map((d) => (
              <button key={d.key} type="button"
                className={`ac-menu-item ${indicators.has(d.key) ? "on" : ""}`}
                onClick={() => toggleIndicator(d.key)}>
                <span className="ac-menu-dot" style={{ background: d.color }} />
                {d.label[lang === "uz" ? 1 : lang === "en" ? 2 : 0]}
              </button>
            )))}
          </div>
          <div className="ac-menu-wrap">
            <button type="button" className={`ac-menu-btn ${finFields.length ? "on" : ""}`}
              onClick={() => setMenu(menu === "fin" ? null : "fin")}>
              {t("Финансы", "Moliya", "Financials")}{finFields.length ? ` · ${finFields.length}` : ""}
            </button>
            {menuPanel("fin", (
              <div className="ac-menu-scroll">
                {AC_FIN_FIELDS.map((f) => (
                  <button key={f} type="button"
                    className={`ac-menu-item ${finFields.includes(f) ? "on" : ""}`}
                    disabled={!finFields.includes(f) && finFields.length >= AC_FIN_MAX}
                    onClick={() => toggleFin(f)}>
                    {finLabel(f, lang)}
                  </button>
                ))}
              </div>
            ))}
          </div>
        </div>
        <button type="button" className="ac-fullscreen-btn"
          aria-pressed={isFullscreen}
          aria-label={isFullscreen
            ? t("Выйти из полноэкранного режима", "To'liq ekrandan chiqish", "Exit full screen")
            : t("Развернуть график на весь экран", "Grafikni to'liq ekranga yoyish", "Expand chart to full screen")}
          title={isFullscreen
            ? t("Выйти из полноэкранного режима (Esc)", "To'liq ekrandan chiqish (Esc)", "Exit full screen (Esc)")
            : t("На весь экран", "To'liq ekran", "Full screen")}
          onClick={toggleFullscreen}>
          <svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor"
            strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
            {isFullscreen ? (
              <path d="M9 4v5H4 M15 4v5h5 M9 20v-5H4 M15 20v-5h5" />
            ) : (
              <path d="M8 3H3v5 M16 3h5v5 M8 21H3v-5 M21 16v5h-5" />
            )}
          </svg>
          <span className="ac-fullscreen-label">
            {isFullscreen ? t("Свернуть", "Kichraytirish", "Restore") : t("На весь экран", "To'liq ekran", "Full screen")}
          </span>
        </button>
        {menu === "span" && (
          <div className="ac-menu ac-span-menu">
            <label>{t("С", "Dan", "From")}
              <input type="date" value={span.from}
                onChange={(e) => setSpan((s) => ({ ...s, from: e.target.value }))} />
            </label>
            <label>{t("По", "Gacha", "To")}
              <input type="date" value={span.to}
                onChange={(e) => setSpan((s) => ({ ...s, to: e.target.value }))} />
            </label>
            <button type="button" className="ac-menu-clear"
              onClick={() => { setSpan({ from: "", to: "" }); setMenu(null); }}>
              {t("Сбросить", "Tozalash", "Clear")}
            </button>
          </div>
        )}
      </div>

      <AdvancedCompareBar peers={peers} allRows={preparedRows} securitiesMap={securitiesMap}
        selected={compareTickers} colors={QC_COLORS} onToggle={toggleCompare}
        lang={lang} max={QC_MAX} />

      <div className="ac-body">
        <div className="ac-rail-wrap">
          <AdvancedChartRail rows={preparedRows} securitiesMap={securitiesMap} ticker={up}
            favorites={favorites} onToggleFavorite={onToggleFavorite} lang={lang} signedIn={signedIn}
            onOpen={openPeerChart} />
        </div>
        <button type="button" className="ac-rail-toggle" onClick={() => setRailOpen((v) => !v)}
          aria-label={railOpen ? t("Скрыть список", "Ro'yxatni yashirish", "Hide the list")
                               : t("Показать список", "Ro'yxatni ko'rsatish", "Show the list")}>
          {railOpen ? "‹" : "›"}
        </button>

        <div className="ac-plot" ref={attach} style={{ height: plotH }}>
          {loading && <div className="ac-state muted">{t("Загрузка…", "Yuklanmoqda…", "Loading…")}</div>}
          {failed && (
            <div className="ac-state">
              <p>{t("Не удалось загрузить историю цен.", "Narxlar tarixini yuklab bo'lmadi.", "Failed to load the price history.")}</p>
              <button className="primary-btn" type="button" onClick={() => setRetry((v) => v + 1)}>
                {t("Повторить", "Qayta urinish", "Retry")}
              </button>
            </div>
          )}
          {emptyState && !failed && (
            <div className="ac-state muted">
              {custom
                ? t("За выбранный период сделок не было", "Tanlangan davrda bitim bo'lmagan", "No trades in the selected period")
                : t("История цен недоступна", "Narxlar tarixi mavjud emas", "Price history unavailable")}
            </div>
          )}

          {!loading && !failed && n >= 2 && (
            <>
              {legendChips.length > 0 && (
                <div className="ac-legend">
                  {legendChips.map((c) => (
                    <button key={c.key} type="button" className="ac-legend-chip"
                      style={{ "--ac-color": c.color }} onClick={c.off}>
                      <span className="ac-legend-dot" />{c.text}<span className="ac-legend-x">✕</span>
                    </button>
                  ))}
                </div>
              )}

              <svg className={`ac-svg ${chartNavigation ? "is-candle-interactive" : ""} ${candleDragging ? "is-panning" : ""}`}
                viewBox={`0 0 ${W} ${H}`} width="100%" height={H}
                aria-label={chartNavigation
                  ? t("График. Ctrl и колесо меняют масштаб, перетаскивание показывает историю.",
                      "Grafik. Ctrl va g'ildirak masshtabni o'zgartiradi, sudrash tarixni ko'rsatadi.",
                      "Chart. Ctrl and the wheel zoom; drag to browse history.")
                  : undefined}
                onPointerDown={onCandlePointerDown}
                onPointerMove={onCandlePointerMove}
                onPointerUp={endCandleDrag}
                onPointerCancel={endCandleDrag}
                onClick={addTrendPoint}
                onPointerLeave={() => { if (!candleDrag.current) setHover(null); }}>
                <defs>
                  <linearGradient id="acArea" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stopColor={priceColor} stopOpacity="0.26" />
                    <stop offset="100%" stopColor={priceColor} stopOpacity="0.02" />
                  </linearGradient>
                  <linearGradient id="acBase" x1="0" y1={priceTop} x2="0" y2={priceBot}
                    gradientUnits="userSpaceOnUse">
                    <stop offset="0" stopColor="#2fc584" stopOpacity="0.34" />
                    <stop offset={Math.max(0, Math.min(1, (ys(baseLevel) - priceTop) / (priceBot - priceTop)))}
                      stopColor="#2fc584" stopOpacity="0.04" />
                    <stop offset={Math.max(0, Math.min(1, (ys(baseLevel) - priceTop) / (priceBot - priceTop)))}
                      stopColor="#ee6a60" stopOpacity="0.04" />
                    <stop offset="1" stopColor="#ee6a60" stopOpacity="0.34" />
                  </linearGradient>
                </defs>

                {yLabels.map((tick, i) => (
                  <g key={`y${i}`}>
                    <line x1={PAD.left} y1={tick.y} x2={W - PAD.right} y2={tick.y}
                      stroke="currentColor" strokeOpacity="0.14" strokeDasharray="4 6" strokeWidth="0.8" />
                    <text x={W - PAD.right + 8} y={tick.y + 4} fontSize="11" fill="currentColor" opacity="0.55">
                      {tick.label}
                    </text>
                  </g>
                ))}
                {cmpOn && minP <= 0 && maxP >= 0 && (
                  <line x1={PAD.left} y1={ys(0)} x2={W - PAD.right} y2={ys(0)}
                    stroke="currentColor" strokeOpacity="0.4" strokeWidth="0.9" />
                )}

                {ind.bb && (
                  <>
                    <path d={`${linePath(ind.bb.upper.map(toScaleOrNull(toScale)), ys)}`} fill="none"
                      stroke="#14b8a6" strokeWidth="1" strokeOpacity="0.7" />
                    <path d={`${linePath(ind.bb.lower.map(toScaleOrNull(toScale)), ys)}`} fill="none"
                      stroke="#14b8a6" strokeWidth="1" strokeOpacity="0.7" />
                    <path d={`${linePath(ind.bb.mid.map(toScaleOrNull(toScale)), ys)}`} fill="none"
                      stroke="#14b8a6" strokeWidth="1" strokeOpacity="0.45" strokeDasharray="4 4" />
                  </>
                )}

                {drawType === "area" && !drawCandles && (
                  <path d={`${baseD} L${xs(n - 1).toFixed(1)},${priceBot} L${xs(0).toFixed(1)},${priceBot} Z`}
                    fill="url(#acArea)" />
                )}
                {drawType === "baseline" && !drawCandles && (
                  <path d={`${baseD} L${xs(n - 1).toFixed(1)},${ys(baseLevel).toFixed(1)} L${xs(0).toFixed(1)},${ys(baseLevel).toFixed(1)} Z`}
                    fill="url(#acBase)" />
                )}
                {drawType === "baseline" && (
                  <line x1={PAD.left} y1={ys(baseLevel)} x2={W - PAD.right} y2={ys(baseLevel)}
                    stroke="currentColor" strokeOpacity="0.35" strokeDasharray="3 4" />
                )}

                {drawCandles ? candleDrawPoints.map((p, i) => {
                  const okp = ohlcOk(p);
                  const upDay = okp ? p.close >= p.open : (i > 0 ? p.close >= points[i - 1].close : true);
                  const c = upDay ? "#2fc584" : "#ee6a60";
                  const w = Math.max(1, Math.min(9, gapPx * 0.68));
                  const x = xs(i);
                  if (!okp) {
                    return <line key={`k${i}`} className="ac-candle" x1={x} y1={ys(p.close)} x2={x} y2={ys(p.close) + 1}
                      stroke={c} strokeWidth={Math.max(1, w)} />;
                  }
                  const yo = ys(p.open), yc = ys(p.close);
                  return (
                    <g key={`k${i}`} className="ac-candle">
                      <line x1={x} y1={ys(p.high)} x2={x} y2={ys(p.low)} stroke={c} strokeWidth="1" />
                      <rect x={x - w / 2} y={Math.min(yo, yc)} width={w}
                        height={Math.max(1, Math.abs(yc - yo))} fill={c} />
                    </g>
                  );
                }) : drawType === "bars" ? points.map((p, i) => {
                  if (!ohlcOk(p)) return null;
                  const c = p.close >= p.open ? "#2fc584" : "#ee6a60";
                  const x = xs(i), tick = Math.max(2, Math.min(6, gapPx * 0.32));
                  return <g key={`bar${i}`} className="ac-ohlc-bar">
                    <line x1={x} y1={ys(p.high)} x2={x} y2={ys(p.low)} stroke={c} strokeWidth="1.4" />
                    <line x1={x - tick} y1={ys(p.open)} x2={x} y2={ys(p.open)} stroke={c} strokeWidth="1.4" />
                    <line x1={x} y1={ys(p.close)} x2={x + tick} y2={ys(p.close)} stroke={c} strokeWidth="1.4" />
                  </g>;
                }) : drawType === "columns" ? points.map((p, i) => {
                  const y = ys(baseVals[i]);
                  const previous = i ? baseVals[i - 1] : baseVals[i];
                  return <rect key={`col${i}`} className="ac-price-column"
                    x={xs(i) - Math.max(1, gapPx * 0.34)} y={Math.min(y, priceBot)}
                    width={Math.max(2, gapPx * 0.68)} height={Math.max(1, priceBot - y)}
                    fill={baseVals[i] >= previous ? "#2fc584" : "#ee6a60"} fillOpacity="0.78" />;
                }) : drawType === "renko" ? renko.bricks.map((brick, i) => {
                  const width = innerW / Math.max(1, renko.bricks.length);
                  const y1 = ys(brick.from), y2 = ys(brick.to);
                  return <rect key={`renko${i}`} className="ac-renko-brick"
                    x={PAD.left + i * width} y={Math.min(y1, y2)} width={Math.max(2, width * 0.92)}
                    height={Math.max(2, Math.abs(y2 - y1))} fill={brick.direction > 0 ? "#2fc584" : "#ee6a60"}
                    fillOpacity="0.72" stroke={brick.direction > 0 ? "#2fc584" : "#ee6a60"} />;
                }) : drawType === "kagi" ? (
                  <path className="ac-kagi-line" d={kagi.turns.reduce((path, turn, i) => {
                    const x = PAD.left + (i / Math.max(1, kagi.turns.length - 1)) * innerW;
                    return i ? `${path} H${x.toFixed(1)} V${ys(turn.value).toFixed(1)}` : `M${x.toFixed(1)},${ys(turn.value).toFixed(1)}`;
                  }, "")} fill="none" stroke={priceColor} strokeWidth="2.2" strokeLinejoin="round" />
                ) : drawType === "point_figure" ? pointFigure.columns.map((column, i) => {
                  const x = PAD.left + ((i + 0.5) / Math.max(1, pointFigure.columns.length)) * innerW;
                  const from = Math.round(column.from / pointFigure.box), to = Math.round(column.to / pointFigure.box);
                  const levels = Array.from({ length: Math.min(80, Math.abs(to - from) + 1) }, (_, j) => from + Math.sign(to - from || 1) * j);
                  return <g key={`pnf${i}`} className={`ac-pnf-column ${column.direction > 0 ? "up" : "down"}`}>
                    {levels.map((level) => <text key={level} x={x} y={ys(level * pointFigure.box) + 4}
                      textAnchor="middle" fontSize={Math.max(7, Math.min(13, innerW / Math.max(20, pointFigure.columns.length * 1.4)))}
                      fill={column.direction > 0 ? "#2fc584" : "#ee6a60"}>{column.direction > 0 ? "×" : "○"}</text>)}
                  </g>;
                }) : (
                  <path d={baseD} fill="none" stroke={drawType === "baseline" ? "url(#acBase)" : priceColor}
                    strokeWidth="1.8" strokeLinejoin="round" strokeLinecap="round" />
                )}

                {["sma50", "sma200", "ema50", "ema200"].map((k) => (ind[k] ? (
                  <path key={k} d={linePath(ind[k].map(toScaleOrNull(toScale)), ys)} fill="none"
                    stroke={AC_INDICATORS.find((d) => d.key === k).color} strokeWidth="1.4" strokeOpacity="0.95" />
                ) : null))}

                {cmpOn && cmp.series.map((s) => (
                  <path key={`cs${s.ticker}`} d={linePath(s.pct, ys)} fill="none" stroke={s.color}
                    strokeWidth="1.5" strokeOpacity="0.95" strokeLinejoin="round" />
                ))}

                {drawPoints.length === 2 && points[drawPoints[0]] && points[drawPoints[1]] && (
                  <line className="ac-trend-line" x1={xs(drawPoints[0])} y1={ys(baseVals[drawPoints[0]])}
                    x2={xs(drawPoints[1])} y2={ys(baseVals[drawPoints[1]])}
                    stroke="var(--accent)" strokeWidth="2" strokeDasharray="5 3" />
                )}

                {/* Volume. Not decoration: on this market a move worth 40 000
                    сум and a move worth 400 млн are different events, and the
                    price line cannot tell them apart. Money rather than share
                    count, so a 2 сум share and a 23 000 сум one are on the same
                    scale — and so the bar agrees with the readout above it. */}
                {points.map((p, i) => {
                  const v = p.turnover || 0;
                  const w = Math.max(1.5, Math.min(10, gapPx * 0.76));
                  // A carried close with no turnover used to disappear entirely,
                  // leaving unexplained holes between otherwise continuous dates.
                  // Keep zero honest (never invent a coloured volume bar), but
                  // draw a neutral baseline tick so the reader can distinguish a
                  // no-trade / unpublished-volume session from a rendering bug.
                  if (!v) return (
                    <rect key={`v0${i}`} className="ac-volume-empty"
                      x={xs(i) - w / 2} y={volBot - 8} width={w} height="8"
                      fill="currentColor" fillOpacity="0.2">
                      <title>{t("Торгов не было или объём не опубликован",
                                "Savdo bo'lmagan yoki hajm e'lon qilinmagan",
                                "No trades or volume was not published")}</title>
                    </rect>
                  );
                  // A fourth-root display scale keeps genuinely small sessions
                  // readable beside rare multi-million spikes. Square-root still
                  // crushed KFSK's older 48k–100k sessions into an 8px baseline
                  // while recent 11.8m sessions filled the pane, which looked like
                  // missing data. The tooltip keeps the exact turnover; only the
                  // visual height is compressed.
                  const volumeRatio = Math.min(1, v / volumeScale);
                  // A 12px floor was still effectively invisible at the 115%
                  // browser scale used on the market workstation: KFSK's small
                  // sessions looked like missing columns between the large ones.
                  // Reserve one fifth of the pane as the visible floor. Exact
                  // magnitude remains in the tooltip; the bar chart communicates
                  // both presence and relative activity without blank-looking days.
                  const h = Math.max(32, Math.pow(volumeRatio, 0.25) * (volBot - volTop));
                  const upDay = i > 0 ? p.close >= points[i - 1].close : true;
                  return <rect key={`v${i}`} className="ac-volume-bar" x={xs(i) - w / 2} y={volBot - h} width={w} height={h}
                    fill={upDay ? "#2fc584" : "#ee6a60"} fillOpacity="0.9" />;
                })}
                <line x1={PAD.left} y1={volBot} x2={W - PAD.right} y2={volBot}
                  stroke="currentColor" strokeOpacity="0.18" />
                <line x1={PAD.left} y1={volTop + VOL_H / 2} x2={W - PAD.right} y2={volTop + VOL_H / 2}
                  stroke="currentColor" strokeOpacity="0.08" strokeDasharray="3 5" />
                <text x={PAD.left + 4} y={volTop + 15} fontSize="12" fontWeight="600" fill="currentColor" opacity="0.72">
                  {t("Объём", "Hajm", "Volume")} · {fmtCompact(maxVol, lang)} {t("сум", "so'm", "UZS")}
                </text>

                {subPanes.map((pane, pi) => {
                  const top = subTop(pi), bot = top + SUB_H;
                  const frame = (
                    <>
                      <line x1={PAD.left} y1={bot} x2={W - PAD.right} y2={bot}
                        stroke="currentColor" strokeOpacity="0.18" />
                    </>
                  );
                  if (pane.key === "rsi" || pane.key === "stoch") {
                    const lo = 0, hi = 100;
                    const yv = (v) => top + (1 - (v - lo) / (hi - lo)) * SUB_H;
                    const guides = pane.key === "rsi" ? [30, 70] : [20, 80];
                    return (
                      <g key={pane.key}>
                        {frame}
                        {guides.map((g) => (
                          <line key={g} x1={PAD.left} y1={yv(g)} x2={W - PAD.right} y2={yv(g)}
                            stroke="currentColor" strokeOpacity="0.18" strokeDasharray="3 5" />
                        ))}
                        {pane.key === "rsi" && (
                          <path d={linePath(ind.rsi || [], yv)} fill="none" stroke="#22d3ee" strokeWidth="1.4" />
                        )}
                        {pane.key === "stoch" && (
                          <>
                            <path d={linePath(ind.stoch?.k || [], yv)} fill="none" stroke="#a3e635" strokeWidth="1.4" />
                            <path d={linePath(ind.stoch?.d || [], yv)} fill="none" stroke="#fb923c" strokeWidth="1.2" strokeDasharray="4 3" />
                          </>
                        )}
                        <text x={PAD.left + 2} y={top + 11} fontSize="10" fill="currentColor" opacity="0.6">
                          {pane.key === "rsi" ? "RSI 14" : "Stoch 14/3"}
                        </text>
                        {[guides[0], guides[1]].map((g) => (
                          <text key={`gl${g}`} x={W - PAD.right + 8} y={yv(g) + 4} fontSize="10"
                            fill="currentColor" opacity="0.5">{g}</text>
                        ))}
                      </g>
                    );
                  }
                  if (pane.key === "macd") {
                    const vals = [...(ind.macd?.line || []), ...(ind.macd?.signal || []), ...(ind.macd?.hist || [])]
                      .filter((v) => v != null);
                    const m = Math.max(1e-9, ...vals.map(Math.abs));
                    const yv = (v) => top + SUB_H / 2 - (v / m) * (SUB_H / 2 - 4);
                    return (
                      <g key={pane.key}>
                        {frame}
                        <line x1={PAD.left} y1={yv(0)} x2={W - PAD.right} y2={yv(0)}
                          stroke="currentColor" strokeOpacity="0.22" />
                        {(ind.macd?.hist || []).map((v, i) => (v == null ? null : (
                          <rect key={`mh${i}`} x={xs(i) - Math.max(0.6, gapPx * 0.3)} y={Math.min(yv(0), yv(v))}
                            width={Math.max(1.2, gapPx * 0.6)} height={Math.max(0.6, Math.abs(yv(v) - yv(0)))}
                            fill={v >= 0 ? "#2fc584" : "#ee6a60"} fillOpacity="0.45" />
                        )))}
                        <path d={linePath(ind.macd?.line || [], yv)} fill="none" stroke="#f472b6" strokeWidth="1.4" />
                        <path d={linePath(ind.macd?.signal || [], yv)} fill="none" stroke="#facc15" strokeWidth="1.2" />
                        <text x={PAD.left + 2} y={top + 11} fontSize="10" fill="currentColor" opacity="0.6">MACD 12/26/9</text>
                      </g>
                    );
                  }
                  const f = pane.fin;
                  const fv = f.values.filter((v) => v != null);
                  if (!fv.length) {
                    return (
                      <g key={pane.key}>
                        {frame}
                        <text x={PAD.left + 2} y={top + 11} fontSize="10" fill="currentColor" opacity="0.6">
                          {finLabel(f.field, lang)}
                        </text>
                        <text x={PAD.left + 2} y={top + SUB_H / 2} fontSize="11" fill="currentColor" opacity="0.45">
                          {t("Нет отчётности за этот период", "Bu davr uchun hisobot yo'q", "No filing covers this period")}
                        </text>
                      </g>
                    );
                  }
                  const lo = Math.min(...fv), hi = Math.max(...fv);
                  const sp = hi - lo || Math.abs(hi) || 1;
                  const yv = (v) => top + SUB_H - 8 - ((v - lo) / sp) * (SUB_H - 18);
                  return (
                    <g key={pane.key}>
                      {frame}
                      {/* A step, because an annual figure does not drift through
                          its year — it lands when the filing does. */}
                      <path d={stepPath(f.values, yv)} fill="none" stroke={f.color} strokeWidth="1.5" />
                      <text x={PAD.left + 2} y={top + 11} fontSize="10" fill={f.color} opacity="0.9">
                        {finLabel(f.field, lang)}{f.unit ? `, ${f.unit}` : ""}
                      </text>
                      <text x={W - PAD.right + 8} y={top + 12} fontSize="10" fill="currentColor" opacity="0.5">{abbrev(hi)}</text>
                      <text x={W - PAD.right + 8} y={top + SUB_H - 2} fontSize="10" fill="currentColor" opacity="0.5">{abbrev(lo)}</text>
                    </g>
                  );
                })}

                {xLabels.map((tick, i) => (
                  <text key={`x${i}`} x={tick.x} y={H - 8} fontSize="11" fill="currentColor" opacity="0.55"
                    textAnchor={tick.x < PAD.left + 30 ? "start" : tick.x > W - PAD.right - 30 ? "end" : "middle"}>
                    {tick.label}
                  </text>
                ))}

                {adjustments.map((a) => {
                  const i = points.findIndex((p) => String(p.date) >= String(a.ex_date));
                  return i > 0 ? (
                    <line key={`adj${a.ex_date}`} x1={xs(i)} y1={priceTop} x2={xs(i)} y2={priceBot}
                      stroke="currentColor" strokeOpacity="0.3" strokeDasharray="2 4" />
                  ) : null;
                })}

                {hover != null && (
                  <g>
                    <line x1={xs(hover)} y1={priceTop} x2={xs(hover)}
                      y2={subPanes.length ? subTop(subPanes.length - 1) + SUB_H : volBot}
                      stroke="currentColor" strokeOpacity="0.4" strokeDasharray="3 3" />
                    <circle cx={xs(hover)} cy={ys(baseVals[hover])} r="3.6" fill={priceColor}
                      stroke="var(--panel, #0b0f1a)" strokeWidth="1.5" />
                    {cmpOn && cmp.series.map((s) => (s.pct[hover] == null ? null : (
                      <circle key={`ch${s.ticker}`} cx={xs(hover)} cy={ys(s.pct[hover])} r="3.2"
                        fill={s.color} stroke="var(--panel, #0b0f1a)" strokeWidth="1.5" />
                    )))}
                    <rect x={W - PAD.right + 2} y={ys(baseVals[hover]) - 9} width={PAD.right - 6} height="18"
                      rx="3" fill={priceColor} />
                    <text x={W - PAD.right + 6} y={ys(baseVals[hover]) + 4} fontSize="10.5" fill="#04140a">
                      {cmpOn ? fmtPctVal(baseVals[hover]) : fmtFull(points[hover].close)}
                    </text>
                  </g>
                )}
              </svg>

              {hp && (
                <div className="ac-tooltip" style={{
                  left: Math.min(Math.max(12, pointer.x + 16), Math.max(12, (box.w || W) - 210)),
                  top: Math.min(Math.max(8, pointer.y - 30), Math.max(8, (box.h || H) - 200)),
                }}>
                  <div className="ac-tt-date">{fmtDate(hp.date, true)}</div>
                  {ohlcOk(hp) && (
                    <>
                      <div className="ac-tt-row"><span>{t("Откр.", "Ochil.", "Open")}</span><b>{fmtFull(hp.open)}</b></div>
                      <div className="ac-tt-row"><span>{t("Макс.", "Maks.", "High")}</span><b>{fmtFull(hp.high)}</b></div>
                      <div className="ac-tt-row"><span>{t("Мин.", "Min.", "Low")}</span><b>{fmtFull(hp.low)}</b></div>
                    </>
                  )}
                  <div className="ac-tt-row"><span>{t("Закрытие", "Yopilish", "Close")}</span><b>{fmtFull(hp.close)}</b></div>
                  <div className="ac-tt-row"><span>{t("Объём", "Hajm", "Volume")}</span>
                    <b>{hp.turnover ? `${fmtCompact(hp.turnover, lang)} ${t("сум", "so'm", "UZS")}` : "—"}</b>
                  </div>
                  {relVol != null && (
                    <div className="ac-tt-row"><span>{t("Объём к среднему", "O'rtacha hajmga", "Vol vs avg")}</span>
                      <b>{fmtRelVol(relVol, lang)}</b>
                    </div>
                  )}
                  {cmpOn && (
                    <div className="ac-tt-block">
                      <div className="ac-tt-row"><span style={{ color: priceColor }}>{up}</span>
                        <b style={{ color: priceColor }}>{fmtPctVal(baseVals[hover])}</b></div>
                      {cmp.series.map((s) => {
                        const pv = peerVolumeAt(s.volHist, hp.date);
                        return (
                          <React.Fragment key={`tt${s.ticker}`}>
                            <div className="ac-tt-row">
                              <span style={{ color: s.color }}>{s.ticker}</span>
                              <b style={{ color: s.color }}>{fmtPctVal(s.pct[hover])}</b>
                            </div>
                            <div className="ac-tt-row ac-tt-volrow">
                              <span>{t("объём", "hajm", "vol")}</span>
                              <b>{pv
                                ? `${fmtCompact(pv.turnover, lang)}${pv.rel != null ? ` · ${fmtRelVol(pv.rel, lang)}` : ""}`
                                : "—"}</b>
                            </div>
                          </React.Fragment>
                        );
                      })}
                    </div>
                  )}
                  {(indicators.size > 0 || finPanes.length > 0) && (
                    <div className="ac-tt-block">
                      {AC_INDICATORS.filter((d) => indicators.has(d.key)).map((d) => {
                        const v = d.key === "bb" ? ind.bb?.mid?.[hover]
                          : d.key === "macd" ? ind.macd?.line?.[hover]
                          : d.key === "stoch" ? ind.stoch?.k?.[hover]
                          : ind[d.key]?.[hover];
                        return (
                          <div className="ac-tt-row" key={`tti${d.key}`}>
                            <span style={{ color: d.color }}>{d.label[lang === "uz" ? 1 : lang === "en" ? 2 : 0]}</span>
                            <b>{fmtFull(v)}</b>
                          </div>
                        );
                      })}
                      {finPanes.map((f) => (
                        <div className="ac-tt-row" key={`ttf${f.field}`}>
                          <span style={{ color: f.color }}>{finLabel(f.field, lang)}</span>
                          <b>{f.values[hover] == null ? "—"
                            : `${abbrev(f.values[hover])}${f.unit ? ` ${f.unit}` : ""}`}</b>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </>
          )}
        </div>
      </div>

      <div className="ac-notes">
        {chartNavigation && points.length > 0 && (
          <p className="ac-history-help" data-testid="ac-visible-range"
            data-from={points[0].date} data-to={points[points.length - 1].date}>
            <span>
              {t("Ctrl + колесо: вверх — приблизить, вниз — отдалить; потяните график — перейти по истории.",
                 "Ctrl + g'ildirak: yuqoriga — yaqinlashtirish, pastga — uzoqlashtirish; tarix uchun grafikni suring.",
                 "Ctrl + wheel: up zooms in, down zooms out; drag the chart to browse history.")}
            </span>
            <span className="ac-history-dates">{fmtDate(points[0].date, true)} — {fmtDate(points[points.length - 1].date, true)}</span>
            {candleViewChanged && (
              <button type="button" className="ac-history-reset" onClick={() => setCandleView(null)}>
                {t("Сбросить", "Tiklash", "Reset")}
              </button>
            )}
          </p>
        )}
        {stepLine && (
          <p className="muted">
            {t("Цена показана ступенями — между сделками она не менялась.",
               "Narx pog'onalar bilan — bitimlar orasida u o'zgarmagan.",
               "The price is drawn as steps — between trades it did not move.")}
            {quality?.reason ? ` ${quality.reason}` : ""}
          </p>
        )}
        {AC_SYNTHETIC_TYPES.has(drawType) && (
          <p className="muted ac-synthetic-note">
            {t("Расчётный вид по дневным данным; значения фигур синтетические и не являются ценами сделок.",
               "Kunlik ma’lumotlar asosidagi hisobiy ko‘rinish; shakl qiymatlari sintetik va bitim narxlari emas.",
               "Calculated from daily data; figure values are synthetic and are not traded prices.")}
          </p>
        )}
        {cmpOn && cmp.start && (
          <p className="muted">
            {t(`Сравнение считается с ${fmtDate(cmp.start, true)} — раньше сохранённых котировок нет.`,
               `Taqqoslash ${fmtDate(cmp.start, true)} dan — undan oldingi kotirovkalar yo'q.`,
               `The comparison starts on ${fmtDate(cmp.start, true)} — there are no stored quotes before it.`)}
          </p>
        )}
        {cmp && cmp.dropped.length > 0 && !cmpLoading && (
          <p className="muted">
            {t("Нет сохранённых котировок за этот период: ", "Bu davr uchun kotirovkalar yo'q: ", "No stored quotes for this period: ")}
            {cmp.dropped.map((c) => c.ticker).join(", ")}
          </p>
        )}
        {adjustments.length > 0 && (
          <p className="muted">
            {t("Пунктиром отмечены дробления и бонусные эмиссии; цены до них пересчитаны на текущую акцию.",
               "Punktir bilan maydalash va bonus emissiyalar belgilangan; ulardan oldingi narxlar qayta hisoblangan.",
               "The dashed lines mark splits and bonus issues; prices before them are restated onto the current share.")}
          </p>
        )}
        {finFields.length > 0 && (
          <p className="muted">
            {t("Годовой показатель нанесён на 31 декабря своего периода и держится до следующего отчёта — раньше его не существовало.",
               "Yillik ko'rsatkich o'z davrining 31 dekabriga qo'yilgan va keyingi hisobotgacha saqlanadi.",
               "An annual figure is placed on 31 December of its period and held until the next filing — before that it did not exist.")}
          </p>
        )}
      </div>
      <TechnicalBacktestCard ticker={ticker} lang={lang} apiFetch={apiFetch} signedIn={signedIn}
        hasProAccess={hasProAccess} onUpgrade={onUpgrade} />
    </div>
  );
}

/** Scale a price-unit indicator onto whatever the price pane is measuring. */
function toScaleOrNull(toScale) {
  return (v) => (v == null || !Number.isFinite(v) ? null : toScale(v));
}

function CompanyInfoPanel({ ticker, secInfo, wikiInfo, language, onClose, loading }) {
  const lang = normalizeLanguage(language);
  const panelRef = useRef(null);
  const closeRef = useRef(null);
  const onCloseRef = useRef(onClose);
  onCloseRef.current = onClose;

  useEffect(() => {
    if (!ticker) return undefined;

    // This drawer is rendered through a body portal below. Keep the page at the
    // row that opened it, move focus into the dialog, and return focus to that
    // row's info button when the drawer closes.
    const returnFocus = document.activeElement;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    const focusFrame = window.requestAnimationFrame(() => closeRef.current?.focus());

    const onKeyDown = (event) => {
      if (event.key === "Escape") {
        event.preventDefault();
        onCloseRef.current?.();
        return;
      }
      if (event.key !== "Tab" || !panelRef.current) return;
      const focusable = [...panelRef.current.querySelectorAll(
        'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])',
      )].filter((element) => !element.hasAttribute("hidden"));
      if (!focusable.length) return;
      const first = focusable[0];
      const last = focusable.at(-1);
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    };

    document.addEventListener("keydown", onKeyDown);
    return () => {
      window.cancelAnimationFrame(focusFrame);
      document.removeEventListener("keydown", onKeyDown);
      document.body.style.overflow = previousOverflow;
      if (returnFocus instanceof HTMLElement && returnFocus.isConnected) returnFocus.focus();
    };
  }, [ticker]);

  if (!ticker) return null;
  const name = secInfo?.name || ticker;
  const logo = secInfo?.logo_url;
  const sector = secInfo?.sector;
  const isin = secInfo?.isin;
  const isPreferred = secInfo?.is_preferred;
  const secType = secInfo?.type;

  const sectorText = sector ? sectorLabel(lang, sector) : null;
  const typeLabels = { stock: lang === "en" ? "Stock" : lang === "uz" ? "Aksiya" : "Акция", bond: lang === "en" ? "Bond" : lang === "uz" ? "Obligatsiya" : "Облигация" };
  const closeLabel = lang === "en" ? "Close company details" : lang === "uz" ? "Kompaniya ma'lumotlarini yopish" : "Закрыть сведения о компании";
  const titleId = `company-panel-title-${String(ticker).replace(/[^a-zA-Z0-9_-]/g, "-")}`;

  return createPortal(
    <div className="company-panel-overlay" onClick={onClose}>
      <aside
        ref={panelRef}
        className="company-info-panel"
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        onClick={(e) => e.stopPropagation()}
      >
        <button ref={closeRef} className="company-panel-close" type="button" onClick={onClose} aria-label={closeLabel} title={closeLabel}>×</button>
        <div className="company-panel-header">
          <CompanyLogo logo={logo} name={name} ticker={ticker} />
          <div className="company-panel-title">
            <h2 id={titleId}>{name}</h2>
            <div className="company-panel-meta">
              <span className="status-badge muted">{ticker}</span>
              {isin && <span className="status-badge muted">{isin}</span>}
              {sectorText && <span className="status-badge">{sectorText}</span>}
              {secType && <span className="status-badge muted">{typeLabels[secType] || secType}</span>}
              {isPreferred && <span className="status-badge muted">{lang === "en" ? "Preferred" : lang === "uz" ? "Imtiyozli" : "Привилег."}</span>}
            </div>
          </div>
        </div>
        <div className="company-panel-body">
          {loading ? (
            <p className="company-panel-wiki muted">{lang === "en" ? "Loading..." : lang === "uz" ? "Yuklanmoqda..." : "Загрузка..."}</p>
          ) : wikiInfo?.extract ? (
            <>
              <p className="company-panel-wiki">{wikiInfo.extract}</p>
              {wikiInfo.page_url && (
                <a href={wikiInfo.page_url} target="_blank" rel="noreferrer" className="company-panel-wiki-link">
                  {wikiInfo.source === "wikipedia"
                    ? (lang === "en" ? "Read on Wikipedia →" : lang === "uz" ? "Vikipediyada o'qish →" : "Читать на Википедии →")
                    : (lang === "en" ? "Official website →" : lang === "uz" ? "Rasmiy sayt →" : "Официальный сайт →")}
                </a>
              )}
            </>
          ) : (
            <p className="company-panel-wiki muted">
              {lang === "en" ? "No description available." : lang === "uz" ? "Tavsif mavjud emas." : "Описание недоступно."}
            </p>
          )}
          {secInfo?.last_price != null && (
            <div className="company-panel-price">
              <span className="company-panel-price-label">{lang === "en" ? "Last price" : lang === "uz" ? "Oxirgi narx" : "Последняя цена"}</span>
              <strong className="company-panel-price-value">{Number(secInfo.last_price).toLocaleString(lang === "en" ? "en-US" : "ru-RU")} сум</strong>
              {secInfo.last_trade_date && <span className="muted">{secInfo.last_trade_date}</span>}
            </div>
          )}
        </div>
      </aside>
    </div>,
    document.body,
  );
}

// A floating horizontal scrollbar for the wide market table, clung to the bottom of
// the table's visible area (the screen bottom while the table runs off the fold).
// The table's own scroll container (.market-table-wrap) has no height cap, so its
// native horizontal scrollbar sits at the very bottom of a tall table — unreachable
// without scrolling the whole page down. We hide that native bar (see CSS) and mirror
// it here so it's always reachable. Rendered via a body portal because the table's
// ancestors (.market-board overflow:hidden + backdrop-filter, .app-shell-wrap
// overflow:hidden) would otherwise clip/mis-anchor a position:fixed element.
function MarketFloatScroll({ wrapRef, colSignature, rowCount, loading }) {
  const trackRef = useRef(null);
  const [box, setBox] = useState({ show: false, left: 0, width: 0, top: 0 });
  const [thumb, setThumb] = useState({ width: 0, left: 0 });
  const drag = useRef(null);
  const MIN_THUMB = 40;

  // Track geometry + thumb size/position, derived from the table's live scroll state.
  useEffect(() => {
    const wrap = wrapRef.current;
    if (!wrap) return undefined;
    let raf = 0;
    const measure = () => {
      raf = 0;
      const el = wrapRef.current;
      if (!el) return;
      const r = el.getBoundingClientRect();
      const sw = el.scrollWidth, cw = el.clientWidth;
      const max = sw - cw;
      // The bar is a fixed child of the zoomed root, so its geometry is written in
      // CSS pixels while the rect arrives in viewport pixels — see rootZoom().
      const { zoom, vw, vh } = zoomedViewport();
      // Clamp to the table's VISIBLE rectangle: the wrap can extend past the viewport
      // (the layout has a min-width and .app-shell-wrap clips the overflow).
      const left = Math.max(r.left / zoom, 0);
      const right = Math.min(r.right / zoom, vw);
      const trackW = right - left;
      const rTop = r.top / zoom, rBottom = r.bottom / zoom;
      // The wrap's native bar is hidden (see CSS) — this floating bar is the only
      // horizontal scrollbar. It clings to the viewport bottom while the table runs
      // below the fold, and to the table's own bottom edge once the end scrolls into
      // view, so exactly one bar is visible whenever the table is on screen.
      const inView = max > 1 && rTop < vh && rBottom > 40 && trackW > 40;
      if (!inView) {
        setBox((b) => (b.show ? { ...b, show: false } : b));
        return;
      }
      const BAR = 14;
      const top = Math.min(vh, rBottom) - BAR;
      setBox({ show: true, left, width: trackW, top });
      const tw = Math.max(trackW * (cw / sw), MIN_THUMB);
      const tl = max > 0 ? (el.scrollLeft / max) * (trackW - tw) : 0;
      setThumb({ width: tw, left: tl });
    };
    const schedule = () => { if (!raf) raf = requestAnimationFrame(measure); };
    measure();
    // capture:true reaches window for the wrap's own (non-bubbling) horizontal scroll too.
    window.addEventListener("scroll", schedule, { passive: true, capture: true });
    window.addEventListener("resize", schedule);
    const ro = new ResizeObserver(schedule);
    ro.observe(wrap);
    // Table scrolled (trackpad / Shift+wheel / keyboard) -> re-derive the thumb.
    wrap.addEventListener("scroll", schedule, { passive: true });
    return () => {
      window.removeEventListener("scroll", schedule, { capture: true });
      window.removeEventListener("resize", schedule);
      wrap.removeEventListener("scroll", schedule);
      ro.disconnect();
      if (raf) cancelAnimationFrame(raf);
    };
    // colSignature/rowCount/loading: ResizeObserver won't fire when only scrollWidth changes.
  }, [wrapRef, colSignature, rowCount, loading]);

  // Drag the thumb -> the table scrolls (mapped by the thumb's travel range).
  useEffect(() => {
    const onMove = (e) => {
      const d = drag.current;
      const el = wrapRef.current;
      if (!d || !el) return;
      const denom = d.trackW - d.thumbW;
      const max = el.scrollWidth - el.clientWidth;
      // The track is measured in CSS pixels and the pointer reports viewport ones,
      // so the drag would run at 1.5x the thumb under a 150 % text size.
      const moved = (e.clientX - d.startX) / rootZoom();
      el.scrollLeft = denom > 0 ? d.startScroll + (moved / denom) * max : d.startScroll;
    };
    const onUp = () => { if (drag.current) { drag.current = null; document.body.classList.remove("market-float-dragging"); } };
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    return () => { window.removeEventListener("pointermove", onMove); window.removeEventListener("pointerup", onUp); };
  }, [wrapRef]);

  const onThumbDown = (e) => {
    const el = wrapRef.current;
    if (!el) return;
    e.preventDefault();
    drag.current = { startX: e.clientX, startScroll: el.scrollLeft, trackW: box.width, thumbW: thumb.width };
    document.body.classList.add("market-float-dragging");
  };
  const onTrackDown = (e) => {
    if (e.target !== trackRef.current) return; // ignore clicks on the thumb
    const el = wrapRef.current;
    if (!el) return;
    const clickX = (e.clientX - trackRef.current.getBoundingClientRect().left) / rootZoom();
    const dir = clickX < thumb.left ? -1 : 1; // page toward the click
    el.scrollBy({ left: dir * el.clientWidth * 0.9, behavior: "smooth" });
  };

  return createPortal(
    <div
      className="market-float-scroll"
      ref={trackRef}
      onPointerDown={onTrackDown}
      aria-hidden="true"
      style={{ display: box.show ? "block" : "none", left: box.left, width: box.width, top: box.top }}
    >
      <div className="market-float-thumb" style={{ width: thumb.width, left: thumb.left }} onPointerDown={onThumbDown} />
    </div>,
    document.body
  );
}

// The column picker ("Обзор / Объёмы / Фин. показатели / Мультипликаторы").
// It used to be an absolutely-positioned child of the toolbar, which meant it
// rode the page up on the first scroll gesture and — now that the toolbar is
// sticky and .market-board clips — would have been cut off at the board edge.
// Portaled to <body> instead: a fixed popover re-anchored to its button on
// every scroll/resize, and on a phone a bottom sheet with its own scrollport,
// so a thumb drag moves the list of columns and not the page behind it.
/**
 * The ⓘ beside an economic label: what this term means, on hover, at the point
 * the reader met it. Definitions come from lib/glossary.js by id.
 *
 * It is portaled to <body> for the same reason the column picker is — inside the
 * board's horizontal scrollport a positioned child is clipped by the scroll box,
 * so a tooltip on the rightmost header would be cut in half or scroll away from
 * the header that opened it.
 *
 * Hover opens it on a mouse; tap toggles it on a phone, where there is no hover
 * at all. Every pointer event stops at the marker: the header underneath sorts on
 * click and drags to reorder, and asking what a column means must do neither.
 */
function TermInfo({ termId, lang, label }) {
  const entry = termFor(termId, lang);
  const btnRef = useRef(null);
  const popRef = useRef(null);
  const [open, setOpen] = useState(false);
  // A hovered tooltip is `pointer-events: none` — the pointer cannot enter it,
  // which is what keeps it from flickering, and also what made its text
  // impossible to select. A CLICK pins it: it stops following the pointer, takes
  // events, and can be read, selected and copied like any other text on the page.
  const [pinned, setPinned] = useState(false);
  const [copied, setCopied] = useState(false);
  const [pos, setPos] = useState(null);
  const close = React.useCallback(() => { setOpen(false); setPinned(false); setCopied(false); }, []);

  useEffect(() => {
    if (!copied) return undefined;
    const t = setTimeout(() => setCopied(false), 1600);
    return () => clearTimeout(t);
  }, [copied]);

  useLayoutEffect(() => {
    if (!open) { setPos(null); return undefined; }
    let raf = 0;
    const place = () => {
      raf = 0;
      const btn = btnRef.current;
      if (!btn) return;
      const r = btn.getBoundingClientRect();
      // CSS pixels of the zoomed root, not viewport pixels — see rootZoom().
      const { zoom, vw, vh } = zoomedViewport();
      const mid = (r.left + r.width / 2) / zoom;
      const markerTop = r.top / zoom, markerBottom = r.bottom / zoom;
      const width = Math.min(320, vw - 24);
      const left = Math.max(12, Math.min(mid - width / 2, vw - width - 12));
      // Below the marker by default; above it when the viewport bottom is closer
      // than the tooltip is tall, so it is never half off-screen.
      const below = vh - markerBottom;
      setPos({ left, width, top: below > 190 ? markerBottom + 8 : null,
               bottom: below > 190 ? null : vh - markerTop + 8 });
    };
    const schedule = () => { if (!raf) raf = requestAnimationFrame(place); };
    place();
    // capture:true — the table's own scrollport does not bubble its scroll event.
    window.addEventListener("scroll", schedule, { passive: true, capture: true });
    window.addEventListener("resize", schedule);
    return () => {
      window.removeEventListener("scroll", schedule, { capture: true });
      window.removeEventListener("resize", schedule);
      if (raf) cancelAnimationFrame(raf);
    };
    // Pinning adds the actions row, which changes the height the placement
    // above/below the marker is decided on.
  }, [open, pinned]);

  useEffect(() => {
    if (!open) return undefined;
    const onKey = (e) => { if (e.key === "Escape") close(); };
    // A press inside the pinned tooltip is the start of a text selection or the
    // copy button — it must not be read as "clicked away".
    const onDocDown = (e) => {
      const inside = (btnRef.current && btnRef.current.contains(e.target))
        || (popRef.current && popRef.current.contains(e.target));
      if (!inside) close();
    };
    window.addEventListener("keydown", onKey);
    document.addEventListener("pointerdown", onDocDown);
    return () => {
      window.removeEventListener("keydown", onKey);
      document.removeEventListener("pointerdown", onDocDown);
    };
  }, [open, close]);

  // A term with no entry yet renders nothing rather than an ⓘ that explains nothing.
  if (!entry) return null;

  const stop = (e) => { e.stopPropagation(); };
  // What a reader pastes into a chat is the term AND its definition — a bare
  // definition arrives without saying what it defines.
  const copyText = `${entry.term} — ${entry.def}`;
  // The selection + execCommand path every browser still honours, for when the
  // async clipboard is missing, denied, or simply never answers.
  const legacyCopy = () => {
    try {
      const ta = document.createElement("textarea");
      ta.value = copyText;
      ta.setAttribute("readonly", "");
      ta.style.cssText = "position:fixed;top:0;left:0;opacity:0";
      document.body.appendChild(ta);
      ta.select();
      const done = document.execCommand("copy");
      ta.remove();
      return done;
    } catch (_) { return false; }
  };
  const copy = async (e) => {
    e.stopPropagation();
    e.preventDefault();
    // navigator.clipboard is the right API and is tried first — but its promise
    // is NOT guaranteed to settle: where the permission is withheld or the
    // window is not the focused one it can hang, and an awaited hang leaves the
    // button saying nothing at all. So it races a short deadline, and anything
    // other than a resolve falls through to the legacy path. The click's user
    // activation outlives the race, so the fallback is still allowed to run.
    const viaApi = navigator.clipboard && navigator.clipboard.writeText
      ? await Promise.race([
          navigator.clipboard.writeText(copyText).then(() => true, () => false),
          new Promise((resolve) => { setTimeout(() => resolve(null), 400); }),
        ])
      : false;
    setCopied(viaApi === true ? true : legacyCopy());
  };
  const tt = (ru, uz, en) => (lang === "en" ? en : lang === "uz" ? uz : ru);
  return (
    <>
      <button
        type="button"
        ref={btnRef}
        className={`term-info-btn${open ? " open" : ""}`}
        aria-label={`${label || entry.term} — ${lang === "en" ? "what this means" : lang === "uz" ? "bu nimani anglatadi" : "что это значит"}`}
        aria-expanded={open}
        // Hover reads, click keeps: the second press unpins, and the tooltip
        // stays up while the pointer is still on the marker.
        onClick={(e) => { e.stopPropagation(); e.preventDefault(); setOpen(true); setPinned((v) => !v); setCopied(false); }}
        onMouseDown={stop}
        onPointerDown={stop}
        onTouchStart={stop}
        onMouseEnter={() => setOpen(true)}
        onMouseLeave={() => { if (!pinned) setOpen(false); }}
        onFocus={() => setOpen(true)}
        onBlur={() => { if (!pinned) setOpen(false); }}
        onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.stopPropagation(); } }}
        onDragStart={(e) => { e.preventDefault(); e.stopPropagation(); }}
      >ℹ</button>
      {open && pos && createPortal(
        <div
          ref={popRef}
          className={`term-tooltip${pinned ? " is-pinned" : ""}`}
          role="tooltip"
          /* Pinned, the tooltip sits over a sortable header and a draggable
             one; nothing that happens inside it belongs to the table. */
          onPointerDown={stop}
          onMouseDown={stop}
          onClick={stop}
          style={{ left: pos.left, width: pos.width, ...(pos.top != null ? { top: pos.top } : { bottom: pos.bottom }) }}
        >
          <div className="term-tooltip-term">{entry.term}</div>
          <div className="term-tooltip-def">{entry.def}</div>
          {pinned ? (
            <div className="term-tooltip-actions">
              <button
                type="button"
                className={`term-tooltip-copy${copied ? " is-done" : ""}`}
                onClick={copy}
              >
                {copied ? tt("Скопировано", "Nusxalandi", "Copied") : tt("Копировать", "Nusxalash", "Copy")}
              </button>
              <span className="term-tooltip-hint">{tt("Esc — закрыть", "Esc — yopish", "Esc to close")}</span>
            </div>
          ) : (
            /* A tooltip that vanishes when approached teaches nobody that it
               can be kept. Said once, quietly, where the question is asked. */
            <div className="term-tooltip-teach">
              {tt("Нажмите, чтобы выделить и скопировать",
                  "Ajratib nusxalash uchun bosing",
                  "Click to select and copy")}
            </div>
          )}
        </div>,
        document.body,
      )}
    </>
  );
}

function MarketColsPopover({ anchorRef, onClose, title, closeLabel, children }) {
  const [pos, setPos] = useState(null);
  const [sheet, setSheet] = useState(() => window.matchMedia("(max-width: 760px)").matches);

  useEffect(() => {
    const mq = window.matchMedia("(max-width: 760px)");
    const onChange = () => setSheet(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  // Desktop geometry only — the sheet is pinned to the viewport bottom by CSS
  // and has nothing to measure.
  useLayoutEffect(() => {
    if (sheet) { setPos(null); return undefined; }
    let raf = 0;
    const place = () => {
      raf = 0;
      const btn = anchorRef.current;
      if (!btn) return;
      const r = btn.getBoundingClientRect();
      // In the units a fixed child of the (possibly zoomed) root is placed in —
      // see rootZoom(). Measured pixels come in from the rect, CSS pixels go out.
      const { zoom, vw, vh } = zoomedViewport();
      const anchorRight = r.right / zoom, anchorBottom = r.bottom / zoom;
      const width = Math.min(300, vw - 24);
      // Right-aligned to the button, but never off either edge of the viewport.
      const left = Math.max(12, Math.min(anchorRight - width, vw - width - 12));
      const top = Math.max(8, Math.min(anchorBottom + 8, vh - 200));
      setPos({ top, left, width, maxHeight: Math.max(200, vh - top - 16) });
    };
    const schedule = () => { if (!raf) raf = requestAnimationFrame(place); };
    place();
    // capture:true so an inner scrollport's (non-bubbling) scroll re-anchors too.
    window.addEventListener("scroll", schedule, { passive: true, capture: true });
    window.addEventListener("resize", schedule);
    return () => {
      window.removeEventListener("scroll", schedule, { capture: true });
      window.removeEventListener("resize", schedule);
      if (raf) cancelAnimationFrame(raf);
    };
  }, [anchorRef, sheet]);

  // Esc closes. On the sheet the page behind is frozen as well, so the scroll
  // gesture belongs to the sheet alone — the complaint that "scroll gets in the
  // way" on a phone was the page scrolling under an open filter panel.
  useEffect(() => {
    const onKey = (e) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", onKey);
    if (!sheet) return () => window.removeEventListener("keydown", onKey);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      window.removeEventListener("keydown", onKey);
      document.body.style.overflow = prev;
    };
  }, [onClose, sheet]);

  return createPortal(
    <>
      <div className={`market-cols-backdrop${sheet ? " is-sheet" : ""}`} onClick={onClose} />
      <div
        className={`market-cols-dropdown${sheet ? " market-cols-sheet" : ""}`}
        role="menu"
        style={sheet || !pos ? undefined : { top: pos.top, left: pos.left, width: pos.width, maxHeight: pos.maxHeight }}
      >
        {sheet && (
          <div className="market-cols-sheet-head">
            <span className="market-cols-sheet-grip" aria-hidden="true" />
            <span className="market-cols-sheet-title">{title}</span>
            <button type="button" className="market-cols-sheet-close" onClick={onClose} aria-label={closeLabel}>×</button>
          </div>
        )}
        {children}
      </div>
    </>,
    document.body
  );
}

// The board's column headers, pinned under the topbar while the rows scroll past.
// The real <thead> can't simply be `position: sticky`: its nearest scrollport is
// .market-table-wrap, which `overflow-x: auto` turns into a scroll container on
// BOTH axes, and that box never scrolls vertically — a sticky th would stay glued
// to the top of the table and ride the page up with it. So the header row is
// mirrored into a fixed bar: the SAME <th> elements (same sort and drag-reorder
// handlers), the column widths measured off the live table, and the wrap's own
// horizontal scroll offset, so the two read and behave as one header. Portaled to
// <body> for the same reason as MarketFloatScroll — the table's ancestors
// (.market-board overflow:hidden, .app-shell-wrap) would otherwise clip it.
function MarketStickyHead({ wrapRef, cells, colSignature, rowCount, loading }) {
  const scrollerRef = useRef(null);
  const [box, setBox] = useState({ show: false, left: 0, width: 0, top: 0, tableWidth: 0, cols: [] });
  const lastKey = useRef("");
  const measureRef = useRef(() => {});

  useEffect(() => {
    const wrap = wrapRef.current;
    if (!wrap) return undefined;
    let raf = 0;
    const hide = () => {
      if (lastKey.current === "hidden") return;
      lastKey.current = "hidden";
      setBox((b) => ({ ...b, show: false }));
    };
    // The bar mirrors the slice of the table the viewport actually shows, so its
    // own scroll offset is the table's scrollLeft plus whatever the wrap has run
    // off the left edge of the screen.
    const syncScroll = (el, wrapLeft) => {
      const sc = scrollerRef.current;
      if (sc) sc.scrollLeft = el.scrollLeft + (Math.max(wrapLeft, 0) - wrapLeft);
    };
    const measure = () => {
      raf = 0;
      const el = wrapRef.current;
      const table = el && el.querySelector(".market-table");
      const headRow = table && table.querySelector("thead tr");
      if (!el || !table || !headRow || loading || !rowCount) { hide(); return; }
      // Pin under the sticky topbar, whose height differs per breakpoint. The
      // filter bar above the table scrolls away with the page (by request), so
      // the topbar is the only thing this has to clear.
      // The bar is fixed inside the (possibly zoomed) root, so every measured
      // coordinate is divided into the CSS pixels it will be written back as —
      // see rootZoom(). The column WIDTHS go through the same division, or the
      // mirrored header's cells would be 1.5x their columns at a 150 % text size
      // and the labels would walk off their own columns to the right.
      const { zoom, vw } = zoomedViewport();
      const topbar = document.querySelector(".topbar");
      const pin = topbar
        ? Math.max(0, Math.round(topbar.getBoundingClientRect().bottom / zoom)) : 0;
      const headRect = headRow.getBoundingClientRect();
      const tableRect = table.getBoundingClientRect();
      const wrapRect = el.getBoundingClientRect();
      const left = Math.max(wrapRect.left / zoom, 0);
      const width = Math.min(wrapRect.right / zoom, vw) - left;
      // Only while the real header sits above the pin line and rows are still
      // under it — otherwise the bar would hang over a table that has scrolled by.
      if (headRect.bottom / zoom > pin + 1
          || tableRect.bottom / zoom < pin + headRect.height / zoom + 24
          || width < 60) { hide(); return; }
      // Half-pixel rounding: enough to keep the labels over their columns, coarse
      // enough that sub-pixel noise doesn't re-render the bar on every frame.
      const round = (v) => Math.round(v * 2) / 2;
      const cols = Array.from(headRow.children)
        .map((th) => round(th.getBoundingClientRect().width / zoom));
      const tableWidth = round(tableRect.width / zoom);
      const key = `${round(left)}|${round(width)}|${pin}|${tableWidth}|${cols.join(",")}`;
      syncScroll(el, wrapRect.left / zoom);
      if (key === lastKey.current) return;
      lastKey.current = key;
      setBox({ show: true, left, width, top: pin, tableWidth, cols });
    };
    measureRef.current = measure;
    const schedule = () => { if (!raf) raf = requestAnimationFrame(measure); };
    measure();
    // capture:true reaches window for the wrap's own (non-bubbling) horizontal scroll too.
    window.addEventListener("scroll", schedule, { passive: true, capture: true });
    window.addEventListener("resize", schedule);
    const ro = new ResizeObserver(schedule);
    ro.observe(wrap);
    wrap.addEventListener("scroll", schedule, { passive: true });
    return () => {
      measureRef.current = () => {};
      window.removeEventListener("scroll", schedule, { capture: true });
      window.removeEventListener("resize", schedule);
      wrap.removeEventListener("scroll", schedule);
      ro.disconnect();
      if (raf) cancelAnimationFrame(raf);
    };
  }, [wrapRef, colSignature, rowCount, loading]);

  // Column widths also move on things no observer reports — a sort caret, a
  // language switch, a font finishing its load. Re-measuring after every render
  // is cheap because `lastKey` swallows the no-op ones.
  useLayoutEffect(() => { measureRef.current(); });

  // A column CSS has hidden (mobile drops the company name) measures 0 wide.
  // It has to be left out of BOTH the colgroup and the row: a `display: none`
  // cell drops out of the row entirely under fixed table layout, so every
  // following header would shift one column to the left.
  const mirrored = box.cols
    .map((w, i) => ({ w, i }))
    .filter(({ w, i }) => w > 0 && cells[i]);

  // Nothing in the DOM until it is actually pinned — a second copy of the header
  // row hanging around would double every `.market-table thead` query.
  if (!box.show || !mirrored.length) return null;

  return createPortal(
    <div
      className="market-sticky-head"
      aria-hidden="true"
      style={{ left: box.left, width: box.width, top: box.top }}
    >
      <div className="market-sticky-head__scroller" ref={scrollerRef}>
        <table
          className="market-table market-sticky-head__table"
          style={{ width: box.tableWidth || undefined, minWidth: box.tableWidth || undefined }}
        >
          <colgroup>
            {mirrored.map(({ i, w }) => <col key={i} style={{ width: w }} />)}
          </colgroup>
          <thead>
            <tr>
              {mirrored.map(({ i }) => React.cloneElement(cells[i], {
                // The bar is aria-hidden (the real header is the one screen
                // readers and Tab travel through), so its copies stay unfocusable.
                tabIndex: -1,
              }))}
            </tr>
          </thead>
        </table>
      </div>
    </div>,
    document.body
  );
}

// ── A column's own controls ───────────────────────────────────────────────────
// Sort, move, freeze, hide — everything a reader does TO a column rather than
// with its numbers, in one strip under the header that opened it. The board is
// wider than any screen, and until now the only way to move a column was to drag
// its header: impossible with a thumb, and awkward when the destination is six
// columns off the right edge. These buttons say the same thing in one press.
//
// Portaled to <body>: a <th> is a table cell, and a popover inside one is both
// clipped by the wrap's overflow and duplicated into the mirrored sticky header.
// It re-finds its own header every frame instead of remembering a rectangle, so
// it follows the column it belongs to when a move actually moves it.
function MarketColMenu({ colKey, fromSticky, lang, state, actions, onClose }) {
  const ref = useRef(null);
  const [pos, setPos] = useState(null);
  const placeRef = useRef(() => {});

  useLayoutEffect(() => {
    let raf = 0;
    const place = () => {
      raf = 0;
      const scope = fromSticky ? ".market-sticky-head" : ".market-table-wrap";
      const sel = `.market-table thead th[data-sort-key="${colKey}"]`;
      const th = document.querySelector(`${scope} ${sel}`) || document.querySelector(`.market-table-wrap ${sel}`);
      // The header went away — the column was hidden, the view switched, or the
      // page scrolled it off. A toolbar for a column nobody can see is noise.
      if (!th) { onClose(); return; }
      const r = th.getBoundingClientRect();
      // CSS pixels of the zoomed root, as everywhere a fixed overlay is placed
      // from a measured rectangle — see rootZoom().
      const { zoom, vw, vh } = zoomedViewport();
      const thLeft = r.left / zoom, thBottom = r.bottom / zoom, thTop = r.top / zoom;
      if (thBottom < 0 || thTop > vh) { onClose(); return; }
      const w = (ref.current && ref.current.offsetWidth) || 300;
      const left = Math.round(Math.max(8, Math.min(thLeft, vw - w - 8)));
      const top = Math.round(thBottom + 6);
      // Re-placed after every render, so a position that did not change must not
      // reach state: a fresh object each time is an infinite render loop.
      setPos((prev) => (prev && prev.top === top && prev.left === left ? prev : { top, left }));
    };
    placeRef.current = place;
    const schedule = () => { if (!raf) raf = requestAnimationFrame(place); };
    place();
    // capture:true so the wrap's own (non-bubbling) horizontal scroll re-anchors too.
    window.addEventListener("scroll", schedule, { passive: true, capture: true });
    window.addEventListener("resize", schedule);
    return () => {
      placeRef.current = () => {};
      window.removeEventListener("scroll", schedule, { capture: true });
      window.removeEventListener("resize", schedule);
      if (raf) cancelAnimationFrame(raf);
    };
  }, [colKey, fromSticky, onClose]);

  // A move re-lays the header row out without any scroll or resize to observe.
  useLayoutEffect(() => { placeRef.current(); });

  useEffect(() => {
    const onKey = (e) => { if (e.key === "Escape") onClose(); };
    const onDown = (e) => { if (ref.current && !ref.current.contains(e.target)) onClose(); };
    window.addEventListener("keydown", onKey);
    window.addEventListener("pointerdown", onDown, true);
    return () => {
      window.removeEventListener("keydown", onKey);
      window.removeEventListener("pointerdown", onDown, true);
    };
  }, [onClose]);

  const L = {
    asc: lang === "en" ? "Sort ascending" : lang === "uz" ? "O'sish bo'yicha saralash" : "Сортировать по возрастанию",
    desc: lang === "en" ? "Sort descending" : lang === "uz" ? "Kamayish bo'yicha saralash" : "Сортировать по убыванию",
    start: lang === "en" ? "Move to start" : lang === "uz" ? "Boshiga ko'chirish" : "Переместить в начало",
    left: lang === "en" ? "Move left" : lang === "uz" ? "Chapga ko'chirish" : "Переместить влево",
    right: lang === "en" ? "Move right" : lang === "uz" ? "O'ngga ko'chirish" : "Переместить вправо",
    end: lang === "en" ? "Move to end" : lang === "uz" ? "Oxiriga ko'chirish" : "Переместить в конец",
    pin: lang === "en" ? "Freeze column" : lang === "uz" ? "Ustunni mahkamlash" : "Закрепить столбец",
    unpin: lang === "en" ? "Unfreeze column" : lang === "uz" ? "Mahkamlashni bekor qilish" : "Открепить столбец",
    hide: lang === "en" ? "Hide column" : lang === "uz" ? "Ustunni yashirish" : "Скрыть столбец",
    hideLocked: lang === "en" ? "The price column always stays"
      : lang === "uz" ? "Narx ustuni doim qoladi" : "Столбец с ценой всегда остаётся",
    menu: lang === "en" ? "Column controls" : lang === "uz" ? "Ustun boshqaruvi" : "Управление столбцом",
  };

  const Btn = ({ label, onClick, disabled, active, danger, children }) => (
    <button
      type="button"
      className={`market-colmenu-btn${active ? " is-active" : ""}${danger ? " is-danger" : ""}`}
      title={label}
      aria-label={label}
      disabled={disabled}
      onClick={onClick}
    >
      {children}
    </button>
  );
  // 16px stroke glyphs, drawn inline: an icon font is one more thing to load for
  // eight marks, and the board already pays for its fonts.
  const Svg = ({ children }) => (
    <svg viewBox="0 0 16 16" width="15" height="15" fill="none" stroke="currentColor"
      strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      {children}
    </svg>
  );

  return createPortal(
    <div
      ref={ref}
      className="market-colmenu"
      role="toolbar"
      aria-label={L.menu}
      style={pos ? { top: pos.top, left: pos.left } : { top: -9999, left: -9999 }}
      onPointerDown={(e) => e.stopPropagation()}
    >
      <Btn label={L.asc} active={state.dir === "asc"} onClick={() => actions.sort("asc")}>
        <Svg><path d="M3 4h4" /><path d="M3 8h7" /><path d="M3 12h10" /></Svg>
      </Btn>
      <Btn label={L.desc} active={state.dir === "desc"} onClick={() => actions.sort("desc")}>
        <Svg><path d="M3 4h10" /><path d="M3 8h7" /><path d="M3 12h4" /></Svg>
      </Btn>
      <span className="market-colmenu-sep" aria-hidden="true" />
      <Btn label={L.start} disabled={!state.canLeft} onClick={() => actions.move("start")}>
        <Svg><path d="M3 3v10" /><path d="M14 8H6.5" /><path d="M9.5 5 6.5 8l3 3" /></Svg>
      </Btn>
      <Btn label={L.left} disabled={!state.canLeft} onClick={() => actions.move(-1)}>
        <Svg><path d="M13 8H4" /><path d="M7 5 4 8l3 3" /></Svg>
      </Btn>
      <Btn label={L.right} disabled={!state.canRight} onClick={() => actions.move(1)}>
        <Svg><path d="M3 8h9" /><path d="M9 5l3 3-3 3" /></Svg>
      </Btn>
      <Btn label={L.end} disabled={!state.canRight} onClick={() => actions.move("end")}>
        <Svg><path d="M13 3v10" /><path d="M2 8h7.5" /><path d="M6.5 5l3 3-3 3" /></Svg>
      </Btn>
      <span className="market-colmenu-sep" aria-hidden="true" />
      <Btn label={state.pinned ? L.unpin : L.pin} active={state.pinned} onClick={actions.pin}>
        <Svg><path d="M6 2h4l-.6 3.4 2.1 2.1H4.5l2.1-2.1z" /><path d="M8 7.5V14" /></Svg>
      </Btn>
      <Btn label={state.canHide ? L.hide : L.hideLocked} disabled={!state.canHide} danger onClick={actions.hide}>
        <Svg><path d="M3 4.5h10" /><path d="M6.5 4.5V3h3v1.5" /><path d="M4.5 4.5 5 13.5h6l.5-9" /></Svg>
      </Btn>
    </div>,
    document.body
  );
}

// ЛЕНТА СОБЫТИЙ ПО БУМАГАМ. /api/news has served a dated timeline of real market
// events — filings, listings, delistings — since the §3.2 work, and no page ever
// read it: it was built and left invisible while the News section grew out of the
// separate editorial module. This is that timeline.
//
// It lives on the «Корпоративные» tab of the news section (it stood under the
// board until 2026-08-20): a filing IS corporate news, and that is the page a
// reader looking for one opens.
//
// Every row is dated by the ISSUER's own publication date and OPENS the
// document, so it is a way INTO the filing rather than a note that one exists.
function MarketEventsFeed({ lang, onOpenCompany }) {
  const t = (ru, uz, en) => (lang === "uz" ? uz : lang === "en" ? en : ru);
  const [items, setItems] = React.useState(null);
  const [kind, setKind] = React.useState("all");
  const [expanded, setExpanded] = React.useState(false);
  const [detail, setDetail] = React.useState(null);

  React.useEffect(() => {
    let alive = true;
    fetch("/api/news?limit=120&days=365")
      .then((r) => r.json())
      .then((d) => { if (alive) setItems(d && d.ok ? (d.items || []) : []); })
      .catch(() => { if (alive) setItems([]); });
    return () => { alive = false; };
  }, []);

  if (items === null) return null;

  const KINDS = [
    ["all", t("Все", "Barchasi", "All")],
    ["report", t("Отчётность", "Hisobot", "Filings")],
    ["listing", t("Листинги", "Listinglar", "Listings")],
    ["delisting", t("Делистинг", "Delisting", "Delisting")],
  ];
  const counts = items.reduce((acc, i) => ({ ...acc, [i.type]: (acc[i.type] || 0) + 1 }), {});
  const shown = kind === "all" ? items : items.filter((i) => i.type === kind);
  if (items.length === 0) return null;
  const visible = expanded ? shown.slice(0, 120) : shown.slice(0, 12);

  const day = (d) => {
    const s = String(d || "").slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return "";
    const [y, m, dd] = s.split("-");
    return `${dd}.${m}.${y}`;
  };
  // The period a filing covers, said the way the reader asked for it elsewhere on
  // the site: «2025 · год» / «2026 · II кв.».
  const period = (i) => {
    if (!i.year) return "";
    if (i.quarter) {
      const roman = ["", "I", "II", "III", "IV"][i.quarter] || i.quarter;
      return `${i.year} · ${roman} ${t("кв.", "chorak", "Q")}`;
    }
    return `${i.year} · ${t("год", "yil", "FY")}`;
  };
  // The row opens the event ON THIS SITE. It used to hand the reader straight to
  // openinfo's PDF — the source is the source, but a click on a row in OUR
  // timeline should first say what the event is in our own terms: who filed it,
  // for which period, and what that filing put into our database. The document
  // stays one click away, from the row and from the detail alike.
  const openHint = () => t("Подробнее о событии", "Hodisa haqida batafsil", "Event details");

  // The filing's form, in the reader's language — the headline and the event's
  // own detail must not disagree over whether it is «НСБУ» or «NSBU».
  const formLabel = (raw) => (raw === "NSBU" ? t("НСБУ", "NSBU", "NAS")
    : raw === "MSFO" ? t("МСФО", "MSFO", "IFRS")
    : raw === "Audition" ? t("Аудит", "Audit", "Audit") : raw);
  const headline = (i) => {
    if (i.type === "report") {
      return `${t("Опубликована отчётность", "Hisobot e'lon qilindi", "Filing published")} · ${formLabel(i.report_form)}`;
    }
    if (i.type === "listing") return t("Допуск к торгам", "Savdoga qo'yildi", "Admitted to trading");
    return t("Нет сделок более 60 дней", "60 kundan ortiq bitimsiz", "No trades for over 60 days");
  };

  return (
    <article className="panel market-events">
      <div className="market-events-head">
        <div>
          <div className="panel-label">{t("Биржевые события", "Birja hodisalari", "Market events")}</div>
          <h2>{t("Лента событий по бумагам", "Qog'ozlar bo'yicha hodisalar lentasi", "Securities events feed")}</h2>
        </div>
        <div className="market-events-kinds">
          {KINDS.map(([k, label]) => (
            <button key={k} type="button"
              className={`sector-chip${kind === k ? " active" : ""}`}
              aria-pressed={kind === k}
              onClick={() => { setKind(k); setExpanded(false); }}>
              {label}
              {k !== "all" && counts[k] ? ` (${counts[k]})` : ""}
            </button>
          ))}
        </div>
      </div>
      <ul className="market-events-list">
        {visible.map((i, index) => (
          <li key={`${i.type}-${i.ticker}-${i.date}-${i.year || ""}-${i.quarter || ""}-${index}`}
            className={`market-events-row ev-${i.type} is-openable`}
            role="link"
            tabIndex={0}
            title={openHint()}
            onClick={() => setDetail(i)}
            onKeyDown={(e) => {
              if (e.key === "Enter" || e.key === " ") { e.preventDefault(); setDetail(i); }
            }}>
            <time className="ev-date">{day(i.date)}</time>
            <button type="button" className="ev-ticker"
              onClick={(e) => { e.stopPropagation(); if (onOpenCompany) onOpenCompany(i.ticker); }}>{i.ticker}</button>
            <span className="ev-what">
              <span className="ev-headline">{headline(i)}</span>
              {period(i) ? <span className="ev-period">{period(i)}</span> : null}
              <span className="ev-company">{i.company}</span>
            </span>
            {/* The document, where the source published one. NSBU quarterlies carry
                both forms in one workbook, so one link is the whole filing. */}
            <span className="ev-links" onClick={(e) => e.stopPropagation()}>
              {i.pdf_url && (
                <a href={i.pdf_url} target="_blank" rel="noopener noreferrer">PDF</a>
              )}
              {i.excel_url && (
                <a href={i.excel_url} target="_blank" rel="noopener noreferrer">XLS</a>
              )}
            </span>
          </li>
        ))}
      </ul>
      {shown.length > visible.length && (
        <button type="button" className="market-events-more" onClick={() => setExpanded(true)}>
          {t(`Показать все ${shown.length}`, `Barchasini ko'rsatish (${shown.length})`,
             `Show all ${shown.length}`)}
        </button>
      )}
      <p className="fin-note muted">
        {t("События по данным биржи и openinfo.uz. Дата — дата публикации эмитентом, не дата нашей загрузки.",
           "Hodisalar birja va openinfo.uz ma'lumotlari bo'yicha. Sana — emitent e'lon qilgan sana.",
           "Events from the exchange and openinfo.uz. The date is the issuer's publication date, not the date we ingested it.")}
      </p>
      {detail && (
        <MarketEventDetail
          item={detail}
          lang={lang}
          headline={headline(detail)}
          period={period(detail)}
          day={day(detail.date)}
          form={formLabel(detail.report_form)}
          onClose={() => setDetail(null)}
          onOpenCompany={onOpenCompany}
        />
      )}
    </article>
  );
}


// The lines a filing puts on the page, in the order the Финансы tab reads them:
// what came in, what was left of it, and what the balance says at the period's end.
const EVENT_DETAIL_ROWS = [
  "net_revenue", "gross_profit", "operating_income", "net_profit",
  "total_assets", "total_liabilities", "total_equity",
];

// ОДНО СОБЫТИЕ, НА НАШЕЙ СТОРОНЕ. A dialog rather than a route: an event has no
// id of its own — it is identified by issuer, kind and period together — so
// there is no honest URL to give it, and the reader keeps their place in the
// timeline.
//
// For a filing it answers the question the row raises: the period stated in
// full, and the figures THIS period holds in our database, read from the same
// series the Финансы tab draws. The source documents are offered at the bottom,
// named as sources — which is what they are.
function MarketEventDetail({ item, lang, headline, period, day, form, onClose, onOpenCompany }) {
  const t = (ru, uz, en) => (lang === "uz" ? uz : lang === "en" ? en : ru);
  const isReport = item.type === "report";
  const quarterly = !!item.quarter;
  const periodKey = item.year ? (quarterly ? `${item.year}Q${item.quarter}` : String(item.year)) : "";
  const [fin, setFin] = React.useState(null);

  React.useEffect(() => {
    if (!isReport || !item.ticker || !periodKey) { setFin({}); return undefined; }
    let alive = true;
    setFin(null);
    fetch(`/api/company/${encodeURIComponent(item.ticker)}/financials`
          + `?freq=${quarterly ? "quarterly" : "annual"}`)
      .then((r) => r.json())
      .then((d) => { if (alive) setFin(d && d.ok ? d : {}); })
      .catch(() => { if (alive) setFin({}); });
    return () => { alive = false; };
  }, [isReport, item.ticker, periodKey, quarterly]);

  React.useEffect(() => {
    const onKey = (e) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  const series = (fin && fin.series) || {};
  const figures = EVENT_DETAIL_ROWS
    .map((field) => {
      const s = series[field];
      const v = s && s.values ? s.values[periodKey] : undefined;
      return Number.isFinite(Number(v)) ? { field, value: Number(v), money: !!s.money } : null;
    })
    .filter(Boolean);

  const classLabel = (raw) => {
    const key = String(raw || "").toLowerCase();
    if (!key) return null;
    if (key === "bond") return t("Облигация", "Obligatsiya", "Bond");
    if (key.startsWith("prefer") || key.startsWith("imtiyoz")) {
      return t("Привилегированная акция", "Imtiyozli aksiya", "Preferred share");
    }
    if (key === "ordinary") return t("Обыкновенная акция", "Oddiy aksiya", "Ordinary share");
    return raw;
  };

  const kindLabel = item.type === "report"
    ? t("Отчётность", "Hisobot", "Filing")
    : item.type === "listing"
      ? t("Листинг", "Listing", "Listing")
      : t("Делистинг", "Delisting", "Delisting");

  const line = (label, value) => (value == null || value === "" ? null : (
    <div className="ev-detail-line">
      <span className="ev-detail-k">{label}</span>
      <span className="ev-detail-v">{value}</span>
    </div>
  ));

  return createPortal(
    <div className="ev-detail-backdrop" role="presentation" onClick={onClose}>
      <article className={`ev-detail ev-${item.type}`} role="dialog" aria-modal="true"
        aria-label={`${item.ticker} — ${headline}`}
        onClick={(e) => e.stopPropagation()}>
        <button type="button" className="ev-detail-close" onClick={onClose}
          aria-label={t("Закрыть", "Yopish", "Close")}>×</button>

        <div className="ev-detail-head">
          {/* The kind alone: the date is stated below, under the label that says
              WHOSE date it is — the issuer's, not our ingestion clock. */}
          <span className={`ev-detail-kind ev-${item.type}`}>{kindLabel}</span>
        </div>
        <h3 className="ev-detail-title">{headline}</h3>
        <button type="button" className="ev-detail-issuer"
          onClick={() => { if (onOpenCompany) onOpenCompany(item.ticker); onClose(); }}>
          <b>{item.ticker}</b>
          <span>{item.company}</span>
        </button>

        <div className="ev-detail-facts">
          {line(t("Период", "Davr", "Period"), period || null)}
          {line(t("Форма", "Shakl", "Form"), isReport ? (form || item.report_form) : null)}
          {line(item.type === "delisting"
                  ? t("Последняя сделка", "Oxirgi bitim", "Last trade")
                  : item.type === "listing"
                    ? t("Допуск к торгам", "Savdoga qo'yilgan", "Admitted to trading")
                    : t("Опубликовано эмитентом", "Emitent e'lon qilgan", "Published by the issuer"),
                day)}
          {line(t("Класс бумаги", "Qog'oz sinfi", "Share class"), classLabel(item.share_type))}
          {line(t("Капитализация при допуске", "Listingdagi kapitallashuv", "Cap at admission"),
                Number.isFinite(Number(item.market_cap))
                  ? formatCompactVolume(item.market_cap, lang) : null)}
        </div>

        {isReport && (
          <div className="ev-detail-fin">
            <h4>{t("Что этот отчёт даёт по периоду", "Bu hisobot davr bo'yicha nima beradi",
                   "What this filing holds for the period")}</h4>
            {fin === null ? (
              <p className="muted">{t("Загрузка…", "Yuklanmoqda…", "Loading…")}</p>
            ) : figures.length ? (
              <table className="ev-detail-table">
                <tbody>
                  {figures.map((f) => (
                    <tr key={f.field}>
                      <th scope="row">{finLabel(f.field, lang)}</th>
                      <td title={formatMarketNumber(f.value, lang, 0)}>
                        {f.money ? formatCompactVolume(f.value, lang)
                                 : formatRatio(f.value, 2, lang)}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            ) : (
              // Said plainly rather than shown as an empty table: the filing is
              // real, the parse of THIS period simply has not reached us yet.
              <p className="muted">
                {t("Показатели за этот период у нас пока не разобраны — откройте документ или страницу компании.",
                   "Bu davr ko'rsatkichlari hali tahlil qilinmagan — hujjatni yoki kompaniya sahifasini oching.",
                   "The figures for this period are not parsed on our side yet — open the document or the company page.")}
              </p>
            )}
          </div>
        )}

        <div className="ev-detail-actions">
          <button type="button" className="ev-detail-primary"
            onClick={() => { if (onOpenCompany) onOpenCompany(item.ticker); onClose(); }}>
            {t("Страница компании", "Kompaniya sahifasi", "Company page")}
          </button>
          {(item.pdf_url || item.excel_url) && (
            <span className="ev-detail-src">
              <span className="muted">{t("Источник — openinfo.uz:", "Manba — openinfo.uz:", "Source — openinfo.uz:")}</span>
              {item.pdf_url && <a href={item.pdf_url} target="_blank" rel="noopener noreferrer">PDF</a>}
              {item.excel_url && <a href={item.excel_url} target="_blank" rel="noopener noreferrer">XLS</a>}
            </span>
          )}
        </div>
      </article>
    </div>,
    document.body
  );
}

// The periods the board can measure a change over. `1d` is the session — it comes
// off the live board row, not the stored history, because that is the number the
// exchange itself publishes today; the rest are windows over the settled closes
// (/api/market/changes, MARKET_CHANGE_WINDOWS on the server side).
const CHANGE_PERIODS = [
  { code: "1d", label: ["За сессию", "Sessiya", "Session"], short: ["сессия", "sessiya", "session"] },
  { code: "1w", label: ["1Н", "1H", "1W"], short: ["нед.", "hafta", "wk"] },
  { code: "1m", label: ["1М", "1O", "1M"], short: ["мес.", "oy", "mo"] },
  { code: "3m", label: ["3М", "3O", "3M"], short: ["3 мес.", "3 oy", "3mo"] },
  { code: "6m", label: ["6М", "6O", "6M"], short: ["6 мес.", "6 oy", "6mo"] },
  { code: "1y", label: ["1Г", "1Y", "1Y"], short: ["год", "yil", "yr"] },
  { code: "ytd", label: ["С начала года", "Yil boshidan", "YTD"], short: ["с 1 янв.", "1-yanv.dan", "YTD"] },
];
const CHANGE_PERIOD_KEY = "uz_market_change_period";
const changePeriodLabel = (code, lang, field = "label") => {
  const found = CHANGE_PERIODS.find((p) => p.code === code) || CHANGE_PERIODS[0];
  const i = lang === "uz" ? 1 : lang === "en" ? 2 : 0;
  return found[field][i];
};

function MarketView({
  rows,
  meta,
  loading,
  message,
  query,
  onQueryChange,
  type,
  onTypeChange,
  onRefresh,
  onAnalyze,
  onOpenCompany,
  onOpenBond,
  onOpenBankFx,
  language,
  companies,
  securitiesMap,
  financials,
  tradeStats,
  favoriteTickers,
  onToggleFavorite,
  viewMode: viewModeProp,
  onViewModeChange,
  isAdmin = false,
}) {
  const lang = normalizeLanguage(language);
  // viewMode is driven by the route (table = /market, heatmap = /heatmap).
  const viewMode = viewModeProp || "table";
  const setViewMode = onViewModeChange || (() => {});
  const [marketSector, setMarketSector] = useState(null);
  const [favOnly, setFavOnly] = useState(false);
  const [panelTicker, setPanelTicker] = useState(null);
  const [panelWiki, setPanelWiki] = useState(null);
  const [panelWikiLoading, setPanelWikiLoading] = useState(false);
  const hasFav = (t) => !!favoriteTickers && favoriteTickers.has(String(t || "").trim().toUpperCase());

  // Per-ticker financial ratios & equity (facts store) for P/E, P/B and the
  // §3.8 ratio-coefficient columns. Fetched once; keyed by ticker.
  const [ratios, setRatios] = useState({});
  useEffect(() => {
    let alive = true;
    fetch("/api/market/ratios")
      .then((r) => r.json())
      .then((d) => { if (alive && d && d.ok) setRatios(d.ratios || {}); })
      .catch(() => {});
    return () => { alive = false; };
  }, []);

  // Price change over a WEEK, a MONTH, a quarter, half a year, a year and
  // year-to-date, per security, off the same stored closes the charts draw
  // (/api/market/changes). The board measured one period — the session — so
  // «сколько он сделал за месяц?» meant opening every company page in turn.
  //
  // The period is the reader's choice and it travels: the «Изменение» column,
  // the movers strip on this page and the board preview on the landing page all
  // follow it, because three answers to one question on one screen is worse than
  // none. The explicit «Изм. 1Н» and «Изм. 1М» columns never move — a reader
  // comparing the week against the month needs both at once.
  const [changes, setChanges] = useState({});
  useEffect(() => {
    let alive = true;
    fetch("/api/market/changes")
      .then((r) => r.json())
      .then((d) => { if (alive && d && d.ok) setChanges(d.changes || {}); })
      .catch(() => {});
    return () => { alive = false; };
  }, []);
  // Which of the exchange's two boards is on screen. Not persisted: MAIN is the
  // market, NEGO is a handful of deals on a given day, and a reader who returns
  // tomorrow to a five-row board they do not remember choosing would read it as
  // the market having collapsed.
  const [segment, setSegment] = useState("main");
  const [changePeriod, setChangePeriod] = useState(() => {
    try {
      const saved = localStorage.getItem(CHANGE_PERIOD_KEY);
      if (CHANGE_PERIODS.some((p) => p.code === saved)) return saved;
    } catch (e) { /* ignore */ }
    return "1d";
  });
  useEffect(() => {
    try { localStorage.setItem(CHANGE_PERIOD_KEY, changePeriod); } catch (e) { /* ignore */ }
  }, [changePeriod]);
  // One security's change over one period, as {pct, from} or null. The session
  // keeps its own rule — a security that did not trade today has NO change to
  // report (ТЗ §2.4), which is a different statement from a flat one — while a
  // window is answered by the stored closes or not at all.
  const changeOver = (ticker, code) => {
    if (code === "1d") return null;
    const hit = (changes[String(ticker || "").toUpperCase()] || {})[code];
    return hit && Number.isFinite(hit.pct) ? hit : null;
  };
  // The same window's TURNOVER, as {value, sessions, from} — the sum of what the
  // security changed hands for over it. Kept separate from the change because a
  // line can have traded over a month without having a close a month back to
  // measure from (its history starts inside the window), and the liquidity panel
  // must still be able to rank it.
  const turnoverOver = (ticker, code) => {
    if (code === "1d") return null;
    const hit = ((changes[String(ticker || "").toUpperCase()] || {}).turnover || {})[code];
    return hit && Number.isFinite(hit.value) ? hit : null;
  };
  // Everything ELSE the window did, on the same footing as a session: its
  // opening price, its high and low, the сумы and the bumagi that changed hands,
  // the average share price, the average deal and the biggest one.
  //
  // Customer, 19.08.2026: «когда я выбираю период — например за год — должны
  // МЕНЯТЬСЯ цифры: открытие, макс, мин, объём в сумах/шт, ср. цена акции,
  // ср. сумма сделки, крупнейшая сделка, объёмы %, капитализация, объём торгов,
  // рост, снижение — а не только показывать их изменение». Until now the board
  // could restate two of them (the percent and the turnover) and reprinted the
  // SESSION's figures under every other heading, so a row read «за год» beside
  // this morning's high and low.
  const statsOver = (ticker, code) => {
    if (code === "1d") return null;
    const hit = ((changes[String(ticker || "").toUpperCase()] || {}).stats || {})[code];
    return hit || null;
  };

  // «Номинальная стоимость» of the security, off the exchange's own card via the
  // listing registry (`parval`), joined onto the board row by the server. A zero
  // par is the card saying "not stated" and the collector lands that as absent —
  // so any number here is a filed one, and a dash is the source's silence rather
  // than a rounding of nothing.
  const parOf = (row) => {
    const par = Number(row?.nominal);
    return Number.isFinite(par) && par > 0 ? par : null;
  };
  // What the market pays per sum of par. For a bond this is the конвенция the
  // whole market quotes in (a price is a percentage of par); for a share it is
  // the plainest possible statement of how far the price has left its issue
  // value behind. Shown as a multiple, not a percent, because on this market the
  // numbers run from 0.3x to 60x and a percent column of «5 800 %» reads as an
  // error.
  const priceToPar = (row) => {
    const par = parOf(row);
    const price = marketDisplayPrice(row);
    return par && Number.isFinite(price) && price > 0 ? price / par : null;
  };

  // Multiples come from the server, computed per ISSUER (ТЗ §8). Keyed by
  // ticker, but both classes of an issuer carry the same object — that is the
  // point: the board used to divide ONE class's capitalisation by the WHOLE
  // issuer's profit, so no pair of classes could agree. A statement that failed
  // validation arrives with its multiples already suppressed and the reason
  // attached, so nothing here has to decide what is publishable.
  const [multiples, setMultiples] = useState({});
  const [marketSummary, setMarketSummary] = useState(null);
  const [mapData, setMapData] = useState(null);
  const [instruments, setInstruments] = useState({});
  // ТЗ §4: dormant listings are hidden by default and reachable by a switch —
  // not dropped, because a security that stopped trading is a fact about the
  // market and hiding it permanently is how five references came to disagree.
  //
  // The switch is a FILTER, not an "include" checkbox. It is named «Неактивные»
  // and sits beside «Избранное», which shows favourites and only favourites —
  // so pressing it and getting the whole board back with eleven more rows
  // buried in it read as a broken button. Now it lands the reader on the
  // eleven, which is the question the chip's name asks.
  const [inactiveOnly, setInactiveOnly] = useState(false);
  useEffect(() => {
    let alive = true;
    fetch("/api/market/multiples")
      .then((r) => r.json())
      .then((d) => {
        if (!alive || !d || !d.ok) return;
        const byTicker = {};
        (d.items || []).forEach((it) => { byTicker[it.ticker] = it; });
        setMultiples(byTicker);
      })
      .catch(() => {});
    fetch("/api/market/summary")
      .then((r) => r.json())
      .then((d) => { if (alive && d && d.ok) setMarketSummary(d); })
      .catch(() => {});
    // The market map in ONE request (ТЗ §9): tiles, sector aggregates and the
    // counts behind them. It used to be stitched together on the client from
    // endpoints with different instrument universes.
    fetch("/api/heatmap")
      .then((r) => r.json())
      .then((d) => { if (alive && d && d.ok) setMapData(d); })
      .catch(() => {});
    // The single instrument universe (ТЗ §4). `is_active` here follows TRADING —
    // ninety days without an execution — rather than a registry flag, which is
    // what the "показать неактивные" switch below actually filters on.
    fetch("/api/instruments")
      .then((r) => r.json())
      .then((d) => {
        if (!alive || !d || !d.ok) return;
        const by = {};
        (d.items || []).forEach((i) => { by[i.ticker] = i; });
        setInstruments(by);
      })
      .catch(() => {});
    return () => { alive = false; };
  }, []);

  // Column sorting, as an ORDERED chain of keys. An empty chain falls back to the
  // default (date desc, then |change|) — which is itself two-level, and used to be
  // the only two-level order the board could express: one click on any header threw
  // it away. "Latest session first, biggest turnover within the day" is the question
  // the board is actually read with, and it needs two columns to ask.
  //
  // Plain click collapses back to a single key (the old behaviour, unchanged).
  // Shift/⌘/Ctrl-click appends: first press adds the column, second flips its
  // direction, third drops it out of the chain again.
  const [sortKeys, setSortKeys] = useState([]);
  // Text columns read best ascending, numeric/date columns descending.
  const defaultSortDir = (key) => (["ticker", "company"].includes(key) ? "asc" : "desc");
  const sortRankOf = (key) => sortKeys.findIndex((s) => s.key === key);
  const sortDirOf = (key) => sortKeys.find((s) => s.key === key)?.dir || null;
  const onSort = (key, additive = false) => {
    setSortKeys((prev) => {
      const i = prev.findIndex((s) => s.key === key);
      if (!additive) {
        // Re-clicking the only active key flips it; anything else starts over.
        if (prev.length === 1 && i === 0) return [{ key, dir: prev[0].dir === "asc" ? "desc" : "asc" }];
        return [{ key, dir: defaultSortDir(key) }];
      }
      if (i < 0) return [...prev, { key, dir: defaultSortDir(key) }];
      const next = [...prev];
      if (next[i].dir === defaultSortDir(key)) {
        next[i] = { key, dir: next[i].dir === "asc" ? "desc" : "asc" };
        return next;
      }
      next.splice(i, 1);
      return next;
    });
  };
  const clearSort = () => setSortKeys([]);
  // A phone has no Shift key, and the board stays a table there. Long-press on a
  // header is the touch equivalent of the modifier: it appends instead of replacing.
  const longPress = useRef({ timer: null, fired: false });
  const startLongPress = (key) => {
    longPress.current.fired = false;
    clearTimeout(longPress.current.timer);
    longPress.current.timer = setTimeout(() => {
      longPress.current.fired = true;
      onSort(key, true);
    }, 500);
  };
  const cancelLongPress = () => clearTimeout(longPress.current.timer);
  useEffect(() => () => clearTimeout(longPress.current.timer), []);
  // A modifier nobody is told about is a feature nobody has. The hint appears the
  // moment it becomes actionable — right after the first column is sorted, not on
  // a cold page where it would be noise — and retires for good once the reader has
  // either built a two-key order or dismissed it.
  const [sortHintSeen, setSortHintSeen] = useState(() => {
    try { return localStorage.getItem("uz_market_sort_hint") === "seen"; } catch (e) { return false; }
  });
  const dismissSortHint = () => {
    setSortHintSeen(true);
    try { localStorage.setItem("uz_market_sort_hint", "seen"); } catch (e) { /* ignore */ }
  };
  useEffect(() => {
    if (sortKeys.length > 1 && !sortHintSeen) dismissSortHint();
  }, [sortKeys.length, sortHintSeen]); // eslint-disable-line react-hooks/exhaustive-deps
  // Touch has no Shift key, so the hint must name the gesture that device HAS.
  const coarsePointer = typeof window !== "undefined" && typeof window.matchMedia === "function"
    && window.matchMedia("(pointer: coarse)").matches;

  // User-configurable quote columns (ticker/company/last are always shown).
  // Quote columns grouped into collapsible sections in the settings dropdown.
  // Each section is a sibling of "AI screener overview" (not nested under it).
  const COL_GROUPS = [
    { key: "overview", title: mt(lang, "grpOverview"), cols: [
      // «Изм.» follows the period selector; these two never do. A reader who is
      // comparing the week against the month needs both on screen at once, and a
      // column whose meaning depends on a control elsewhere cannot be that.
      ["change", `${mt(lang, "change")} (${changePeriodLabel(changePeriod, lang, "short")})`],
      ["change1w", `${mt(lang, "change")} 1${lang === "en" ? "W" : lang === "uz" ? "H" : "Н"}`],
      ["change1m", `${mt(lang, "change")} 1${lang === "en" ? "M" : lang === "uz" ? "O" : "М"}`],
      // «Номинальная стоимость» and what the market pays for it. The par is a
      // registry fact about the security; the ratio beside it is the reading a
      // par is FOR — a share trading at eighteen times its par and one trading
      // below it are two different propositions.
      ["nominal", mt(lang, "nominalCol")],
      ["priceToPar", mt(lang, "nominalToPrice")],
      ["open", mt(lang, "open")],
      ["high", mt(lang, "high")],
      ["low", mt(lang, "low")],
      ["date", mt(lang, "date")],
      ["source", mt(lang, "source")],
    ] },
    { key: "volumes", title: mt(lang, "grpVolumes"), cols: [
      ["volume", mt(lang, "volumeCol")],
      ["volQty", mt(lang, "volQty")],
      ["avgShare", mt(lang, "avgSharePrice")],
      ["avgTrade", mt(lang, "avgTradePrice")],
      ["bigTrade", mt(lang, "bigTrade")],
      ["volShare", mt(lang, "volShare")],
    ] },
    { key: "financials", title: mt(lang, "grpFinancials"), cols: [
      ["finRevenue", mt(lang, "finRevenue")],
      ["finGross", mt(lang, "finGross")],
      ["finCash", mt(lang, "finCash")],
      ["finLiab", mt(lang, "finLiab")],
      ["finNet", mt(lang, "finNet")],
      ["finOperating", mt(lang, "finOperating")],
    ] },
    // Долг/Капитал удалён по ТЗ мультипликаторов (лист 06): 47 из 99 значений
    // не воспроизводились, единицы были смешаны. Его роль делят P/S
    // (нефинансовый сектор) и Капитал/Активы (в первую очередь банки).
    { key: "multiples", title: mt(lang, "grpMultiples"), cols: [
      ["mktCap", mt(lang, "mktCap")],
      ["pe", "P/E"],
      ["pb", "P/B"],
      ["ps", "P/S"],
      ["roe", "ROE"],
      ["roa", "ROA"],
      ["netMargin", mt(lang, "netMargin")],
      ["eqAssets", mt(lang, "equityAssets")],
    ] },
    // The ratio rows of the company page's «Коэффициенты» card, on the board —
    // the same numbers from the same indicator filings, so a reader who
    // compares two issuers does not have to open two pages to do it. Published
    // as the issuer published them (Долг/Активы in percent, the rest bare
    // coefficients), with the year each one belongs to under the figure.
    { key: "coefficients", title: mt(lang, "grpRatios"), cols: [
      ["currentRatio", mt(lang, "currentRatio")],
      ["quickRatio", mt(lang, "quickRatio")],
      ["debtAssets", mt(lang, "debtAssets")],
      ["assetTurnover", mt(lang, "assetTurnover")],
      ["roce", "ROCE"],
    ] },
  ];
  const MARKET_COLS = COL_GROUPS.flatMap((g) => g.cols);
  // Core columns are always shown — listed in the settings panel as locked rows.
  const CORE_COLS = [
    ["ticker", mt(lang, "ticker")],
    ["company", mt(lang, "company")],
    ["last", mt(lang, "last")],
  ];
  // Every sortable column by its screen label — the sort chain and the CSV header
  // both name keys the reader only ever sees as column titles.
  const SORT_LABEL_OF = Object.fromEntries([...CORE_COLS, ...MARKET_COLS]);
  // The key carries a version. A new column added to the DEFAULT set is invisible
  // to every reader who has ever opened this table, because their saved selection
  // is what loads — the week and month change columns would have shipped to
  // nobody. Bumping the key retires the old selection once, deliberately. It went
  // to _v3 in the same session as _v2: «Номинал» joined the default set an hour
  // later, and a reader who had already picked up _v2 would not have seen it.
  const [visibleCols, setVisibleCols] = useState(() => {
    try { const s = JSON.parse(localStorage.getItem("uz_market_cols_v3")); if (Array.isArray(s)) return new Set(s); } catch (e) { /* ignore */ }
    return new Set(["change", "change1w", "change1m", "nominal",
                    "open", "high", "low", "volume", "date", "source"]);
  });
  const [colsOpen, setColsOpen] = useState(false);
  const colsBtnRef = useRef(null); // the popover is portaled — it anchors off this
  const [colsSearch, setColsSearch] = useState("");
  const [openGroups, setOpenGroups] = useState(() => new Set(["overview", "volumes", "financials"]));
  const toggleGroup = (k) => setOpenGroups((prev) => { const n = new Set(prev); if (n.has(k)) n.delete(k); else n.add(k); return n; });
  useEffect(() => { try { localStorage.setItem("uz_market_cols_v3", JSON.stringify([...visibleCols])); } catch (e) { /* ignore */ } }, [visibleCols]);
  const toggleCol = (k) => setVisibleCols((prev) => { const n = new Set(prev); if (n.has(k)) n.delete(k); else n.add(k); return n; });
  // Bonds carry no equity metrics — the exchange feed gives them only price/trade
  // data (no market cap, P/E, ROE, or issuer financials). Hide the stock-only
  // columns on the bonds view instead of rendering misleading blank cells; stocks
  // and bonds are not comparable on the same metrics.
  const EQUITY_ONLY_COLS = new Set(["mktCap", "pe", "pb", "ps", "roe", "roa", "netMargin", "eqAssets", "finRevenue", "finGross", "finCash", "finLiab", "finNet", "finOperating",
    "currentRatio", "quickRatio", "debtAssets", "assetTurnover", "roce"]);

  // Drag-to-reorder columns. Ticker + company stay pinned left (identity cells);
  // everything from "last" onward is reorderable. Order is persisted per user.
  const MOVABLE_KEYS = ["last", ...MARKET_COLS.map(([k]) => k)];
  // The key carries a version alongside uz_market_cols_v3, and for the same reason:
  // a saved order keeps only the keys it knew and APPENDS the rest, so a column
  // added next to «Изм.» landed at the far right of the board for every reader who
  // had ever opened it — three screens of horizontal scroll from the column it
  // belongs beside. Bumping the key retires the old order once, deliberately.
  const [colOrder, setColOrder] = useState(() => {
    try {
      const s = JSON.parse(localStorage.getItem("uz_market_col_order_v2"));
      if (Array.isArray(s)) {
        const known = new Set(["last", ...MARKET_COLS.map(([k]) => k)]);
        const kept = s.filter((k) => known.has(k));
        const missing = ["last", ...MARKET_COLS.map(([k]) => k)].filter((k) => !kept.includes(k));
        return [...kept, ...missing];
      }
    } catch (e) { /* ignore */ }
    return ["last", ...MARKET_COLS.map(([k]) => k)];
  });
  useEffect(() => { try { localStorage.setItem("uz_market_col_order_v2", JSON.stringify(colOrder)); } catch (e) { /* ignore */ } }, [colOrder]);
  const [dragCol, setDragCol] = useState(null);
  const [dragOverCol, setDragOverCol] = useState(null);
  const wrapRef = useRef(null); // .market-table-wrap — for the horizontal scroll controls
  const moveCol = (from, to) => {
    if (!from || from === to) return;
    setColOrder((prev) => {
      const arr = prev.filter((k) => MOVABLE_KEYS.includes(k));
      const fi = arr.indexOf(from);
      const ti = arr.indexOf(to);
      if (fi < 0 || ti < 0) return prev;
      const next = [...arr];
      next.splice(fi, 1);
      next.splice(ti, 0, from);
      return next;
    });
  };
  const resetColOrder = () => setColOrder(["last", ...MARKET_COLS.map(([k]) => k)]);

  // Frozen columns. A column can only be frozen at the left edge — that is what
  // freezing IS — so pinning hoists it to the front of the movable block and the
  // identity cells (ticker, company) join the frozen group, otherwise the pinned
  // column would float over the very names it is meant to be read against.
  const [pinnedCols, setPinnedCols] = useState(() => {
    try { const s = JSON.parse(localStorage.getItem("uz_market_pinned_cols")); if (Array.isArray(s)) return new Set(s); } catch (e) { /* ignore */ }
    return new Set();
  });
  useEffect(() => { try { localStorage.setItem("uz_market_pinned_cols", JSON.stringify([...pinnedCols])); } catch (e) { /* ignore */ } }, [pinnedCols]);
  const togglePin = (k) => setPinnedCols((prev) => { const n = new Set(prev); if (n.has(k)) n.delete(k); else n.add(k); return n; });

  // Visible movable columns in the user's chosen order ("last" is always shown).
  const shownOrder = colOrder.filter((k) =>
    (k === "last" || visibleCols.has(k)) && !(type === "bond" && EQUITY_ONLY_COLS.has(k)));
  const pinnedOrder = shownOrder.filter((k) => pinnedCols.has(k));
  const visibleOrder = [...pinnedOrder, ...shownOrder.filter((k) => !pinnedCols.has(k))];
  const colSpan = 3 + visibleOrder.length;

  // Where each frozen column comes to rest: the summed width of everything
  // frozen to its left, measured off the live header (the table lays itself out
  // by content, so no width is knowable in advance). Re-measured after every
  // render — the same trick MarketStickyHead uses, and just as cheap, because a
  // measurement that changed nothing never reaches state.
  const [pinOffsets, setPinOffsets] = useState({});
  const pinMeasureRef = useRef(() => {});
  const pinKeys = pinnedOrder.join("|");
  useEffect(() => {
    const measure = () => {
      const head = wrapRef.current && wrapRef.current.querySelector(".market-table thead tr");
      if (!head || !pinKeys) {
        setPinOffsets((prev) => (Object.keys(prev).length ? {} : prev));
        return;
      }
      const widths = Array.from(head.children).map((th) => th.getBoundingClientRect().width);
      const next = {};
      let acc = 0;
      // The header row is [ticker, company, ...visibleOrder], and the frozen
      // columns are the first of visibleOrder — so the run is contiguous.
      ["__ticker", "__company", ...pinKeys.split("|")].forEach((k, i) => {
        next[k] = Math.round(acc);
        acc += widths[i] || 0;
      });
      setPinOffsets((prev) => {
        const ks = Object.keys(next);
        if (ks.length === Object.keys(prev).length && ks.every((k) => prev[k] === next[k])) return prev;
        return next;
      });
    };
    pinMeasureRef.current = measure;
    measure();
    window.addEventListener("resize", measure);
    return () => { pinMeasureRef.current = () => {}; window.removeEventListener("resize", measure); };
  }, [pinKeys]);
  useLayoutEffect(() => { pinMeasureRef.current(); });
  // Until the widths are known the columns would all stack at left: 0 — better
  // one unfrozen frame than a frame of columns piled on each other.
  const lastPinned = pinnedOrder[pinnedOrder.length - 1];
  const pinAt = (key) => (pinKeys && pinOffsets[key] !== undefined
    ? { left: pinOffsets[key], edge: key === lastPinned }
    : null);
  const pinCls = (pin) => (pin ? ` market-col-pinned${pin.edge ? " market-col-pinned-edge" : ""}` : "");

  // Moves act inside the column's own block: a frozen column reorders among the
  // frozen ones, a loose column among the loose. Otherwise "move right" on a
  // frozen column would change nothing on screen, since freezing puts it back.
  const colGroupOf = (key) => visibleOrder.filter((k) => pinnedCols.has(k) === pinnedCols.has(key));
  const moveColBy = (key, step) => {
    const group = colGroupOf(key);
    const i = group.indexOf(key);
    if (i < 0) return;
    if (step === "start") { if (i > 0) moveCol(key, group[0]); return; }
    if (step === "end") { if (i < group.length - 1) moveCol(key, group[group.length - 1]); return; }
    const j = i + step;
    if (j >= 0 && j < group.length) moveCol(key, group[j]);
  };

  // The header toolbar: which column it belongs to, and whether it was opened
  // from the mirrored sticky bar (so it anchors to the header the reader sees).
  const [colMenu, setColMenu] = useState(null);
  const closeColMenu = React.useCallback(() => setColMenu(null), []);

  const openPanel = (ticker) => {
    setPanelTicker(ticker);
    setPanelWiki(null);
    setPanelWikiLoading(true);
    fetch(`/api/securities/${encodeURIComponent(ticker)}/info?language=${lang}`)
      .then((r) => r.json())
      .then((d) => { if (d.ok) setPanelWiki(d.wiki); })
      .catch(() => {})
      .finally(() => setPanelWikiLoading(false));
  };

  const smap = securitiesMap || {};
  // Fallback sector source for a ticker the securities catalog has not reached;
  // the heat map builds the same map from the same list.
  const companyMap = React.useMemo(() => {
    const by = {};
    (companies || []).forEach((c) => { if (c?.ticker) by[c.ticker] = c; });
    return by;
  }, [companies]);
  const fmap = financials || {};
  // Financials are company-level, so a preferred share shares its common
  // sibling's figures (and vice versa) — mirror the logo sibling fallback
  // (TKDM <-> TKDMP) so both halves of a pair show data from one cached row.
  const finOf = (ticker) => {
    const t = String(ticker || "").toUpperCase();
    return fmap[t] || fmap[t.endsWith("P") ? t.slice(0, -1) : `${t}P`] || null;
  };
  const tmap = tradeStats || {};
  const latestTsDay = latestTradeStatsDay(tmap);
  const preparedEnriched = (Array.isArray(rows) ? rows : [])
    .map(enrichMarketStock)
    .map((r) => applyTradeStats(r, tmap, latestTsDay));

  // MAIN | NEGO — the exchange's own two boards. Its execution feed tags every
  // deal with a board id: G1 is the auction, T1 is a negotiated (переговорная)
  // deal struck bilaterally at an agreed price. The two are not one market and
  // must not be summed: a 2,2-млрд-бумаг T1 deal at 55 while the auction traded
  // 95,5–99,99 (HMKB, 14.08.2026) poisoned the session's turnover, low and VWAP
  // until the day statistics were split.
  //
  // MAIN is the board this page has always shown. NEGO is the same securities
  // seen through their negotiated deals: only the lines that had one, with the
  // negotiated turnover, quantity and count in the volume columns and the
  // negotiated average price derived from them. The PRICES stay the session's —
  // a negotiated price is not a quote, which is the whole reason the boards are
  // separate — and the note under the table says so.
  const negotiated = (r) => Number.isFinite(r?.nego?.value) && r.nego.value > 0;
  const asNegotiated = (r) => ({
    ...r,
    stockVolume: r.nego.value,
    stockQuantity: r.nego.qty,
    stockTradeCount: r.nego.count,
    // Cleared so «Ср. цена акции» derives from the NEGOTIATED turnover and
    // quantity (avgSharePrice) instead of serving the auction's VWAP under a
    // negotiated row. Same for the session VWAP column.
    avgPrice: undefined,
    vwap: null,
    // The date column must name the day the DEAL was struck. A negotiated deal is
    // not a session and is routinely weeks old — the ones on this market in
    // August 2026 were dated 02.07, 10.07, 07.08 and 13.08 — so showing the
    // auction's last-trade date beside a negotiated turnover would date the deal
    // to a session it had nothing to do with.
    last_trade_date: r.nego.date || r.last_trade_date,
  });
  const negotiatedCount = preparedEnriched.filter(negotiated).length;
  // How many negotiated deals the stored statistics know about ALTOGETHER. Most of
  // them are on bonds, and the bonds segment is its own section — so an empty NEGO
  // board here has to say where the deals actually are, or it reads as «this
  // market has none» when the market has four.
  const negotiatedAnywhere = Object.values(tmap).filter(
    (s) => Number.isFinite(s?.block_value) && s.block_value > 0).length;
  const preparedAllSession = segment === "nego"
    ? preparedEnriched.filter(negotiated).map(asNegotiated)
    : preparedEnriched;
  // Over a WINDOW every row is restated once, here, rather than at each of the
  // dozen places that read one. A window's «объём» is its sessions' turnover
  // added up, its «макс» is the highest price inside it, its «ср. сумма сделки»
  // is those сумы over those deals — so the columns, the summary cards, the
  // movers strip, the sort keys, the CSV and the heat map all answer for the
  // period the reader chose, and none of them has to know that a period was
  // chosen. A figure the stored sessions cannot answer comes back null and the
  // cell prints a dash: no column is filled with a session's number under a
  // heading that says a year.
  //
  // NEGO is left alone: a negotiated deal is not a session, the boards are
  // separate for that reason, and there is no windowed record of them to sum.
  const windowed = changePeriod !== "1d" && segment !== "nego";
  const orNull = (v) => (Number.isFinite(v) ? v : null);
  const asPeriod = (r) => {
    const hit = changeOver(r.ticker, changePeriod);
    const st = statsOver(r.ticker, changePeriod);
    return {
      ...r,
      changePercent: hit ? hit.pct : null,
      // Dropped, not converted: a window has no single сум figure — it spans
      // many sessions — and carrying the session's would put this morning's
      // сумы beside half a year's percent.
      changeValue: null,
      periodPct: hit ? hit.pct : null,
      stockVolume: orNull(st?.value),
      periodVolume: orNull(st?.value),
      stockQuantity: orNull(st?.qty),
      stockTradeCount: orNull(st?.trades),
      // The window's volume-weighted price. Cleared rather than left as the
      // session's, so «Ср. цена акции» can never quote one morning under a year.
      avgPrice: Number.isFinite(st?.vwap) ? st.vwap : undefined,
      vwap: orNull(st?.vwap),
      // `undefined`, not null: the session renderers fall back to the last price
      // when these are exactly null, and a window with no stored open must show
      // a dash rather than today's quote.
      openPrice: Number.isFinite(st?.open) ? st.open : undefined,
      highPrice: Number.isFinite(st?.high) ? st.high : undefined,
      lowPrice: Number.isFinite(st?.low) ? st.low : undefined,
      ts: st && Number.isFinite(st.largest_value)
        ? { ...(r.ts || {}), largest_value: st.largest_value,
            largest_qty: orNull(st.largest_qty),
            largest_pct_value: orNull(st.largest_pct) }
        : (r.ts ? { ...r.ts, largest_value: null, largest_qty: null,
                    largest_pct_value: null } : r.ts),
      periodFrom: st?.from || hit?.from || null,
      periodTo: st?.to || null,
      periodSessions: orNull(st?.sessions),
      periodApprox: st?.approx === true,
      // How many of the window's sessions could say how many deals they held.
      // Absent when all of them could; a number here means the deal count and
      // the largest deal are floors over that many sessions, not the whole.
      periodDetailSessions: orNull(st?.detail_sessions),
    };
  };
  const preparedAll = windowed ? preparedAllSession.map(asPeriod) : preparedAllSession;
  // "preferred" is a client-side subset of stocks (the feed was fetched as
  // type=stock); narrow to preferred shares so the table, sectors and heatmap
  // all reflect the filter.
  const isPreferredSec = (r) =>
    smap[r.ticker]?.is_preferred === true ||
    smap[r.ticker]?.share_type === "preferred" ||
    r.share_type === "preferred";
  const byClass =
    type === "preferred" ? preparedAll.filter(isPreferredSec)
    : type === "ordinary" ? preparedAll.filter((r) => !isPreferredSec(r))
    : preparedAll;
  // ТЗ §4: activity is a fact about trading, taken from /api/instruments, not a
  // flag on the row — the registry's own flag disagreed with the tape.
  const isDormant = (r) => {
    const item = instruments[String(r.ticker || "").toUpperCase()];
    return item ? item.is_active === false : r.inactive === true;
  };
  const dormantCount = byClass.filter(isDormant).length;
  const prepared = byClass.filter((r) => isDormant(r) === inactiveOnly);
  // The MAP never shows a dormant listing. A treemap is a picture of movement —
  // every tile's area is the absolute change over the selected period — and a
  // security without a measured move can only be a tiny neutral placeholder that
  // says «—». Eleven of those told the reader nothing the «неактивные: 10» line
  // on the capitalisation card does not already say, in words. Computed from the
  // rows rather than from `inactiveOnly` on purpose: switching the table's filter
  // on and then switching to the map must not carry the eleven across.
  // The TABLE keeps the filter — there a dormant listing has a last close, a
  // date and an issuer to read, which is a row worth having.
  const mapRows = byClass.filter((r) => !isDormant(r));
  // The map answers for the SELECTED period, like the «Изм.» column and the
  // movers strip beside it — one question on the screen, one answer. It needs no
  // restatement of its own: `mapRows` comes off rows already restated for the
  // period, so a tile's colour and its AREA both describe the window the reader
  // chose, from the same stored sessions the column reads.
  const periodMapRows = mapRows;
  const search = String(query || "").trim().toLowerCase();

  // Gather sectors present in current data. Same resolver as the heat map, so a
  // chip here and a block there always hold the same tickers — and a row the
  // securities catalog has not reached lands under Прочее instead of answering
  // to no chip at all.
  const rowSector = (r) => sectorOf(r.ticker, smap, companyMap);
  // Display order, not alphabetical-by-english-key: sorted on the key, the list
  // read «Добыча, Логистика, Прочее, Производство…» — an order that exists only
  // in a language the reader is not being shown, with «Прочее» in the middle of
  // it. orderSectors is the same sequence the heat map's blocks follow.
  const presentSectors = orderSectors([...new Set(prepared.map(rowSector))]);
  const sectorWord = lang === "en" ? "Sector" : lang === "uz" ? "Soha" : "Отрасль";
  // A sector the current segment holds none of cannot filter it. Облигации are
  // «Прочее» to a security and nothing else, so a «Финансы» picked under Акции
  // would empty that table — and, since a chip row with one option is not drawn
  // (see below), leave no control to undo it. The choice is only suspended, not
  // thrown away: switching back to Акции applies it again.
  const activeSector = presentSectors.includes(marketSector) ? marketSector : null;
  // The map draws exactly what the sector control says, like the table beside
  // it. `periodMapRows` is declared before `activeSector` (it is built off the
  // period-restated rows), so the filter is applied here rather than there.
  const sectorMapRows = activeSector
    ? periodMapRows.filter((r) => rowSector(r) === activeSector)
    : periodMapRows;

  // §3.8 multipliers. Inputs are gathered here; the arithmetic lives in the one
  // shared valuationRatios() so this table and the company page cannot disagree.
  const ratioOf = (ticker) => ratios[ticker] || ratios[String(ticker || "").toUpperCase()] || null;
  const mktCapOf = (r) => (Number.isFinite(r.marketCap) ? r.marketCap : null);
  // Earnings for the multiples: the last complete fiscal year when the issuer's
  // latest filing is a cumulative quarter, so P/E means the same thing in every
  // row. Without it the column silently mixes 3-, 6- and 12-month profits.
  const earningsOf = (r) => finEarnings(finOf(r.ticker));
  // ТЗ §8: the server owns this arithmetic. `valuationRatios` remains only as a
  // fallback for the moment before /api/market/multiples answers — it computes
  // at CLASS level and is therefore wrong for a two-class issuer, so it must
  // never outlive the response.
  const multiplesOf = (r) => multiples[String(r.ticker || "").toUpperCase()] || null;
  const valuationOf = (r) => {
    const server = multiplesOf(r);
    if (server) return { pe: server.pe, pb: server.pb, server: true };
    const rat = ratioOf(r.ticker) || {};
    const local = valuationRatios({
      marketCap: mktCapOf(r),
      netIncome: earningsOf(r).netIncome,
      equity: rat.total_equity,
      roePercent: rat.roe,
    });
    return {
      pe: { value: local.pe, status: local.pe == null ? "no_financials" : "ok" },
      pb: { value: local.pb, status: local.pb == null ? "no_financials" : "ok" },
      server: false,
    };
  };
  // An out-of-range multiple sorts (and exports) as absent: a P/E column
  // ordered by value must not crown a 2 816× that the cell itself calls «н/зн».
  const peOf = (r) => {
    const m = valuationOf(r).pe;
    return m?.status === "out_of_range" ? null : m?.value ?? null;
  };

  // A flow figure scaled to twelve months, for SORTING only (ТЗ §7). Returns
  // null rather than a raw value when the period is unknown: ordering by a
  // number whose span nobody knows is the defect, not the fix.
  const annualisedFin = (r, field) => {
    const fin = finOf(r.ticker);
    const value = fin?.[field];
    if (!Number.isFinite(value)) return null;
    const months = Number.isFinite(fin?.period_months)
      ? fin.period_months
      : (fin?.quarter > 0 ? fin.quarter * 3 : (fin?.year ? 12 : null));
    if (!months || months <= 0) return null;
    return (value * 12) / months;
  };

  // ТЗ §8: a multiple the server withheld says WHY. «убыток» is a fact about the
  // issuer, not missing data; «проверяется» means the statement behind it failed
  // validation; a range status means the figure exists and is not believable.
  const statusText = (status) => multipleStatusText(status, lang);
  const multipleCell = (row, metric, digits, suffix = "×") => {
    // Out of range the raw figure is noise, not a multiple — the cell says
    // «н/зн» and the tooltip keeps the number (superseding V15's value+flag).
    if (metric?.value != null && metric.status === "out_of_range") {
      return <td className="num"><span className="cell-status" title={nmTitle(metric, digits, suffix, lang)}>{nmLabel(lang)}</span></td>;
    }
    if (metric?.value != null) {
      const flags = [];
      if (metric.estimate) flags.push(mt(lang, "estimateFlag"));
      const period = metric.base_period || metric.financial_period || null;
      const title = [
        period,
        metric.denominator_period && metric.denominator_period !== period
          ? `${lang === "ru" ? "средняя база" : lang === "uz" ? "o‘rtacha baza" : "average base"}: ${metric.denominator_period}`
          : null,
        metric.note,
        metric.allowed ? `∉ [${metric.allowed.join("; ")}]` : null,
      ].filter(Boolean).join(" · ") || undefined;
      const sub = [period, ...flags].filter(Boolean).join(" · ");
      return (
        <td className="num" title={title}>
          <strong>{formatRatio(metric.value, digits, lang)}{suffix}</strong>
          {sub && <span className="fin-cell-period">{sub}</span>}
        </td>
      );
    }
    const label = statusText(metric?.status);
    if (!label) return <td className="num">{noSecLabel(row)}</td>;
    if (metric?.computed != null && ["unverified", "loss_making"].includes(metric.status)) {
      const period = metric?.base_period ? ` · ${metric.base_period}` : "";
      const reasons = (metric?.reasons || []).join("; ") || metric?.note || label;
      return (
        <td className="num" title={`${reasons}${period}`}>
          <strong>{formatRatio(metric.computed, digits, lang)}{suffix}</strong>
          <span className={`fin-cell-period metric-warning metric-warning--${metric.status}`}>{label}</span>
        </td>
      );
    }
    const reasons = (metric?.reasons || []).join("; ")
      || (metric?.computed != null
        ? `${formatRatio(metric.computed, digits, lang)}${suffix} ∉ [${metric.allowed?.join(", ")}]`
        : metric?.note || "");
    const period = metric?.base_period ? ` · ${metric.base_period}` : "";
    return <td className="num"><span className="cell-status" title={(reasons + period).trim() || undefined}>{label}</span></td>;
  };
  // Issuers openinfo records as having no tradable securities at all
  // (is_listing=false, empty RFB/OTC share registries — e.g. MNGM):
  // market-value cells state that fact instead of an ambiguous dash.
  const noSecLabel = (r) => (r.isin ? "—"
    : lang === "ru" ? "нет бумаг" : lang === "uz" ? "qog'oz yo'q" : "no securities");
  // "Not applicable": the figure is undefined for this issuer's reporting
  // form (bank/insurer/fund statements) rather than missing.
  const naLabel = () => (lang === "ru" ? "н/п" : lang === "uz" ? "t/e" : "n/a");
  // Trade date of the row's day statistics (YYYYMMDD → YYYY-MM-DD).
  const tsDate = (r) => {
    const d = String(r.ts?.trade_date || "");
    return /^\d{8}$/.test(d) ? `${d.slice(0, 4)}-${d.slice(4, 6)}-${d.slice(6)}` : null;
  };
  // Per-trade stat cells for securities with no execution in the archive at
  // all (verified 10-year lookback): state "no trades" — the same fact the
  // trade-date column shows — rather than an ambiguous dash.
  const neverTraded = (r) => (!r.last_trade_date && !r.ts ? mt(lang, "noTrade") : "—");
  const pbOf = (r) => {
    const m = valuationOf(r).pb;
    return m?.status === "out_of_range" ? null : m?.value ?? null;
  };

  // One financials cell, with the reporting period it belongs to underneath it.
  // The period is not decoration: these figures mix completed annuals with
  // cumulative quarters across issuers, and a field whose only source is another
  // filing carries that filing's period (marked, so it reads as a footnote rather
  // than as this row's number).
  const finCell = (row, field, { naWhenTopLine = false } = {}) => {
    const f = finOf(row.ticker);
    const value = f?.[field];
    if (value == null && naWhenTopLine && Number.isFinite(f?.revenue)) {
      return <td className="num">{naLabel()}</td>;
    }
    if (!Number.isFinite(value)) return <td className="num">—</td>;
    const period = finFieldPeriod(f, field);
    const borrowed = Boolean((f?.field_periods || {})[field]);
    const coverage = finPeriodCoverage(period, lang);
    // How much trading the figure covers, printed rather than only hovered: NSBU
    // quarters are cumulative, so this column routinely sets one issuer's six
    // months beside another's three and a third's completed year. Balance lines
    // get no suffix — they are a position on the closing date, not an accumulation.
    const length = finFieldCoverage(period, field, lang);
    return (
      <td className="num">
        <strong>{finValue(value, lang)}</strong>
        {period && (
          <span className={`fin-cell-period${borrowed ? " borrowed" : ""}`}
                title={borrowed
                  ? `${period} · ${coverage} — ${lang === "ru" ? "период отличается от периода строки"
                      : lang === "uz" ? "davr qator davridan farq qiladi"
                      : "a different period than the row"}`
                  : `${period} · ${coverage}`}>
            {period}{length ? ` · ${length}` : ""}{borrowed ? " *" : ""}
          </span>
        )}
      </td>
    );
  };

  // One published coefficient from the issuer's own indicator filing — the same
  // rows the company page's «Коэффициенты» card carries.
  //
  // UNITS ARE THE SOURCE'S. Долг/Активы is published as a percent; текущая и
  // быстрая ликвидность, оборачиваемость активов and ROCE are published as bare
  // coefficients (ROCE 0,07 is seven percent of capital employed). Of these,
  // only debt_ratio and total_asset_turnover reproduce from the sums this
  // platform holds — 401 of 401 issuer-years each; the others are the source's
  // arithmetic on a base it does not name, so they are shown exactly as filed
  // and never rescaled into a percent we would be inventing.
  //
  // The year sits under the figure and is per FIELD, not per issuer: a company
  // can publish liquidity for 2023 and ROE for 2025, and one label over both
  // would claim something the store does not say.
  // The two liquidity ratios are defined on a balance that splits current from
  // non-current assets, and the bank form does not: a bank's balance is ordered by
  // instrument, not by maturity, and «текущая ликвидность» has no meaning on it.
  // The remaining 28 empty cells on this board are exactly the thirteen banks and
  // their preferred lines — so the cell says «н/п», the way the gross-profit and
  // operating-income columns already do for the same forms, rather than leaving a
  // dash a reader would read as our gap.
  const LIQUIDITY_FIELDS = new Set(["current_ratio", "quick_ratio"]);
  const ratioCell = (row, field, { digits = 2, suffix = "" } = {}) => {
    const r = ratioOf(row.ticker);
    const value = r?.[field];
    if (!Number.isFinite(value)) {
      const form = finOf(row.ticker)?.org_type;
      if (LIQUIDITY_FIELDS.has(field) && form === "bank") {
        return (
          <td className="num">
            <span className="cell-status" title={lang === "en"
              ? "The bank balance is not split into current and non-current assets — no liquidity ratio is defined on it"
              : lang === "uz"
                ? "Bank balansi joriy va uzoq muddatli aktivlarga bo'linmaydi — likvidlik koeffitsiyenti aniqlanmaydi"
                : "Банковский баланс не делится на текущие и долгосрочные активы — коэффициент ликвидности на нём не определён"}>
              {lang === "en" ? "n/a" : "н/п"}
            </span>
          </td>
        );
      }
      return <td className="num">—</td>;
    }
    const period = (r.periods || {})[field] || null;
    return (
      <td className="num">
        {formatRatio(value, digits, lang)}{suffix}
        {period && <span className="fin-cell-period">{period}</span>}
      </td>
    );
  };

  // Value read for each sortable column. ticker/company/date are strings, the rest numeric.
  const sortAccessors = {
    ticker: (r) => r.ticker || "",
    company: (r) => r.name || "",
    last: (r) => marketDisplayPrice(r),
    // The selected period's change, so the order follows what the column shows.
    change: (r) => (changePeriod === "1d"
      ? r.changePercent
      : (changeOver(r.ticker, changePeriod)?.pct ?? null)),
    change1w: (r) => changeOver(r.ticker, "1w")?.pct ?? null,
    change1m: (r) => changeOver(r.ticker, "1m")?.pct ?? null,
    nominal: (r) => parOf(r),
    priceToPar: (r) => priceToPar(r),
    open: (r) => r.openPrice,
    high: (r) => r.highPrice,
    low: (r) => r.lowPrice,
    volume: (r) => r.stockVolume,
    volQty: (r) => r.stockQuantity,
    avgShare: (r) => (Number.isFinite(r.avgPrice) ? r.avgPrice : avgSharePrice(r)),
    avgTrade: (r) => avgTradeValue(r),
    bigTrade: (r) => r.ts?.largest_value,
    volShare: (r) => r.stockVolume,
    // ТЗ §7: a column that mixes reporting periods may not be ordered by its
    // raw values. The cached rows span twelve different (year, months)
    // combinations, so a full year always outranked a peer's four quarters for
    // no reason the reader could see. The CELL keeps its own period and label;
    // only the SORT runs on the twelve-month normalisation. Balance-sheet lines
    // are a position on a date and are never scaled.
    finRevenue: (r) => annualisedFin(r, "revenue"),
    finGross: (r) => annualisedFin(r, "gross_profit"),
    finCash: (r) => finOf(r.ticker)?.cash,
    finLiab: (r) => finOf(r.ticker)?.total_liabilities,
    finNet: (r) => annualisedFin(r, "net_income"),
    finOperating: (r) => annualisedFin(r, "operating_income"),
    mktCap: (r) => mktCapOf(r),
    pe: (r) => peOf(r),
    pb: (r) => pbOf(r),
    // Sort on what is RENDERED — the server envelope — not on the raw
    // indicator feed. Sorting on the feed while rendering the envelope put a
    // withheld value's ghost in the ordering (ТЗ мультипликаторов, лист 05:
    // «сортировка по марже выдаёт бессмысленный порядок»).
    ps: (r) => multiplesOf(r)?.ps?.value ?? null,
    roe: (r) => multiplesOf(r)?.roe?.value ?? ratioOf(r.ticker)?.roe,
    roa: (r) => multiplesOf(r)?.roa?.value ?? ratioOf(r.ticker)?.roa,
    netMargin: (r) => multiplesOf(r)?.net_margin?.value ?? ratioOf(r.ticker)?.net_profit_margin,
    eqAssets: (r) => multiplesOf(r)?.equity_assets?.value ?? null,
    // The published coefficients sort on what they show. Unlike the financials
    // columns there is nothing to annualise: a liquidity ratio is a position on
    // a date, and a turnover is already a full year's revenue over assets.
    currentRatio: (r) => ratioOf(r.ticker)?.current_ratio,
    quickRatio: (r) => ratioOf(r.ticker)?.quick_ratio,
    debtAssets: (r) => ratioOf(r.ticker)?.debt_ratio,
    assetTurnover: (r) => ratioOf(r.ticker)?.total_asset_turnover,
    roce: (r) => ratioOf(r.ticker)?.return_to_capital_employed,
    // Normalized to YYYYMMDD so the comparison is chronological. The raw field is
    // a mix of DD.MM.YYYY (live feed) and YYYY-MM-DD (listings registry), and
    // comparing those as strings ordered by the leading digits — "31.01.2026"
    // sorted above "05.02.2026", so "latest first" broke at every month boundary.
    date: (r) => marketRowDay(r) || "",
    source: (r) => r.url || "",
  };

  const visibleRows = prepared
    .filter((row) => {
      if (favOnly && !hasFav(row.ticker)) return false;
      if (activeSector && rowSector(row) !== activeSector) return false;
      if (!search) return true;
      return `${row.ticker || ""} ${row.name || ""} ${row.isin || ""}`.toLowerCase().includes(search);
    })
    .sort((a, b) => {
      if (!sortKeys.length) {
        // Same normalization as the `date` accessor — the default "most recently
        // traded first" order was wrong across month boundaries for exactly the
        // same reason (mixed DD.MM.YYYY / YYYY-MM-DD compared lexicographically).
        const aDate = marketRowDay(a) || "";
        const bDate = marketRowDay(b) || "";
        if (aDate !== bDate) return bDate.localeCompare(aDate);
        return Math.abs(b.changePercent ?? -Infinity) - Math.abs(a.changePercent ?? -Infinity);
      }
      // Each key decides only the rows the keys before it tied on.
      for (const { key, dir } of sortKeys) {
        const acc = sortAccessors[key];
        if (!acc) continue;
        const c = compareSortValues(acc(a), acc(b), dir);
        if (c) return c;
      }
      return 0;
    });
  // The summary cards describe the BOARD, not the table's filter. Fed the
  // dormant subset they answered «сделки сегодня: 11» about eleven securities
  // that have not traded in three months, and named a «лидер роста» at 0 %.
  // Favourites, search and «Неактивные» therefore still never reach them.
  //
  // The sector chip is the one exception (customer, 2026-08-18): it picks WHICH
  // market is being read, not which rows of one are hidden, and a «Финансы»
  // board whose cards went on counting the whole exchange's advancers and
  // capitalisation was answering a question nobody had asked. The pool is the
  // one the movers panels have used since 2026-08-12, so the cards and the
  // strip under them can never describe different sets of securities.
  //
  // Only while the chip row is on screen, though. The map has no sector control
  // (its tiles are the whole board) and a card silently answering for one sector
  // beside a picture of all of them would be unreadable — with nothing to click
  // to find out why.
  // The cards state what the reader is looking at — and since the sector control
  // now stands over the map as well, «Финансы» there has to restate them for the
  // same eight issuers it restates under the table.
  const cardSector = activeSector;
  // Two readings, deliberately: `stats` stays the whole board because the CSV,
  // the session date and the «доля объёма» column all make a claim ABOUT THE
  // MARKET — a row's share of the day's turnover is not a share of its sector's
  // — while `cardStats` is what the four cards and the movers strip report.
  const stats = buildMarketStats(byClass.filter((r) => !isDormant(r)), { windowed });
  const cardStats = cardSector
    ? buildMarketStats(byClass.filter((r) => !isDormant(r) && rowSector(r) === cardSector),
                       { windowed })
    : stats;
  const moverStats = cardStats;
  // Капитализация is a STOCK, not a flow: whatever period is on screen, the
  // market is worth what it is worth today, and restating the card's value to
  // the window's first session would put a year-old figure under a heading that
  // says «Капитализация». What the period CAN say is how far that figure moved
  // over it — so the card keeps today's sum and gains the period's change.
  //
  // Measured on the same rows the card sums, from the same window percents the
  // «Изм.» column shows: each line's capitalisation is walked back through its
  // own change to what it was at the window's start, and the two sums compared.
  // Share counts are held constant — an issue inside the window would move the
  // sum without the price moving — which is why this is stated as the change in
  // the market's PRICE, and why a line whose window has no percent sits out of
  // both sums rather than entering one of them.
  const capPeriodChange = (() => {
    if (!windowed) return null;
    const pool = byClass.filter(
      (r) => !isDormant(r) && (!cardSector || rowSector(r) === cardSector));
    let now = 0;
    let before = 0;
    pool.forEach((r) => {
      const cap = mktCapOf(r);
      const pct = r.changePercent;
      if (!(cap > 0) || !Number.isFinite(pct) || pct <= -100) return;
      now += cap;
      before += cap / (1 + pct / 100);
    });
    return before > 0 ? (now - before) / before * 100 : null;
  })();
  // Dormant listings inside the selected sector — what the capitalisation card
  // below leaves out of its own sum, counted on the same basis the server's
  // whole-market answer counts them.
  const sectorDormant = cardSector
    ? byClass.filter((r) => isDormant(r) && rowSector(r) === cardSector).length
    : 0;
  // Over a WINDOW all three panels are a different list, and they are not drawn
  // from the latest session's rows: a security that has not traded today still
  // moved over the month, and leaving it out would rank the month by who
  // happened to trade this morning (buildMarketStats, `windowed`).
  //
  // Ликвидность followed the same rule until 2026-08-18 only because the sum did
  // not exist — the strip could show the session's turnover or nothing. Every
  // settled session's total_value has been stored per security since 2025-08-13,
  // so the month's turnover is now the month's sessions added up, served beside
  // the change over the same window (/api/market/changes → `turnover`). It is a
  // sum of what actually traded, and each line carries the session count and the
  // first session inside the window in its tooltip, because on this market «за
  // полгода» is routinely four sessions and a reader must be able to see that.
  // Nothing to re-derive: `byClass` already IS the period's rows, so the three
  // panels come out of the same buildMarketStats the cards use and can never
  // describe a different set of securities from the table under them.
  const periodMovers = moverStats;

  // §3.8: export the table the user is looking at as OUR report, client-side.
  //
  // It used to emit a bare 20-column board dump — English headers on a Russian page, UZSE's
  // own name strings, full-precision floats ("43.84615384615385") and a comma delimiter —
  // which read as somebody else's export, because that is what an exchange board is. What
  // separates our page from uzse.uz is the reporting beside the quote, and none of it was in
  // the file: revenue, gross and operating profit, net income, cash, liabilities, and the
  // period each of those figures actually covers. Those are here now, next to the multiples
  // computed from them, under a header block that says what the file is and where each part
  // came from.
  //
  // Delimiter and decimal mark follow the UI language for the same reason. Excel in a ru/uz
  // locale splits on ';' and reads ',' as the decimal mark, so a comma-separated file with
  // dotted decimals opens as a single column of text — the most literal way to look like a
  // foreign dump.
  const exportCsv = () => {
    const ruLocale = lang !== "en";
    const sep = ruLocale ? ";" : ",";
    const cell = (v) => {
      if (v === null || v === undefined || v === "" || (typeof v === "number" && Number.isNaN(v))) return "";
      let s = typeof v === "number"
        ? (ruLocale ? String(v).replace(".", ",") : String(v))
        : String(v);
      // A quoted field is needed for the delimiter, quotes and newlines — and, once decimals
      // are commas, for every number too when the delimiter is a comma.
      return new RegExp(`["\\n\\r${sep === ";" ? ";" : ","}]`).test(s)
        ? `"${s.replace(/"/g, '""')}"` : s;
    };
    // Rounded the way the screen rounds: a report states a figure, it does not dump a float.
    const round = (v, digits) => (Number.isFinite(v) ? Number(v.toFixed(digits)) : "");
    const money = (v) => (Number.isFinite(v) ? Math.round(v) : "");

    const filters = [
      mt(lang, type === "stock" ? "stocks" : type === "bond" ? "bonds"
        : type === "preferred" ? "preferredStocks" : type === "ordinary" ? "ordinaryStocks" : "all"),
      // The file states the filters that ACTUALLY shaped it — a suspended sector
      // named in the header would describe a selection the rows never went through.
      activeSector || "",
      favOnly ? mt(lang, "csvFav") : "",
      // The export states its filters, and «только неактивные» changes what the
      // whole file IS — a sheet of eleven dormant listings that looks like the
      // board would be read as the board.
      inactiveOnly ? (lang === "en" ? "inactive only" : lang === "uz" ? "faqat faol emas" : "только неактивные") : "",
      String(query || "").trim() ? `${mt(lang, "csvSearch")}: ${String(query).trim()}` : "",
    ].filter(Boolean).join(" · ");
    // `last_trade_date` arrives as DD.MM.YYYY from the live feed and YYYY-MM-DD from the
    // listings registry. Normalise both through marketRowDay so one column holds one format.
    const day = (d) => (/^\d{8}$/.test(d || "") ? `${d.slice(6)}.${d.slice(4, 6)}.${d.slice(0, 4)}` : "");
    const session = day(stats.boardDay);

    // Two columns, so the block reads as label/value in a spreadsheet rather than as text
    // spilled across the sheet. A blank row separates it from the table proper.
    const lines = [
      [mt(lang, "csvTitle"), ""].map(cell).join(sep),
      // Stamped DD.MM.YYYY like every other date in the file. Deliberately not the browser
      // locale's own format: on en-US that prints 7/29/2026 next to a 29.07.2026 trade-date
      // column, and one report should not carry two date conventions.
      [mt(lang, "csvGenerated"), (() => {
        const d = new Date();
        const pad = (n) => String(n).padStart(2, "0");
        return `${pad(d.getDate())}.${pad(d.getMonth() + 1)}.${d.getFullYear()} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
      })()].map(cell).join(sep),
      // Over a window there is no ONE session to stamp — `stats.boardDay` is
      // null by design — and a «Торговая сессия» row with nothing after it reads
      // as a missing value rather than as a period export. The period line below
      // takes its place.
      ...(session ? [[mt(lang, "csvSession"), session].map(cell).join(sep)] : []),
      // Which PERIOD the volume columns describe. Without it the file is a set
      // of numbers that look like a session and are a year — the one thing a
      // spreadsheet, unlike the screen, carries no control to reveal.
      ...(windowed
        ? [[mt(lang, "csvPeriod"), changePeriodLabel(changePeriod, lang, "label")].map(cell).join(sep),
           [mt(lang, "csvPeriodNote"), ""].map(cell).join(sep)]
        : []),
      [mt(lang, "csvFilter"), filters].map(cell).join(sep),
      // The file is the table as it stands on screen, so the row ORDER is part of
      // what is being exported — state it rather than let the reader guess.
      [mt(lang, "csvSort"), sortKeys.length
        ? sortKeys.map(({ key, dir }) => `${SORT_LABEL_OF[key] || key} ${dir === "asc" ? "↑" : "↓"}`).join(" → ")
        : mt(lang, "csvSortDefault")].map(cell).join(sep),
      [mt(lang, "csvRows"), visibleRows.length].map(cell).join(sep),
      [mt(lang, "csvMoneyNote"), ""].map(cell).join(sep),
      [mt(lang, "csvSources"), ""].map(cell).join(sep),
      "",
    ];

    const header = [
      mt(lang, "ticker"), mt(lang, "company"), mt(lang, "isin"), mt(lang, "sector"),
      mt(lang, "shareType"), mt(lang, "date"),
      mt(lang, "last"), `${mt(lang, "change")}, %`,
      // Each window change names the session it was measured from — the same
      // statement the cell's tooltip makes, because a percent without its base
      // date is not reproducible from a spreadsheet.
      `${mt(lang, "change")} 1${lang === "en" ? "W" : lang === "uz" ? "H" : "Н"}, %`,
      lang === "en" ? "1W base" : lang === "uz" ? "1H bazasi" : "База 1Н",
      `${mt(lang, "change")} 1${lang === "en" ? "M" : lang === "uz" ? "O" : "М"}, %`,
      lang === "en" ? "1M base" : lang === "uz" ? "1O bazasi" : "База 1М",
      mt(lang, "open"), mt(lang, "high"), mt(lang, "low"),
      mt(lang, "volumeCol"), mt(lang, "csvTrades"), mt(lang, "volQty"),
      mt(lang, "avgSharePrice"), "VWAP", mt(lang, "bigTrade"), mt(lang, "volShare"),
      mt(lang, "finPeriod"), mt(lang, "finCoverage"),
      mt(lang, "finRevenue"), mt(lang, "finGross"), mt(lang, "finOperating"),
      mt(lang, "finNet"), mt(lang, "finCash"), mt(lang, "finLiab"),
      mt(lang, "mktCap"), mt(lang, "pe"), mt(lang, "pb"), "P/S",
      mt(lang, "roe"), mt(lang, "roa"),
      `${mt(lang, "netMargin")}, % (${mt(lang, "netMarginBankNote")})`,
      `${mt(lang, "equityAssets")}, %`,
    ];
    lines.push(header.map(cell).join(sep));

    for (const row of visibleRows) {
      const sec = smap[row.ticker] || {};
      const rat = ratioOf(row.ticker) || {};
      const fin = finOf(row.ticker) || null;
      const period = finRowPeriod(fin);
      const share = (stats.boardDay && marketRowDay(row) !== stats.boardDay) ? 0
        : Number.isFinite(row.stockVolume) && stats.totalVolume > 0
          ? (row.stockVolume / stats.totalVolume) * 100 : "";
      const isPreferred = sec.is_preferred || row.share_type === "preferred";
      lines.push([
        row.ticker,
        row.name,
        row.isin,
        sec.sector || "",
        (row.type === "bond" || sec.type === "bond") ? mt(lang, "bondOne")
          : isPreferred ? mt(lang, "preferred") : mt(lang, "ordinary"),
        day(marketRowDay(row)),
        round(marketDisplayPrice(row), 2), round(row.changePercent, 2),
        round(changeOver(row.ticker, "1w")?.pct, 2), day(changeOver(row.ticker, "1w")?.from),
        round(changeOver(row.ticker, "1m")?.pct, 2), day(changeOver(row.ticker, "1m")?.from),
        round(row.openPrice, 2), round(row.highPrice, 2), round(row.lowPrice, 2),
        money(row.stockVolume), row.stockTradeCount, row.stockQuantity,
        round(Number.isFinite(row.avgPrice) ? row.avgPrice : avgSharePrice(row), 2),
        round(row.vwap, 2), money(row.ts?.largest_value), round(share, 2),
        period || "", period ? finPeriodCoverage(period, lang) : "",
        money(fin?.revenue), money(fin?.gross_profit), money(fin?.operating_income),
        money(fin?.net_income), money(fin?.cash), money(fin?.total_liabilities),
        money(mktCapOf(row)), round(peOf(row), 2), round(pbOf(row), 2),
        round(multiplesOf(row)?.ps?.value, 2),
        round(multiplesOf(row)?.roe?.value ?? rat.roe, 2),
        round(multiplesOf(row)?.roa?.value ?? rat.roa, 2),
        round(multiplesOf(row)?.net_margin?.value ?? rat.net_profit_margin, 2),
        round(multiplesOf(row)?.equity_assets?.value, 2),
      ].map(cell).join(sep));
    }

    // CRLF and the BOM: what Excel expects of a CSV on Windows, which is where these open.
    const blob = new Blob(["﻿" + lines.join("\r\n")], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `uzse_${type || "all"}_${windowed ? changePeriod : ((stats.boardDay || "").slice(0, 8) || "latest")}.csv`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  };

  const formatLeader = (row) => row ? `${row.ticker} ${formatRatio(row.changePercent, 2, lang)}%` : "—";

  const sortTh = (key, label, opts = {}) => {
    const { movable = false, num = false, pinKey = null } = opts;
    const pin = pinKey ? pinAt(pinKey) : null;
    const rank = sortRankOf(key);
    const dir = sortDirOf(key);
    const chained = sortKeys.length > 1;
    const cls = [
      "market-th-sortable",
      num ? "market-th-num" : "",
      rank >= 0 ? "sorted" : "",
      movable ? "market-th-movable" : "",
      movable && dragCol === key ? "dragging" : "",
      movable && dragOverCol === key && dragCol && dragCol !== key ? "drag-over" : "",
      colMenu && colMenu.key === key ? "menu-open" : "",
      pin ? `market-col-pinned${pin.edge ? " market-col-pinned-edge" : ""}` : "",
    ].filter(Boolean).join(" ");
    const menuLabel = lang === "en" ? "Column controls"
      : lang === "uz" ? "Ustun boshqaruvi" : "Управление столбцом";
    // ⌘ on a Mac, Ctrl elsewhere — Shift works everywhere and is the one we teach.
    const isAdditive = (e) => e.shiftKey || e.metaKey || e.ctrlKey;
    const hint = lang === "en" ? "Shift+click (or long-press) — add as a secondary sort"
      : lang === "uz" ? "Shift+bosish (yoki uzoq bosish) — qoʻshimcha saralash kaliti"
      : "Shift+клик (или долгое нажатие) — добавить второй ключ сортировки";
    const dragHint = lang === "en" ? "Drag to reorder · click to sort"
      : lang === "uz" ? "Tartibni o'zgartirish uchun torting · saralash uchun bosing"
      : "Перетащите, чтобы переставить · нажмите для сортировки";
    return (
    <th
      key={key}
      className={cls}
      data-sort-key={key}
      onClick={(e) => {
        // The long-press already sorted; the tap that ends it must not sort again.
        if (longPress.current.fired) { longPress.current.fired = false; return; }
        onSort(key, isAdditive(e));
      }}
      onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onSort(key, isAdditive(e)); } }}
      onTouchStart={() => startLongPress(key)}
      onTouchMove={cancelLongPress}
      onTouchEnd={cancelLongPress}
      onTouchCancel={cancelLongPress}
      onContextMenu={(e) => { if (longPress.current.fired) e.preventDefault(); }}
      role="button"
      tabIndex={0}
      /* ARIA asks for aria-sort on ONE header at a time, so the chain's later keys
         announce their rank through the accessible name instead. */
      aria-sort={rank === 0 ? (dir === "asc" ? "ascending" : "descending") : "none"}
      aria-label={rank > 0
        ? `${label} — ${lang === "en" ? "sort" : lang === "uz" ? "saralash" : "сортировка"} ${rank + 1}, ${
            dir === "asc" ? (lang === "en" ? "ascending" : lang === "uz" ? "oʻsish" : "по возрастанию")
              : (lang === "en" ? "descending" : lang === "uz" ? "kamayish" : "по убыванию")}`
        : undefined}
      draggable={movable}
      onDragStart={movable ? (e) => { setDragCol(key); e.dataTransfer.effectAllowed = "move"; try { e.dataTransfer.setData("text/plain", key); } catch (_) { /* ignore */ } } : undefined}
      onDragOver={movable ? (e) => { e.preventDefault(); e.dataTransfer.dropEffect = "move"; if (dragOverCol !== key) setDragOverCol(key); } : undefined}
      onDragEnter={movable ? (e) => e.preventDefault() : undefined}
      onDragLeave={movable ? () => { setDragOverCol((c) => (c === key ? null : c)); } : undefined}
      onDrop={movable ? (e) => { e.preventDefault(); let from = dragCol; if (!from) { try { from = e.dataTransfer.getData("text/plain"); } catch (_) { from = null; } } moveCol(from, key); setDragCol(null); setDragOverCol(null); } : undefined}
      onDragEnd={movable ? () => { setDragCol(null); setDragOverCol(null); } : undefined}
      title={movable ? `${dragHint} · ${hint}` : hint}
      style={pin ? { left: pin.left } : undefined}
    >
      <span className="market-th-inner">
        {movable && <span className="market-th-grip" aria-hidden="true">⋮⋮</span>}
        <span>{label}</span>
        {/* Renders nothing for a column that is not an economic term (компания,
            UZSE) — the marker promises an explanation and must not appear
            without one. */}
        <TermInfo termId={key} lang={lang} label={label} />
        <span className="market-sort-caret">{rank >= 0 ? (dir === "asc" ? "▲" : "▼") : "↕"}</span>
        {/* The rank only earns its space once the order actually has more than one
            key — a lone "1" beside a single sorted column says nothing. */}
        {chained && rank >= 0 && <span className="market-sort-rank" aria-hidden="true">{rank + 1}</span>}
        {/* The column's own controls. Only the movable columns get it: ticker and
            company cannot be moved, hidden or unfrozen, so a toolbar there would
            be six dead buttons. The header's own click still sorts — this button
            swallows every gesture that would otherwise reach it, including the
            long-press and the drag. */}
        {movable && (
          <button
            type="button"
            className={`market-th-menu-btn${colMenu && colMenu.key === key ? " is-open" : ""}`}
            draggable={false}
            title={menuLabel}
            aria-label={`${label} — ${menuLabel}`}
            aria-haspopup="true"
            aria-expanded={!!(colMenu && colMenu.key === key)}
            onPointerDown={(e) => e.stopPropagation()}
            onMouseDown={(e) => e.stopPropagation()}
            onTouchStart={(e) => e.stopPropagation()}
            onKeyDown={(e) => e.stopPropagation()}
            onClick={(e) => {
              e.stopPropagation();
              e.preventDefault();
              const fromSticky = !!e.currentTarget.closest(".market-sticky-head");
              setColMenu((c) => (c && c.key === key ? null : { key, fromSticky }));
            }}
          >
            <svg viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="currentColor"
              strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
              <path d="M4 6l4 4 4-4" />
            </svg>
          </button>
        )}
      </span>
    </th>
    );
  };

  // ТЗ §2.4/§9: "отсутствие данных показывается как нулевое изменение" was the
  // defect. This cell substituted 0 whenever a close price existed, so a security
  // that has not traded since 15.07 read as "unchanged today" beside securities
  // that genuinely did not move. Measured against the trade archive, seven rows
  // showed 0 % where the last real session moved by up to 20 %. No trading in
  // this session means no change to report — the cell says so, and names the day
  // the price is actually from.
  const sessionChangeCell = (row) => {
    if (!row.tradedToday) {
      const when = row.last_trade_date || row.ts?.trade_date;
      return (
        <td className="num">
          <span className="cell-status" title={when
            ? `${lang === "ru" ? "цена за" : lang === "uz" ? "narx" : "price from"} ${when}`
            : undefined}>
            {lang === "en" ? "no trades" : lang === "uz" ? "bitim yo'q" : "нет сделок"}
          </span>
        </td>
      );
    }
    return <td className="num"><MarketChangeBadge value={row.changeValue} percent={row.changePercent} language={lang} /></td>;
  };

  // A change over a window says which session it measured FROM. On this market
  // the base is rarely the date the label implies — a security can go a fortnight
  // without a trade, so «за неделю» is routinely measured from a close three
  // weeks old, and a reader is entitled to know that before acting on it.
  const windowChangeCell = (row, code) => {
    const hit = changeOver(row.ticker, code);
    if (!hit) {
      return (
        <td className="num">
          <span className="cell-status" title={lang === "en"
            ? "no settled close that far back"
            : lang === "uz" ? "bu davr uchun yopilish narxi yo'q"
            : "нет закрытия за этот период"}>—</span>
        </td>
      );
    }
    const from = String(hit.from || "");
    const pretty = from.length === 8 ? `${from.slice(6)}.${from.slice(4, 6)}.${from.slice(0, 4)}` : from;
    return (
      <td className="num" title={pretty
        ? `${lang === "en" ? "from the close of" : lang === "uz" ? "yopilishdan" : "от закрытия"} ${pretty}`
        : undefined}>
        <MarketChangeBadge percent={hit.pct} language={lang} />
      </td>
    );
  };

  // Label + cell registry so the movable columns can render in any order.
  // The columns whose figures ARE the period once one is chosen. Their headers
  // carry it: «Объём торгов» over a year and over this morning are different
  // claims, the table is read without the period control in view, and a reader
  // who cannot see which is on screen will read the year as today.
  const PERIOD_COLS = new Set(["open", "high", "low", "volume", "volQty",
                               "avgShare", "avgTrade", "bigTrade", "volShare"]);
  const LABEL_OF = Object.fromEntries(
    [["last", mt(lang, "last")], ...MARKET_COLS].map(([k, label]) => [
      k,
      windowed && PERIOD_COLS.has(k)
        ? `${label} · ${changePeriodLabel(changePeriod, lang, "short")}`
        : label,
    ]));
  const NUM_COLS = new Set(MOVABLE_KEYS.filter((k) => k !== "date" && k !== "source"));
  // What a period cell is a statement about. On this market «за полгода» is
  // routinely four sessions, so the count and the first session inside the
  // window are not decoration — they are what makes the figure readable.
  const prettyDay = (d) => {
    const v = String(d || "");
    return v.length === 8 ? `${v.slice(6)}.${v.slice(4, 6)}.${v.slice(0, 4)}` : v;
  };
  const periodHint = (row, { extremes = false, detail = false } = {}) => {
    if (!windowed || !row?.periodSessions) return undefined;
    const label = changePeriodLabel(changePeriod, lang, "short");
    const sessions = `${formatRatio(row.periodSessions, 0, lang)} ${sessionCountLabel(row.periodSessions, lang)}`;
    const span = row.periodFrom
      ? `${lang === "en" ? "from" : lang === "uz" ? "dan" : "с"} ${prettyDay(row.periodFrom)}${
          row.periodTo ? ` ${lang === "en" ? "to" : lang === "uz" ? "gacha" : "по"} ${prettyDay(row.periodTo)}` : ""}`
      : "";
    // A session banked before the day statistics existed carries no high or low,
    // and its close stands in for both. The extreme is then a bound, not a
    // reading, and the cell that shows it says so rather than implying precision.
    const bound = extremes && row.periodApprox
      ? (lang === "en" ? "some sessions counted by their close"
         : lang === "uz" ? "ba'zi sessiyalar yopilish narxi bo'yicha"
         : "по закрытиям части сессий")
      : "";
    // The deal count and the largest deal exist only for the sessions banked
    // with the day statistics beside them; over a year that is a subset, and a
    // floor presented as a total is the one thing these cells must not be.
    const partial = detail && row.periodDetailSessions
      ? (lang === "en" ? `by ${formatRatio(row.periodDetailSessions, 0, lang)} of ${formatRatio(row.periodSessions, 0, lang)} sessions`
         : lang === "uz" ? `${formatRatio(row.periodSessions, 0, lang)} sessiyadan ${formatRatio(row.periodDetailSessions, 0, lang)} tasi bo'yicha`
         : `по ${formatRatio(row.periodDetailSessions, 0, lang)} из ${formatRatio(row.periodSessions, 0, lang)} сессий`)
      : "";
    return [label, sessions, span, bound, partial].filter(Boolean).join(" · ");
  };
  const CELL_OF = {
    last: (row) => <td className="num">{(() => { const p = marketDisplayPrice(row); return p == null ? "—" : formatMarketNumber(p, lang); })()}</td>,
    // ТЗ §2.4/§9: "отсутствие данных показывается как нулевое изменение" was
    // the defect. This cell substituted 0 whenever a close price existed, so a
    // security that has not traded since 15.07 read as "unchanged today" beside
    // securities that genuinely did not move. Measured against the trade
    // archive, seven rows showed 0 % where the last real session moved by up to
    // 20 %. No trading in this session means no change to report — the cell
    // says so, and names the day the price is actually from.
    change: (row) => (changePeriod === "1d"
      ? sessionChangeCell(row)
      : windowChangeCell(row, changePeriod)),
    change1w: (row) => windowChangeCell(row, "1w"),
    change1m: (row) => windowChangeCell(row, "1m"),
    nominal: (row) => {
      const par = parOf(row);
      return <td className="num">{par == null ? "—" : formatMarketNumber(par, lang)}</td>;
    },
    priceToPar: (row) => {
      const ratio = priceToPar(row);
      return (
        <td className="num" title={ratio == null ? undefined : (lang === "en"
          ? `price ${formatMarketNumber(marketDisplayPrice(row), lang)} · par ${formatMarketNumber(parOf(row), lang)}`
          : lang === "uz" ? `narx ${formatMarketNumber(marketDisplayPrice(row), lang)} · nominal ${formatMarketNumber(parOf(row), lang)}`
          : `цена ${formatMarketNumber(marketDisplayPrice(row), lang)} · номинал ${formatMarketNumber(parOf(row), lang)}`)}>
          {ratio == null ? "—" : `${formatRatio(ratio, 2, lang)}×`}
        </td>
      );
    },
    // Over a window `openPrice` is the period's own opening price and is
    // `undefined` when no stored session can say — which is why the fallback
    // below tests for `null` exactly: a window with no open must print a dash,
    // never today's quote under a heading that says a year.
    open: (row) => <td className="num" title={periodHint(row)}>{(() => { const v = row.openPrice !== null ? row.openPrice : marketDisplayPrice(row); return v == null ? "—" : formatMarketNumber(v, lang); })()}</td>,
    high: (row) => <td className="num" title={periodHint(row, { extremes: true })}>{(() => { const v = row.highPrice !== null ? row.highPrice : marketDisplayPrice(row); return v == null ? "—" : formatMarketNumber(v, lang); })()}</td>,
    low: (row) => <td className="num" title={periodHint(row, { extremes: true })}>{(() => { const v = row.lowPrice !== null ? row.lowPrice : marketDisplayPrice(row); return v == null ? "—" : formatMarketNumber(v, lang); })()}</td>,
    volume: (row) => (
      <td className="num" title={periodHint(row)}>
        {row.stockVolume !== null ? formatRatio(row.stockVolume, 0, lang) : "—"}
        {row.stockTradeCount !== null && <span title={periodHint(row, { detail: true })}>{formatRatio(row.stockTradeCount, 0, lang)} {tradeCountLabel(row.stockTradeCount, lang)}</span>}
      </td>
    ),
    volQty: (row) => <td className="num" title={periodHint(row)}>{row.stockQuantity !== null ? formatRatio(row.stockQuantity, 0, lang) : "—"}</td>,
    avgShare: (row) => { const v = Number.isFinite(row.avgPrice) ? row.avgPrice : avgSharePrice(row); return <td className="num" title={periodHint(row)}>{v === null || v === undefined ? neverTraded(row) : formatMarketNumber(v, lang)}</td>; },
    avgTrade: (row) => <td className="num" title={periodHint(row, { detail: true })}>{avgTradeValue(row) !== null ? formatRatio(avgTradeValue(row), 0, lang) : neverTraded(row)}</td>,
    // Over a window this is the biggest deal of the whole period, and the
    // tooltip names the session it was struck in — «крупнейшая сделка за год»
    // is a fact about one day inside the year.
    bigTrade: (row) => (
      <td className="num" title={periodHint(row, { detail: true })}>
        {row.ts && Number.isFinite(row.ts.largest_value) ? (
          <>
            {formatRatio(row.ts.largest_value, 0, lang)}
            <span>
              {Number.isFinite(row.ts.largest_qty) ? `${formatRatio(row.ts.largest_qty, 0, lang)} ${mt(lang, "tradeQtyUnit")}` : ""}
              {Number.isFinite(row.ts.largest_pct_value) ? ` · ${formatRatio(row.ts.largest_pct_value, 1, lang)}%` : ""}
            </span>
          </>
        ) : neverTraded(row)}
      </td>
    ),
    volShare: (row) => <td className="num" title={periodHint(row)}>{(() => {
      // Share of the LATEST session's turnover: an untraded security's
      // backfilled old-day volume contributes 0% of today, by definition.
      // Over a window there is no such session — `stats.boardDay` is null — and
      // the share is of the window's own total, which is the same statement one
      // period longer.
      if (stats.boardDay && marketRowDay(row) !== stats.boardDay) return `0%`;
      return Number.isFinite(row.stockVolume) && stats.totalVolume > 0 ? `${formatRatio(row.stockVolume / stats.totalVolume * 100, 2, lang)}%` : "—";
    })()}</td>,
    finRevenue: (row) => finCell(row, "revenue"),
    // Bank/insurer/fund filings have no gross-profit or operating-income
    // lines (their reporting form differs) — when the issuer's top line IS
    // published but the form carries no such line, say "not applicable"
    // instead of an ambiguous dash.
    finGross: (row) => finCell(row, "gross_profit", { naWhenTopLine: true }),
    finCash: (row) => finCell(row, "cash"),
    finLiab: (row) => finCell(row, "total_liabilities"),
    finNet: (row) => finCell(row, "net_income"),
    finOperating: (row) => finCell(row, "operating_income", { naWhenTopLine: true }),
    mktCap: (row) => <td className="num">{(() => { const v = mktCapOf(row); return v == null ? noSecLabel(row) : formatRatio(v, 0, lang); })()}</td>,
    pe: (row) => {
      const m = valuationOf(row).pe;
      if (m?.value == null || m.status === "out_of_range") return multipleCell(row, m, 2);
      // Name the earnings period on the cell: this is the one multiple whose
      // denominator can come from a different filing than the row's own figures.
      const period = m.base_period || earningsOf(row).period;
      const months = m.base_months || earningsOf(row).months;
      return (
        <td className="num" title={period ? `${lang === "ru" ? "прибыль за" : lang === "uz" ? "foyda" : "earnings for"} ${period}${months ? ` · ${months} ${lang === "ru" ? "мес." : lang === "uz" ? "oy" : "months"}` : ""}` : undefined}>
          <strong>{formatRatio(m.value, 2, lang)}×</strong>
          {(() => {
            const sub = [period, m.estimate ? mt(lang, "estimateFlag") : null]
              .filter(Boolean).join(" · ");
            return sub ? <span className="fin-cell-period">{sub}</span> : null;
          })()}
        </td>
      );
    },
    pb: (row) => multipleCell(row, valuationOf(row).pb, 2),
    ps: (row) => multipleCell(row, multiplesOf(row)?.ps, 2),
    roe: (row) => multipleCell(row, multiplesOf(row)?.roe
      ?? { value: ratioOf(row.ticker)?.roe, status: "ok" }, 1, "%"),
    roa: (row) => multipleCell(row, multiplesOf(row)?.roa
      ?? { value: ratioOf(row.ticker)?.roa, status: "ok" }, 1, "%"),
    netMargin: (row) => {
      const server = multiplesOf(row)?.net_margin;
      if (server) return multipleCell(row, server, 1, "%");
      const v = ratioOf(row.ticker)?.net_profit_margin;
      if (v != null) return <td className="num">{formatRatio(v, 1, lang)}%</td>;
      // Margin is undefined at zero revenue (e.g. the National Investment
      // Fund) — say so instead of showing an ambiguous dash.
      if (finOf(row.ticker)?.revenue === 0) return <td className="num">{naLabel()}</td>;
      return <td className="num">—</td>;
    },
    eqAssets: (row) => multipleCell(row, multiplesOf(row)?.equity_assets, 1, "%"),
    currentRatio: (row) => ratioCell(row, "current_ratio"),
    quickRatio: (row) => ratioCell(row, "quick_ratio"),
    debtAssets: (row) => ratioCell(row, "debt_ratio", { digits: 1, suffix: "%" }),
    assetTurnover: (row) => ratioCell(row, "total_asset_turnover"),
    roce: (row) => ratioCell(row, "return_to_capital_employed"),
    date: (row) => (
      <td>
        {/* The live feed reports last_trade_date=null for some securities
            that did trade — the backfilled day stats carry the real date. */}
        <strong>{row.last_trade_date || tsDate(row) || mt(lang, "noTrade")}</strong>
        {row.close_date && <span>{mt(lang, "closeDate")} {row.close_date}</span>}
      </td>
    ),
    source: (row) => (
      <td>
        {row.url ? (
          <a className="market-source-link" href={row.url} target="_blank" rel="noreferrer">{mt(lang, "source")}</a>
        ) : "—"}
      </td>
    ),
  };

  // One header row, rendered twice: in the table itself and in the pinned bar
  // (MarketStickyHead), so both carry the same sort and drag-reorder handlers.
  const headCells = [
    sortTh("ticker", mt(lang, "ticker"), { pinKey: "__ticker" }),
    sortTh("company", mt(lang, "company"), { pinKey: "__company" }),
    ...visibleOrder.map((k) => sortTh(k, LABEL_OF[k], { movable: true, num: NUM_COLS.has(k), pinKey: k })),
  ];
  const pinTicker = pinAt("__ticker");
  const pinCompany = pinAt("__company");

  return (
    <section className="market-layout">
      <article className="panel market-hero-panel">
        <div className="market-hero-copy">
          <div className="panel-label">{mt(lang, "nav")}</div>
          <h1>{mt(lang, "title")}</h1>
          <p>{mt(lang, "subtitle")}</p>
        </div>
        {/* Operator controls, not reader information: the collector's stamp and
            the manual re-pull answer "did OUR 08:00/13:00/16:10 run land", a
            question only an admin can act on. Readers get the session date on
            the board itself. */}
        {isAdmin && (
          <div className="market-hero-actions">
            {/* When WE last refreshed the board (the collector's 08:00 / 13:00 /
                16:10 runs), not when someone else's mirror refreshed its cache —
                the second is what this used to show, and it can never report our
                schedule. The mirror's stamp and the session it describes stay in
                the tooltip; the feed stamp is the fallback if the trade-stats call
                has not landed yet. */}
            <span className="status-badge muted" title={marketStampTitle(meta, lang)}>
              {mt(lang, "updated")}: {formatMarketTimestamp(meta?.refreshed_at || meta?.updated_at, lang)}
            </span>
            <button className="ghost-btn" type="button" onClick={onRefresh} disabled={loading}>
              {loading ? mt(lang, "loading") : mt(lang, "refresh")}
            </button>
          </div>
        )}
      </article>

      {/* The FX strip and summary cards provide context for the visual map, but
          duplicate information available in the market table. Keep this block
          on the dedicated heatmap page only. */}
      {viewMode === "heatmap" && (
        <>
          <FxRatesBar language={lang} onOpenBanks={onOpenBankFx} />

          {/* The sector control that scopes these four cards is further down the
              page, in the filter bar — so the row has to say for itself which
              sector it is answering for, and offer the way back. Without this the
              numbers change under a control the reader cannot see from here. */}
          {cardSector && (
            <div className="market-stats-scope">
              <span className="market-stats-scope-label">
                {lang === "en" ? "Sector" : lang === "uz" ? "Tarmoq" : "Категория"}:
              </span>
              <button type="button" className="market-stats-scope-chip" onClick={() => setMarketSector(null)}>
                {sectorLabel(lang, cardSector)}
                <span aria-hidden="true">×</span>
              </button>
            </div>
          )}

          <div className="market-stats-grid">
        {/* Инструментов / Сделки сегодня / Без изменений were removed at the
            customer's request (2026-08-12) — the row keeps only the counters
            that name a mover or a sum of money. Up and down belong to one market
            breadth reading, so they share a card and a proportional rail. */}
        <MarketBreadthCard
          language={lang}
          advancers={cardStats.advancers}
          decliners={cardStats.decliners}
          topGrowth={formatLeader(cardStats.topGrowth)}
          topDrop={formatLeader(cardStats.topDrop)} />
        {/* ТЗ §8: the market's capitalisation is its ACTIVE SHARES. The client
            sum counted bonds, which carry no ownership, and dormant listings —
            23 of them, 29 088 bn — inside a figure labelled "the market". The
            server now answers with the total and with what it left out. */}
        {(() => {
          // Whole board: the server's own figure, because only it can say what it
          // left out. Under a sector chip there is no server answer to ask for, so
          // the sum comes from that sector's active rows — the same pool the three
          // counters beside it use — and the note counts what it left out of THEM.
          const server = cardSector ? null : marketSummary?.market_cap;
          const value = server?.value ?? cardStats.totalMarketCap;
          if (!(value > 0)) return null;
          let sub = "UZS";
          if (server) {
            const ex = server.excluded || {};
            const excludedNote = [
              ex.bonds?.instruments ? `${lang === "ru" ? "облигации" : lang === "uz" ? "obligatsiyalar" : "bonds"} — ${ex.bonds.instruments}` : null,
              ex.inactive_listings?.instruments ? `${lang === "ru" ? "неактивные" : lang === "uz" ? "faol emas" : "inactive"} — ${ex.inactive_listings.instruments}` : null,
            ].filter(Boolean).join(", ");
            if (excludedNote) sub = `UZS · ${lang === "ru" ? "исключено" : lang === "uz" ? "hisobdan chiqarilgan" : "excluded"}: ${excludedNote}`;
          } else if (sectorDormant) {
            // Its own sentence, not the market note's list with one item left in
            // it: «без облигации: 17, неактивные: 10» works as an enumeration
            // after «без», «без неактивные: 10» on its own does not.
            sub = `UZS · ${lang === "ru" ? "без неактивных" : lang === "uz" ? "faol emaslarsiz" : "excl. inactive"}: ${sectorDormant}`;
          }
          if (Number.isFinite(capPeriodChange)) {
            // The period the reader chose, spelled out beside its own number:
            // the card is read without the period control in view.
            sub = `${sub} · ${changePeriodLabel(changePeriod, lang, "short")}: ${
              capPeriodChange > 0 ? "+" : ""}${formatRatio(capPeriodChange, 2, lang)}%`;
          }
          return (
            <MarketStatCard
              label={mt(lang, "marketCap")}
              value={formatCompactVolume(value, lang)}
              sub={sub}
              kind="capitalization" />
          );
        })()}
        {/* The day's turnover is the sum of the rows below it, not a separate
            feed's idea of the day: the mirror's /trades snapshot covers a fixed
            44 securities and called 31.07 "120,7 млн over ~900 trades" while the
            board it sits above listed 1,56 млрд over 6 507 — and it cannot
            answer per tab, so the shares view was quoting bond turnover too. */}
        {cardStats.totalVolume > 0 && <MarketStatCard label={windowed ? `${mt(lang, "volume")} · ${changePeriodLabel(changePeriod, lang, "short")}` : mt(lang, "volume")} termId="volume" lang={lang} value={formatCompactVolume(cardStats.totalVolume, lang)} sub={cardStats.totalTrades ? `${formatRatio(cardStats.totalTrades, 0, lang)} ${tradeCountLabel(cardStats.totalTrades, lang)}` : null} kind="turnover" />}
          </div>
        </>
      )}

      {/* Three readings of one session: who moved, and who was actually
          tradeable. Ликвидность answers the question the two percent lists
          cannot — a +20 % on one 37 200-сум trade is a move, not a market —
          and it reads off the same «Объём» (turnover in money) the column, the
          turnover card and the charts already mean — in the same compact form
          those use, so the figure is recognisable without a unit spelled out
          beside it (one was tried in the head and the customer had it out). */}
      {viewMode === "table"
        && (periodMovers.topGainers.length > 0 || periodMovers.topLosers.length > 0 || periodMovers.topVolume.length > 0) && (
        <div className="market-top-movers">
          {[
            // The two change panels carry the selected period in their heading:
            // «Топ роста» over a month and over a session are different claims,
            // and the strip is read at a glance without the control in view.
            { key: "up", title: `${mt(lang, "topGainers")}${changePeriod === "1d" ? "" : ` · ${changePeriodLabel(changePeriod, lang, "short")}`}`,
              rows: periodMovers.topGainers,
              value: (r) => `+${formatRatio(changePeriod === "1d" ? r.changePercent : r.periodPct, 2, lang)}%` },
            { key: "down", title: `${mt(lang, "topLosers")}${changePeriod === "1d" ? "" : ` · ${changePeriodLabel(changePeriod, lang, "short")}`}`,
              rows: periodMovers.topLosers,
              value: (r) => `${formatRatio(changePeriod === "1d" ? r.changePercent : r.periodPct, 2, lang)}%` },
            // Ликвидность carries the period too, and over a window it says how
            // many sessions it added up and from which one: «5,6 млрд» over six
            // months means one thing across 80 sessions and quite another across
            // three, and the panel is read without the control in view.
            { key: "vol", title: `${mt(lang, "topLiquidity")}${changePeriod === "1d" ? "" : ` · ${changePeriodLabel(changePeriod, lang, "short")}`}`,
              rows: periodMovers.topVolume,
              value: (r) => formatCompactVolume(changePeriod === "1d" ? r.stockVolume : r.periodVolume, lang),
              hint: (r) => {
                if (changePeriod === "1d" || !r.periodSessions) return undefined;
                const from = String(r.periodFrom || "");
                const pretty = from.length === 8 ? `${from.slice(6)}.${from.slice(4, 6)}.${from.slice(0, 4)}` : from;
                const sessions = `${formatRatio(r.periodSessions, 0, lang)} ${sessionCountLabel(r.periodSessions, lang)}`;
                return pretty
                  ? `${sessions} ${lang === "en" ? "since" : lang === "uz" ? "boshlab" : "с"} ${pretty}`
                  : sessions;
              } },
          ].map((col) => (
            <article className={`market-movers-col ${col.key}`} key={col.key}>
              <div className="market-movers-head">
                <span className={`market-movers-dot ${col.key}`} />
                <h3>{col.title}</h3>
              </div>
              <ul className="market-movers-list">
                {col.rows.length ? col.rows.map((r, index) => (
                  <li key={r.ticker}>
                    <button
                      type="button"
                      className="market-movers-item"
                      title={col.hint ? col.hint(r) : undefined}
                      onClick={() => onOpenCompany ? onOpenCompany(r.ticker) : onAnalyze(r.ticker)}
                    >
                      <span className="market-movers-rank" aria-hidden="true">
                        {String(index + 1).padStart(2, "0")}
                      </span>
                      <span className="market-movers-tk">
                        <CompanyLogo logo={smap[r.ticker]?.logo_url} name={r.name || r.ticker} ticker={r.ticker} />
                        <span className="market-movers-name">{r.ticker}</span>
                      </span>
                      <span className={`market-movers-chg ${col.key}`}>{col.value(r)}</span>
                    </button>
                  </li>
                )) : <li className="market-movers-empty">—</li>}
              </ul>
            </article>
          ))}
        </div>
      )}

      <article className="panel market-board">
        <div className="market-board-head">
          <div>
            <div className="panel-label">{viewMode === "heatmap" ? (lang === "en" ? "Market Map" : lang === "uz" ? "Bozor xaritasi" : "Карта рынка") : mt(lang, "tableTitle")}</div>
            <h2>{viewMode === "heatmap" ? (lang === "en" ? "Market Map" : lang === "uz" ? "Bozor xaritasi" : "Карта рынка") : mt(lang, "tableTitle")}</h2>
          </div>
          <div className="market-board-head-right">
            {(windowed || stats.boardDay) && (
              <span className="market-session-date">
                {windowed
                  ? changePeriodLabel(changePeriod, lang, "label")
                  : `${stats.boardDay.slice(6, 8)}.${stats.boardDay.slice(4, 6)}.${stats.boardDay.slice(0, 4)}`}
              </span>
            )}
            <div className="market-view-toggle">
              <button
                type="button"
                className={viewMode === "table" ? "active" : ""}
                onClick={() => setViewMode("table")}
                title={lang === "en" ? "Table view" : lang === "uz" ? "Jadval ko'rinishi" : "Таблица"}
              >
                <svg width="15" height="15" viewBox="0 0 15 15" fill="currentColor">
                  <rect x="1" y="2" width="13" height="1.8" rx="0.9"/>
                  <rect x="1" y="6.6" width="13" height="1.8" rx="0.9"/>
                  <rect x="1" y="11.2" width="13" height="1.8" rx="0.9"/>
                </svg>
                <span>{lang === "en" ? "Table" : lang === "uz" ? "Jadval" : "Таблица"}</span>
              </button>
              <button
                type="button"
                className={viewMode === "heatmap" ? "active" : ""}
                onClick={() => setViewMode("heatmap")}
                title={lang === "en" ? "Market map" : lang === "uz" ? "Bozor xaritasi" : "Карта рынка"}
              >
                <svg width="15" height="15" viewBox="0 0 15 15" fill="currentColor">
                  <rect x="1" y="1" width="5.8" height="5.8" rx="1.2"/>
                  <rect x="8.2" y="1" width="5.8" height="5.8" rx="1.2"/>
                  <rect x="1" y="8.2" width="5.8" height="5.8" rx="1.2"/>
                  <rect x="8.2" y="8.2" width="5.8" height="5.8" rx="1.2"/>
                </svg>
                <span>{lang === "en" ? "Map" : lang === "uz" ? "Xarita" : "Карта"}</span>
              </button>
            </div>
            {viewMode === "table" && (
              <span className="status-badge muted">{mt(lang, "showing")}: {visibleRows.length}/{prepared.length}</span>
            )}
          </div>
        </div>

        {/* Every filter the board has — instrument class, share class, favourites,
            search, the column picker and the sector chips — lives in one block so
            it can stick under the topbar as a unit. Scrolling to row 300 must not
            cost the reader the controls that put those rows on screen. */}
        <div className="market-filterbar">
        <div className="market-controls">
          {/* Level 1: instrument class — stocks vs bonds are not comparable
              (price/capitalisation vs coupon/maturity), so they never share a table. */}
          <div className="market-type-levels">
            <div className="segmented-control market-type-control">
              {[
                ["stock", mt(lang, "stocks")],
                ["bond", mt(lang, "bonds")],
              ].map(([value, label]) => {
                const active = value === "bond" ? type === "bond" : type !== "bond";
                return (
                  <button key={value} type="button" className={active ? "active" : ""} onClick={() => onTypeChange(value)}>
                    {label}
                  </button>
                );
              })}
            </div>
            {/* MAIN | NEGO — the exchange's own two boards, side by side with the
                instrument class because that is the same kind of choice: which
                market you are looking at, not which slice of one. The count says
                how many lines had a negotiated deal, so an empty NEGO board
                reads as «none today» rather than as a broken page. */}
            <div className="segmented-control market-segment-control"
              role="group"
              aria-label={lang === "en" ? "Market board" : lang === "uz" ? "Bozor" : "Рынок"}>
              {[["main", lang === "en" ? "Main" : lang === "uz" ? "Asosiy" : "Основной"],
                ["nego", lang === "en" ? "Negotiated" : lang === "uz" ? "Kelishilgan" : "Переговорный"]]
                .map(([value, label]) => (
                  <button key={value} type="button"
                    className={segment === value ? "active" : ""}
                    aria-pressed={segment === value}
                    onClick={() => setSegment(value)}
                    title={value === "main"
                      ? (lang === "en" ? "The auction session (board G1)"
                         : lang === "uz" ? "Auksion sessiyasi (G1)" : "Аукционная сессия (борд G1)")
                      : (lang === "en" ? "Negotiated deals, struck bilaterally (board T1)"
                         : lang === "uz" ? "Kelishilgan bitimlar (T1)" : "Переговорные сделки, вне сессии (борд T1)")}>
                    {label}
                    {value === "nego" && negotiatedCount > 0 ? ` (${negotiatedCount})` : ""}
                  </button>
                ))}
            </div>
            {/* Level 2: share class — only meaningful inside stocks. */}
            {type !== "bond" && (
              <div className="segmented-control market-subtype-control">
                {[
                  ["stock", mt(lang, "all")],
                  ["ordinary", mt(lang, "ordinaryStocks")],
                  ["preferred", mt(lang, "preferredStocks")],
                ].map(([value, label]) => (
                  <button key={value} type="button" className={type === value ? "active" : ""} onClick={() => onTypeChange(value)}>
                    {label}
                  </button>
                ))}
              </div>
            )}
          </div>
          {/* Отрасль. A dropdown rather than the row of chips this used to be:
              eleven chips took a band of the pinned bar to themselves, wrapped
              onto two lines on a laptop, and — because the band was drawn for
              the table only — the map had no sector control at all. One list,
              one answer, both views. */}
          {presentSectors.length > 1 && (
            <label className="market-sector-select">
              <select
                value={activeSector || ""}
                data-all={activeSector ? undefined : "1"}
                onChange={(event) => setMarketSector(event.target.value || null)}
                aria-label={sectorWord}
                title={lang === "en" ? "Show one sector only"
                  : lang === "uz" ? "Faqat bitta sohani ko'rsatish"
                  : "Показать только одну отрасль"}
              >
                <option value="">{`${sectorWord}: ${sectorLabel(lang, "all").toLowerCase()}`}</option>
                {presentSectors.map((s) => (
                  <option key={s} value={s}>{sectorLabel(lang, s)}</option>
                ))}
              </select>
            </label>
          )}
          {viewMode === "table" && (
            <button
              type="button"
              className={`market-fav-filter ${favOnly ? "active" : ""}`}
              aria-pressed={favOnly}
              onClick={() => setFavOnly((v) => !v)}
              title={lang === "en" ? "Show favorites only" : lang === "uz" ? "Faqat tanlanganlar" : "Только избранное"}
            >
              <span className="fav-star">{favOnly ? "★" : "☆"}</span>
              <span className="market-btn-label">{lang === "en" ? "Favorites" : lang === "uz" ? "Tanlanganlar" : "Избранное"}</span>
            </button>
          )}
          {/* ТЗ §4: dormant listings are hidden, not dropped — the count says
              how many, so their absence is a stated fact rather than a silence,
              and the chip shows exactly those rows. Table only: the map has
              nothing to draw for a security with no session (see `mapRows`), so
              offering the switch there would be offering eleven empty squares. */}
          {viewMode === "table" && dormantCount > 0 && (
            <button
              type="button"
              className={`market-fav-filter market-dormant-filter ${inactiveOnly ? "active" : ""}`}
              aria-pressed={inactiveOnly}
              onClick={() => setInactiveOnly((v) => !v)}
              title={inactiveOnly
                ? (lang === "en" ? "Back to the traded board"
                   : lang === "uz" ? "Savdodagi ro'yxatga qaytish" : "Вернуться к торгуемым")
                : (lang === "en" ? `Show the ${dormantCount} listings with no trades for 90 days`
                   : lang === "uz" ? `90 kun bitimsiz ${dormantCount} qog'ozni ko'rsatish`
                   : `Показать ${dormantCount} бумаг без сделок более 90 дней`)}
            >
              <span className="market-btn-label">
                {lang === "en" ? "Inactive" : lang === "uz" ? "Faol emas" : "Неактивные"}
                {` (${dormantCount})`}
              </span>
            </button>
          )}
          {viewMode === "table" && (
            <label className="market-search">
              <input value={query} onChange={(event) => onQueryChange(event.target.value)} placeholder={mt(lang, "search")} />
            </label>
          )}
          {viewMode === "table" && (
            <button type="button" className="market-fav-filter market-export-btn" onClick={exportCsv} title={mt(lang, "exportCsv")}>
              <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><path d="M7 10l5 5 5-5"/><path d="M12 15V3"/></svg>
              <span className="market-btn-label">{mt(lang, "exportCsv")}</span>
            </button>
          )}
          {viewMode === "table" && (
            <div className="market-cols-wrap">
              <button
                type="button"
                ref={colsBtnRef}
                className={`market-cols-btn ${colsOpen ? "active" : ""}`}
                aria-haspopup="true" aria-expanded={colsOpen}
                onClick={() => setColsOpen((o) => !o)}
                title={lang === "en"
                  ? "Choose which columns the table shows"
                  : lang === "uz" ? "Jadval ustunlarini tanlash"
                  : "Выбрать колонки таблицы"}
              >
                <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/></svg>
                {/* Named, like every other button in this bar. A bare gear beside
                    «Избранное», «Неактивные» and «Экспорт CSV» read as an
                    afterthought and was the one control a reader had to guess at —
                    which is how a board with fifteen hidden columns looks like a
                    board that has none. The count says how many are on. */}
                <span className="market-btn-label">
                  {lang === "en" ? "Columns" : lang === "uz" ? "Ustunlar" : "Колонки"}
                  <span className="market-cols-count">{shownOrder.length}</span>
                </span>
              </button>
              {colsOpen && (
                <MarketColsPopover
                  anchorRef={colsBtnRef}
                  onClose={() => setColsOpen(false)}
                  title={lang === "en" ? "Columns" : lang === "uz" ? "Ustunlar" : "Колонки"}
                  closeLabel={lang === "en" ? "Close" : lang === "uz" ? "Yopish" : "Закрыть"}
                >
                  <>
                    <div className="market-cols-search">
                      <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="11" cy="11" r="7"/><path d="m21 21-4.3-4.3"/></svg>
                      <input
                        type="text"
                        value={colsSearch}
                        onChange={(e) => setColsSearch(e.target.value)}
                        placeholder={lang === "en" ? "Search" : lang === "uz" ? "Qidirish" : "Поиск"}
                      />
                    </div>
                    {/* Its own scrollport: the groups scroll here, the search box
                        and the reset footer stay put, and `overscroll-behavior`
                        (CSS) stops the page behind from taking over the gesture. */}
                    <div className="market-cols-body">
                    {(() => {
                      const q = colsSearch.trim().toLowerCase();
                      const matches = (label) => !q || label.toLowerCase().includes(q);
                      const anyMatch = CORE_COLS.some(([, l]) => matches(l)) || MARKET_COLS.some(([, l]) => matches(l));
                      if (!anyMatch) {
                        return <div className="market-cols-empty">{lang === "en" ? "Nothing found" : lang === "uz" ? "Hech narsa topilmadi" : "Ничего не найдено"}</div>;
                      }
                      return (
                        <>
                          {!q && (
                            <div className="market-cols-group">
                              <div className="market-cols-group-body">
                                {CORE_COLS.map(([k, label]) => (
                                  <label key={k} className="market-cols-row market-cols-row-locked">
                                    <input type="checkbox" checked disabled readOnly />
                                    <span>{label}</span>
                                    {/* Same ⓘ as the column header: this panel is where a
                                        reader decides whether a column is worth its width,
                                        which is exactly when they need to know what it
                                        means — before it is on screen to be hovered. */}
                                    <TermInfo termId={k} lang={lang} label={label} />
                                  </label>
                                ))}
                              </div>
                            </div>
                          )}
                          {COL_GROUPS.map((group) => {
                            const cols = group.cols.filter(([, label]) => matches(label));
                            if (!cols.length) return null;
                            const open = q ? true : openGroups.has(group.key);
                            const allOn = group.cols.every(([k]) => visibleCols.has(k));
                            const someOn = group.cols.some(([k]) => visibleCols.has(k));
                            const shownInGroup = group.cols.filter(([k]) => visibleCols.has(k)).length;
                            const setGroupAll = () => setVisibleCols((prev) => {
                              const n = new Set(prev);
                              group.cols.forEach(([k]) => { if (allOn) n.delete(k); else n.add(k); });
                              return n;
                            });
                            return (
                              <div className="market-cols-group" key={group.key}>
                                <button
                                  type="button"
                                  className="market-cols-group-head"
                                  onClick={() => toggleGroup(group.key)}
                                  aria-expanded={open}
                                >
                                  <span className="market-cols-group-title">{group.title}</span>
                                  <span className="market-cols-group-meta">
                                    <span className="market-cols-group-badge">{shownInGroup}</span>
                                    <span className={`market-cols-group-chevron${open ? " open" : ""}`}>›</span>
                                  </span>
                                </button>
                                {open && (
                                  <div className="market-cols-group-body">
                                    {!q && (
                                      <label className="market-cols-row market-cols-all">
                                        <input
                                          type="checkbox"
                                          checked={allOn}
                                          ref={(el) => { if (el) el.indeterminate = someOn && !allOn; }}
                                          onChange={setGroupAll}
                                        />
                                        <span>{lang === "en" ? "All" : lang === "uz" ? "Hammasi" : "Все"}</span>
                                      </label>
                                    )}
                                    {cols.map(([k, label]) => (
                                      <label key={k} className="market-cols-row">
                                        <input
                                          type="checkbox"
                                          checked={visibleCols.has(k)}
                                          onChange={() => toggleCol(k)}
                                        />
                                        <span>{label}</span>
                                        {/* The picker's column key IS the glossary id, so the
                                            row asks for its own definition. A column that is
                                            not an economic term (Источник) renders no marker.
                                            The ⓘ is a <button>: per the HTML spec a label does
                                            not activate for events aimed at interactive
                                            descendants, so asking what P/E means does not
                                            toggle the P/E column. */}
                                        <TermInfo termId={k} lang={lang} label={label} />
                                      </label>
                                    ))}
                                  </div>
                                )}
                              </div>
                            );
                          })}
                        </>
                      );
                    })()}
                    </div>
                    <div className="market-cols-footer">
                      {/* The two things the headers do that a header does not look
                          like it does. This panel is where a reader comes looking
                          for table controls, so both are stated here as well. */}
                      <span className="market-cols-hint">
                        <span>{lang === "en" ? "Drag column headers to reorder" : lang === "uz" ? "Tartib uchun sarlavhalarni torting" : "Перетаскивайте заголовки для порядка"}</span>
                        <span>{coarsePointer
                          ? (lang === "en" ? "Press and hold a header to sort by two columns"
                            : lang === "uz" ? "Ikki ustun bo‘yicha saralash — sarlavhani uzoq bosing"
                            : "Долгое нажатие — сортировка по двум колонкам")
                          : (lang === "en" ? "Shift + click to sort by two columns"
                            : lang === "uz" ? "Shift + bosish — ikki ustun bo‘yicha saralash"
                            : "Shift + клик — сортировка по двум колонкам")}</span>
                      </span>
                      <button type="button" className="market-cols-reset" onClick={resetColOrder}>
                        {lang === "en" ? "Reset order" : lang === "uz" ? "Tartibni tiklash" : "Сбросить порядок"}
                      </button>
                    </div>
                  </>
                </MarketColsPopover>
              )}
            </div>
          )}
        </div>

          {/* The period every «изменение» on this screen is measured over. It
            moves the «Изм.» column, the movers strip and the map together —
            one question, one answer. The two fixed 1Н/1М columns stay where
            they are; a reader can still have all three on screen. */}
        <div className="market-period-row">
        <span className="market-period-label">
          {lang === "en" ? "Change over" : lang === "uz" ? "O'zgarish davri" : "Изменение за"}
        </span>
        <div className="segmented-control market-period-control"
          role="group"
          aria-label={lang === "en" ? "Change period" : lang === "uz" ? "O'zgarish davri" : "Период изменения"}>
          {CHANGE_PERIODS.map((p) => (
            <button
              key={p.code}
              type="button"
              className={changePeriod === p.code ? "active" : ""}
              aria-pressed={changePeriod === p.code}
              onClick={() => setChangePeriod(p.code)}
              title={lang === "en" ? `Change over ${changePeriodLabel(p.code, lang)}`
                : lang === "uz" ? `${changePeriodLabel(p.code, lang)} o'zgarishi`
                : `Изменение за ${changePeriodLabel(p.code, lang).toLowerCase()}`}
            >
              {p.code === "1d"
                ? (lang === "en" ? "Session" : lang === "uz" ? "Sessiya" : "Сессия")
                : p.code === "ytd" ? "YTD" : changePeriodLabel(p.code, lang)}
            </button>
          ))}
        </div>
        </div>

        {/* A sort built from two headers is invisible once you scroll — the carets
            are off in the columns that made it. Spell the chain out, in order, with
            one control back to the board's default order.

            It shows from the FIRST sorted column, not the second, for two reasons:
            until now a header click could never be undone (there was no way back to
            "latest session first"), and one sorted column is exactly the moment the
            reader is ready to be told a second one can be added. */}
        {viewMode === "table" && sortKeys.length > 0 && (
          <div className="market-sort-chain">
            <span className="market-sort-chain-label">
              {lang === "en" ? "Sorted by" : lang === "uz" ? "Saralash" : "Сортировка"}:
            </span>
            {sortKeys.map(({ key, dir }, i) => (
              <button
                key={key}
                type="button"
                className="market-sort-chain-chip"
                onClick={() => onSort(key, true)}
                title={lang === "en" ? "Click to flip, again to remove"
                  : lang === "uz" ? "Yoʻnalishni almashtirish uchun bosing, olib tashlash uchun yana bosing"
                  : "Клик — сменить направление, ещё раз — убрать"}
              >
                {sortKeys.length > 1 && <span className="market-sort-chain-rank">{i + 1}</span>}
                <span>{SORT_LABEL_OF[key] || key}</span>
                <span className="market-sort-caret">{dir === "asc" ? "▲" : "▼"}</span>
              </button>
            ))}
            {sortKeys.length === 1 && !sortHintSeen && (
              <span className="market-sort-teach">
                {coarsePointer ? (
                  lang === "en" ? <>press and hold another column to sort by <b>two</b></>
                    : lang === "uz" ? <>ikkinchi kalit uchun boshqa ustunni <b>uzoq bosing</b></>
                    : <>удерживайте другую колонку, чтобы сортировать по <b>двум</b></>
                ) : (
                  lang === "en" ? <><kbd>Shift</kbd> + click another column to sort by <b>two</b></>
                    : lang === "uz" ? <><kbd>Shift</kbd> + boshqa ustunni bosing — <b>ikkita</b> kalit</>
                    : <><kbd>Shift</kbd> + клик по другой колонке — сортировка по <b>двум</b></>
                )}
                <button
                  type="button"
                  className="market-sort-teach-close"
                  onClick={dismissSortHint}
                  aria-label={lang === "en" ? "Got it" : lang === "uz" ? "Tushunarli" : "Понятно"}
                  title={lang === "en" ? "Got it" : lang === "uz" ? "Tushunarli" : "Понятно"}
                >×</button>
              </span>
            )}
            <button type="button" className="market-sort-chain-reset" onClick={clearSort}>
              {lang === "en" ? "Reset" : lang === "uz" ? "Tiklash" : "Сбросить"}
            </button>
          </div>
        )}
        </div>

        {/* ТЗ Дополнение 1 §А.2: bonds get their own table, not a row in the
            equity board — an issue has a value rather than a capitalisation, and
            no earnings for a multiple to divide by. The «Облигации» segment IS
            the bond section: screener + yield map, a row opens /bond/{T}. */}
        {viewMode === "table" && type === "bond" ? (
          <BondsView language={lang} onOpenBond={onOpenBond || onAnalyze} embedded />
        ) : viewMode === "heatmap" ? (
          loading ? (
            <p className="market-empty-cell">{mt(lang, "loading")}</p>
          ) : (
            <MarketHeatmap rows={sectorMapRows} companies={companies} securitiesMap={smap} language={lang} onAnalyze={onAnalyze} onOpenCompany={onOpenCompany} type={type} mapData={mapData} period={changePeriod} />
          )
        ) : (
          <>
          {/* What the reader is now looking at, and why these rows do not
              behave like the rest of the board: the price is a close from
              months ago carried forward, the day's change is nil because there
              was no day, and the server leaves them out of the market's
              capitalisation. Without this the eleven rows look like eleven
              securities that all happened to close flat. */}
          {inactiveOnly && (
            <p className="market-dormant-note">
              {lang === "en"
                ? "Listings with no trades for over 90 days. The price is their last settled close, carried forward — there is no day's move, and the market capitalisation above leaves them out."
                : lang === "uz"
                  ? "90 kundan ortiq bitimsiz qog'ozlar. Narx — ularning oxirgi yopilishi, oldinga ko'chirilgan; kunlik o'zgarish yo'q va yuqoridagi kapitalizatsiya ularni hisobga olmaydi."
                  : "Бумаги без сделок более 90 дней. Цена — их последнее закрытие, перенесённое вперёд: дневного изменения нет, и в капитализацию рынка выше они не входят."}
            </p>
          )}
          {/* The NEGO board's own contract, stated where it is read: which
              columns are negotiated figures, which are still the session's, and
              why the two are never added together. */}
          {segment === "nego" && (
            <p className="market-dormant-note">
              {lang === "en"
                ? "Negotiated deals (exchange board T1) — struck bilaterally at an agreed price, outside the auction. Turnover, quantity, trades and the average price are the negotiated ones; the quote, the day's change and the OHLC remain the auction session's, because a negotiated price is not a quote. The exchange's own bulletin excludes these deals from the session, and so does the Main board."
                : lang === "uz"
                  ? "Kelishilgan bitimlar (T1 bordi) — auksiondan tashqari, kelishilgan narxda. Aylanma, hajm, bitimlar soni va o'rtacha narx — kelishilgan; kotirovka, kunlik o'zgarish va OHLC — auksion sessiyasining, chunki kelishilgan narx kotirovka emas."
                  : "Переговорные сделки (борд T1) — заключены двусторонне по согласованной цене, вне аукциона. Оборот, количество, число сделок и средняя цена — переговорные; котировка, дневное изменение и OHLC остаются аукционными, потому что переговорная цена не является котировкой. Бюллетень биржи не включает эти сделки в сессию — и «Основной» рынок здесь тоже."}
            </p>
          )}
          {segment === "nego" && negotiatedCount === 0 && !loading && (
            <p className="market-dormant-note">
              {lang === "en"
                ? `No negotiated deals on record for the securities on this board.${
                    negotiatedAnywhere ? ` The exchange's statistics hold ${negotiatedAnywhere} for other instruments — most of them bonds, which have their own section.` : ""}`
                : lang === "uz"
                  ? `Bu ro'yxatdagi qog'ozlar bo'yicha kelishilgan bitimlar yo'q.${
                      negotiatedAnywhere ? ` Boshqa instrumentlar bo'yicha — ${negotiatedAnywhere}, asosan obligatsiyalar.` : ""}`
                  : `По бумагам этого раздела переговорных сделок не зафиксировано.${
                      negotiatedAnywhere ? ` В статистике биржи их ${negotiatedAnywhere} по другим инструментам — в основном по облигациям, у которых свой раздел.` : ""}`}
            </p>
          )}
          <div className="market-table-wrap" ref={wrapRef}>
            <table className="market-table">
              <thead>
                <tr>{headCells}</tr>
              </thead>
              <tbody>
                {loading ? (
                  <tr><td colSpan={colSpan} className="market-empty-cell">{mt(lang, "loading")}</td></tr>
                ) : visibleRows.length ? (
                  visibleRows.map((row) => {
                    const sec = smap[row.ticker] || {};
                    const logo = sec.logo_url;
                    const isPreferred = sec.is_preferred || row.share_type === "preferred";
                    const isFav = hasFav(row.ticker);
                    return (
                    <tr key={`${row.ticker}-${row.isin}`}>
                      <td className={`market-ticker-cell${pinCls(pinTicker)}`} style={pinTicker ? { left: pinTicker.left } : undefined}>
                        <button
                          type="button"
                          className={`market-fav-btn ${isFav ? "is-fav" : ""}`}
                          aria-pressed={isFav}
                          title={isFav
                            ? (lang === "en" ? "Remove from favorites" : lang === "uz" ? "Tanlanganlardan olib tashlash" : "Убрать из избранного")
                            : (lang === "en" ? "Add to favorites" : lang === "uz" ? "Tanlanganlarga qo'shish" : "В избранное")}
                          onClick={(e) => { e.stopPropagation(); onToggleFavorite && onToggleFavorite(row.ticker, row.name); }}
                        >
                          {isFav ? "★" : "☆"}
                        </button>
                        <CompanyLogo logo={logo} name={row.name || row.ticker} ticker={row.ticker} />
                        <div className="market-ticker-info">
                          <button type="button" className="market-ticker-btn" onClick={() => onOpenCompany ? onOpenCompany(row.ticker) : onAnalyze(row.ticker)}>
                            {row.ticker || "—"}
                          </button>
                          <span>{(row.type === "bond" || sec.type === "bond")
                            ? mt(lang, "bondOne")
                            : isPreferred ? mt(lang, "preferred")
                            : row.share_type ? mt(lang, row.share_type)
                            : (row.type || "—")}</span>
                        </div>
                        <button
                          type="button"
                          className="market-info-btn"
                          title={lang === "en" ? "Company info" : lang === "uz" ? "Kompaniya ma'lumoti" : "О компании"}
                          onClick={() => openPanel(row.ticker)}
                        >ℹ</button>
                      </td>
                      <td className={pinCls(pinCompany).trim() || undefined} style={pinCompany ? { left: pinCompany.left } : undefined}>
                        <button type="button" className="market-company-name-btn" onClick={() => onOpenCompany && onOpenCompany(row.ticker)}>
                          {row.name || sec.name || "—"}
                        </button>
                        <span>{row.isin || "—"}</span>
                      </td>
                      {visibleOrder.map((k) => {
                        const cell = CELL_OF[k](row);
                        const pin = pinAt(k);
                        if (!pin) return React.cloneElement(cell, { key: k });
                        return React.cloneElement(cell, {
                          key: k,
                          className: `${cell.props.className || ""}${pinCls(pin)}`.trim(),
                          style: { ...(cell.props.style || {}), left: pin.left },
                        });
                      })}
                    </tr>
                    );
                  })
                ) : (
                  <tr><td colSpan={colSpan} className="market-empty-cell">{favOnly
                    ? (lang === "en" ? "No favorites yet — tap ☆ next to a company to track it."
                       : lang === "uz" ? "Hali tanlanganlar yo'q — kuzatish uchun kompaniya yonidagi ☆ ni bosing."
                       : "Пока нет избранного — нажмите ☆ рядом с компанией, чтобы следить за ней.")
                    : inactiveOnly
                      ? (lang === "en" ? "No dormant listing matches the current filters."
                         : lang === "uz" ? "Joriy filtrlarga mos keladigan faol bo'lmagan qog'oz yo'q."
                         : "Под текущие фильтры не попала ни одна неактивная бумага.")
                      : mt(lang, "empty")}</td></tr>
                )}
              </tbody>
            </table>
          </div>
          <MarketStickyHead
            wrapRef={wrapRef}
            cells={headCells}
            colSignature={visibleOrder.join("|")}
            rowCount={visibleRows.length}
            loading={loading}
          />
          <MarketFloatScroll
            wrapRef={wrapRef}
            colSignature={visibleOrder.join("|")}
            rowCount={visibleRows.length}
            loading={loading}
          />
          {colMenu && visibleOrder.includes(colMenu.key) && (() => {
            const key = colMenu.key;
            const group = colGroupOf(key);
            const i = group.indexOf(key);
            return (
              <MarketColMenu
                colKey={key}
                fromSticky={colMenu.fromSticky}
                lang={lang}
                state={{
                  dir: sortDirOf(key),
                  pinned: pinnedCols.has(key),
                  canLeft: i > 0,
                  canRight: i >= 0 && i < group.length - 1,
                  // "Последняя" is a core column: the picker keeps it locked too.
                  canHide: key !== "last",
                }}
                actions={{
                  sort: (dir) => setSortKeys([{ key, dir }]),
                  move: (step) => moveColBy(key, step),
                  pin: () => togglePin(key),
                  hide: () => { toggleCol(key); setColMenu(null); },
                }}
                onClose={closeColMenu}
              />
            );
          })()}
          </>
        )}
      </article>

      {panelTicker && (
        <CompanyInfoPanel
          ticker={panelTicker}
          secInfo={smap[panelTicker]}
          wikiInfo={panelWiki}
          language={language}
          onClose={() => { setPanelTicker(null); setPanelWiki(null); }}
          loading={panelWikiLoading}
        />
      )}
    </section>
  );
}

// ---------------------------------------------------------------------------
// CatalogView helpers
// ---------------------------------------------------------------------------

function PriceSparkline({ points, language }) {
  const [activeIndex, setActiveIndex] = useState(null);
  if (!points || points.length < 2) return null;
  // The stored endpoint can contain rows in either query order. A chart must
  // always read from the earlier session to the later one; otherwise both the
  // line and its date caption tell the story backwards.
  const ordered = points
    .filter((p) => p?.close != null && p.close > 0)
    .slice()
    .sort((a, b) => String(a.date || "").localeCompare(String(b.date || "")));
  const closes = ordered.map((p) => Number(p.close));
  if (closes.length < 2) return null;
  const W = 360, H = 82, PAD = 5;
  const min = Math.min(...closes);
  const max = Math.max(...closes);
  const range = max - min || 1;
  const xs = closes.map((_, i) => PAD + (i / (closes.length - 1)) * (W - PAD * 2));
  const ys = closes.map((v) => PAD + (1 - (v - min) / range) * (H - PAD * 2));
  const polyline = xs.map((x, i) => `${x},${ys[i]}`).join(" ");
  const areaPath = `M${xs[0]},${H} ` + xs.map((x, i) => `L${x},${ys[i]}`).join(" ") + ` L${xs[xs.length - 1]},${H} Z`;
  const first = closes[0], last = closes[closes.length - 1];
  const pct = ((last - first) / first * 100).toFixed(1);
  const tone = last >= first ? "pos" : "neg";
  const firstDate = ordered[0]?.date;
  const lastDate = ordered[ordered.length - 1]?.date;
  const inspectedIndex = activeIndex == null
    ? null
    : Math.max(0, Math.min(activeIndex, ordered.length - 1));
  const inspectedPoint = inspectedIndex == null ? null : ordered[inspectedIndex];
  const inspectedClose = inspectedIndex == null ? null : closes[inspectedIndex];
  const previousClose = inspectedIndex > 0 ? closes[inspectedIndex - 1] : null;
  const sessionChange = previousClose
    ? ((inspectedClose - previousClose) / previousClose) * 100
    : null;
  const locale = language === "en" ? "en-US" : language === "uz" ? "uz-UZ" : "ru-RU";
  const chartLabel = language === "en"
    ? "Interactive price chart. Use the left and right arrow keys to inspect trading sessions."
    : language === "uz"
      ? "Interaktiv narx grafigi. Savdo sessiyalarini ko‘rish uchun chap va o‘ng tugmalardan foydalaning."
      : "Интерактивный график цены. Используйте стрелки влево и вправо для просмотра торговых сессий.";
  const sessionLabel = language === "en"
    ? "vs previous session"
    : language === "uz"
      ? "oldingi sessiyaga nisbatan"
      : "к предыдущей сессии";

  const inspectAtPointer = (event) => {
    const bounds = event.currentTarget.getBoundingClientRect();
    if (!bounds.width) return;
    const ratio = Math.max(0, Math.min(1, (event.clientX - bounds.left) / bounds.width));
    setActiveIndex(Math.floor((ratio * (ordered.length - 1)) + 0.5));
  };

  const inspectWithKeyboard = (event) => {
    if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return;
    event.preventDefault();
    setActiveIndex((current) => {
      if (event.key === "Home") return 0;
      if (event.key === "End") return ordered.length - 1;
      const start = current == null ? ordered.length - 1 : current;
      return Math.max(0, Math.min(
        ordered.length - 1,
        start + (event.key === "ArrowLeft" ? -1 : 1),
      ));
    });
  };

  return (
    <div className="catalog-sparkline">
      <div className="catalog-sparkline-meta">
        <span className="catalog-sparkline-price">{last.toLocaleString(language === "en" ? "en-US" : "ru-RU")} сум</span>
        <span className={`catalog-sparkline-change ${tone}`}>{tone === "pos" ? "+" : ""}{pct}%</span>
        <span className="catalog-sparkline-period muted">{firstDate} – {lastDate}</span>
      </div>
      <div
        className="catalog-sparkline-chart"
        role="group"
        tabIndex={0}
        aria-label={chartLabel}
        onPointerMove={inspectAtPointer}
        onPointerDown={inspectAtPointer}
        onPointerLeave={() => setActiveIndex(null)}
        onPointerCancel={() => setActiveIndex(null)}
        onFocus={() => setActiveIndex((current) => current ?? ordered.length - 1)}
        onBlur={() => setActiveIndex(null)}
        onKeyDown={inspectWithKeyboard}
      >
        <svg viewBox={`0 0 ${W} ${H}`} className="catalog-sparkline-svg" preserveAspectRatio="none" aria-hidden="true">
          <defs>
            <linearGradient id="catalog-spk-grad" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="var(--catalog-accent)" stopOpacity="0.3" />
              <stop offset="100%" stopColor="var(--catalog-accent)" stopOpacity="0.01" />
            </linearGradient>
          </defs>
          <path d={areaPath} fill="url(#catalog-spk-grad)" />
          <polyline points={polyline} fill="none" stroke="var(--catalog-accent)" strokeWidth="2" strokeLinejoin="round" strokeLinecap="round" />
          {inspectedIndex != null && (
            <>
              <line
                className="catalog-sparkline-guide"
                x1={xs[inspectedIndex]}
                y1={PAD}
                x2={xs[inspectedIndex]}
                y2={H}
              />
              <circle
                className="catalog-sparkline-active-dot"
                cx={xs[inspectedIndex]}
                cy={ys[inspectedIndex]}
                r="4"
              />
            </>
          )}
        </svg>
        {inspectedPoint && (
          <div
            className="catalog-sparkline-tooltip"
            role="tooltip"
            style={{ "--catalog-hover-x": `${(xs[inspectedIndex] / W) * 100}%` }}
          >
            <span>{formatCatalogDate(inspectedPoint.date, language)}</span>
            <strong>{inspectedClose.toLocaleString(locale)} сум</strong>
            {sessionChange != null && (
              <em className={sessionChange >= 0 ? "pos" : "neg"}>
                {sessionChange >= 0 ? "+" : ""}{sessionChange.toFixed(2)}% {sessionLabel}
              </em>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

function CatalogFilterSelect({ value, onChange, options, label, className = "" }) {
  const [open, setOpen] = useState(false);
  const selectedIndex = Math.max(0, options.findIndex((option) => option.value === value));
  const [activeIndex, setActiveIndex] = useState(selectedIndex);
  const listboxId = React.useId();
  const selectedOption = options[selectedIndex] || options[0];

  useEffect(() => {
    setActiveIndex(selectedIndex);
  }, [selectedIndex]);

  const choose = (index) => {
    const option = options[index];
    if (!option) return;
    onChange(option.value);
    setActiveIndex(index);
    setOpen(false);
  };

  const handleKeyDown = (event) => {
    if (event.key === "Escape") {
      setOpen(false);
      return;
    }
    if (["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) {
      event.preventDefault();
      setOpen(true);
      setActiveIndex((current) => {
        if (event.key === "Home") return 0;
        if (event.key === "End") return options.length - 1;
        const direction = event.key === "ArrowDown" ? 1 : -1;
        return Math.max(0, Math.min(options.length - 1, current + direction));
      });
      return;
    }
    if ((event.key === "Enter" || event.key === " ") && open) {
      event.preventDefault();
      choose(activeIndex);
    }
  };

  return (
    <div
      className={`catalog-filter-control ${open ? "is-open" : ""} ${className}`.trim()}
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) setOpen(false);
      }}
    >
      <button
        className="catalog-filter-trigger"
        type="button"
        aria-label={label}
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={listboxId}
        onClick={() => setOpen((current) => !current)}
        onKeyDown={handleKeyDown}
      >
        <span>{selectedOption?.label || label}</span>
        <svg viewBox="0 0 16 16" aria-hidden="true"><path d="m4 6 4 4 4-4" /></svg>
      </button>
      {open && (
        <div className="catalog-filter-menu" id={listboxId} role="listbox" aria-label={label}>
          {options.map((option, index) => (
            <button
              key={option.value}
              className={`${index === activeIndex ? "is-highlighted" : ""} ${option.value === value ? "is-selected" : ""}`.trim()}
              type="button"
              role="option"
              aria-selected={option.value === value}
              onMouseEnter={() => setActiveIndex(index)}
              onMouseDown={(event) => event.preventDefault()}
              onClick={() => choose(index)}
            >
              <span>{option.label}</span>
              {option.value === value && (
                <svg viewBox="0 0 16 16" aria-hidden="true"><path d="m3.5 8.5 3 3 6-7" /></svg>
              )}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

